insert into public.landmarks (slug, name, description, category, latitude, longitude, geofence_radius_m, geofence_polygon, address, neighbourhood, source_name, source_url, source_license, source_record_id, needs_review, review_note, is_active) values
  ('edifice-de-la-eastern-townships-bank', 'Édifice de la Eastern Townships Bank', 'Cet édifice, œuvre de l’agence d’architectes Cox et Amos, est construit entre 1907 et 1909 par la Eastern Township Bank. Le rez-de-chaussée loge au départ les bureaux montréalais de la Eastern Township Bank, une banque fondée à Sherbrooke en 1859. Les étages supérieurs hébergent entre autres des compagnies d’assurances, la firme de courtage de Louis-Joseph Forget, les bureaux de la Canadian Car and Foundry Company et le consulat américain. En 1912, la Canadian Bank of Commerce devient propriétaire de l’immeuble en faisant l’acquisition de la Eastern Township Bank.', 'architecture', 45.5016, -73.5605, 60, null::extensions.geography, '437 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-09-3563-00', false, null, true),
  ('immeuble-joseph-ulric-cartier', 'Immeuble Joseph-Ulric-Cartier', 'Dès les années 1900, le restaurateur Joseph-Ulric Cartier loue un espace dans un petit immeuble situé sur la rue Notre-Dame. En février 1907, il achète l''immeuble de Ida Torrence et John Travis et y poursuit ses activités commerciales. Trois ans plus tard, Cartier fait démolir son immeuble et confie à l''architecte Charles Bernier la conception d''un nouvel édifice de cinq étages. L''immeuble est construit en 1911 et, dès 1912, il accueille ses nouveaux locataires. À la barre du Florence , Cartier poursuit son métier de restaurateur au rez-de-chaussée.', 'historic', 45.5008, -73.5595, 50, null::extensions.geography, '484-488 rue McGill', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-18-1875-00', false, null, true),
  ('entrepot-james-adams-mathewson', 'Entrepôt James-Adams-Mathewson', 'Cet entrepôt à l''origine en pierre de trois étages est construit vers 1865. L''épicier Samuel Mathewson acquiert en 1853 cet emplacement donnant sur la rue de Longueuil avec une étable ou une dépendance. Tout indique que son fils James Adams, qui hérite de la propriété en 1854, fait construire entre 1855 et 1880 un bâtiment similaire à l''immeuble contigu au sud lui appartenant. Le nouveau bâtiment sert d''entrepôt à l''entreprise des Mathewson, spécialisée dans la vente en gros et au détail de produits d''épicerie, jusqu''en 1946.', 'historic', 45.5006, -73.5593, 50, null::extensions.geography, 'None rue De Longueuil', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-18-3358-02', false, null, true),
  ('maison-magasin-samuel-mathewson', 'Maison-magasin Samuel-Mathewson', 'L''épicier Samuel Mathewson fait construire cette maison-magasin en 1841. Mathewson avait acquis en juillet de cette même année la moitié d''un emplacement appartenant en son entier à John Mathewson et la moitié d''un magasin en pierre donnant sur la rue de Longueuil. À l''instar de bâtiments semblables, cette maison-magasin est conçue pour servir à des fins résidentielles et commerciales. Mathewson établit son magasin au rez-de-chaussée et sa résidence au-dessus. Au décès de Samuel Mathewson en avril 1854, son fils James Adams hérite de la propriété et suit les traces de son père.', 'historic', 45.5007, -73.5591, 50, null::extensions.geography, '468-470 rue McGill', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-18-4254-01', false, null, true),
  ('immeuble-john-mathewson', 'Immeuble John-Mathewson', 'Le fabricant de savon et de chandelles John Mathewson fait bâtir ce magasin à l''origine en pierre de trois étages en 1837-1838. Mathewson avait acquis à l''automne 1836 un grand emplacement vacant comprenant aujourd''hui les terrains des immeubles au 468-470 et au 464, rue McGill. Le nouvel immeuble décrit dans les contrats notariés comme une maison, un hangar ou un magasin, sert probablement dès le départ de lieu d''entreposage et de magasin pour l''entreprise de Mathewson. L''épicier Samuel Mathewson achète la moitié nord de l''emplacement et du magasin en 1841.', 'historic', 45.5005, -73.5592, 50, null::extensions.geography, 'None rue De Longueuil', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-18-4254-02', false, null, true),
  ('magasin-entrepot-charles-phillips', 'Magasin-entrepôt Charles-Phillips', 'L’édifice porte le nom du constructeur de l’édifice, même si celui-ci n’est propriétaire que pendant deux ans. Charles Phillips achète en 1869 un lot sur lequel est érigé un bâtiment de petite dimension ne couvrant que la moitié du terrain. On y retrouve un magasin de tissu et deux logements. Phillips démolit rapidement ce bâtiment et ses dépendances, et construit ensuite en 1870 un magasin entrepôt de quatre étages couvrant tout le lot. La fonction résidentielle disparaît par le fait même.', 'historic', 45.5006, -73.5591, 50, null::extensions.geography, '464 rue McGill', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-18-5050-00', false, null, true),
  ('magasin-entrepot-george-burland', 'Magasin-entrepôt George-Burland', 'L’homme d’affaires George B. Burland fait construire ce magasin-entrepôt en 1886-1887. Burland acquiert la propriété du shérif du district de Montréal en juin 1886. La maison-magasin en pierre de trois étages et demi qui s’y trouve est probablement démolie peu de temps après. Terminé vers le début du printemps 1887, l’immeuble demeure la propriété de la famille Burland jusqu’au début des années 1950. La Charles Morton & Co., des marchands en gros de dry goods (tissus, articles de mercerie et, parfois, autres produits), loue tout le bâtiment entre 1887 et 1889.', 'historic', 45.5005, -73.559, 50, null::extensions.geography, '460 rue McGill', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-18-5746-00', false, null, true),
  ('hotel-ottawa', 'Hôtel Ottawa', 'Parmi les hôtels de première classe construits pendant les années 1840 — notamment le Ottawa, le Donegana, le Hays'' House et le St-Lawrence Hall — il ne subsiste aujourd''hui que l''immeuble de l''Hôtel Ottawa. Après l''acquisition du terrain vacant par vente de shérif en 1845 (les anciens bâtiments ayant été démolis par le propriétaire précédent), le marchand Harrison Stephens procédait immédiatement à la construction d''un nouvel hôtel de luxe.', 'historic', 45.5016, -73.5597, 50, null::extensions.geography, '404-410 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-19-0864-01', false, null, true),
  ('edifice-de-la-sovereign-bank', 'Édifice de la Sovereign Bank', 'Ce gratte-ciel est construit en 1904-1905 par la Sovereign Bank. Oeuvre de l’architecte américain Howard Colton Stone, il atteint 10 étages et dépasse de quelques pieds le maximum alors autorisé (130 pieds). Il remplace un magasin-entrepôt de trois étages qui a longtemps appartenu au notaire Étienne Guy et à ses héritiers. La Sovereign Bank occupe les deux premiers étages de l’immeuble de bureaux dès le printemps 1905. Aux étages supérieurs, on retrouve principalement des bureaux d’entreprises, mais on note aussi la présence de bureaux d’avocats, de notaires, de courtiers et d’un consulat.', 'architecture', 45.5019, -73.5596, 60, null::extensions.geography, '388-390 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-19-1496-00', false, null, true),
  ('magasin-entrepot-alfred-larocque-1867', 'Magasin-entrepôt Alfred-Larocque [1867]', 'François-Alfred Chartier Laroque fait construire ce magasin-entrepôt en 1867-1868. Une série de bâtiments sont démolis en 1867 pour permettre l’élargissement de la rue Notre-Dame, à l’ouest de la rue St-Pierre. La maison-magasin appartenant à Laroque, fils de l’important homme d’affaires montréalais François-Antoine Larocque, fait partie de cette série d’immeubles. Laroque entreprend donc aussitôt la construction d’un nouveau magasin-entrepôt en pierre de taille de quatre étages. En 1868, les travaux sont terminés et les deux espaces locatifs du magasin sont occupés.', 'historic', 45.5016, -73.5594, 50, null::extensions.geography, '399-401 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-19-1578-02', false, null, true),
  ('magasin-entrepot-joseph-tiffin-1872', 'Magasin-entrepôt Joseph-Tiffin [1872]', 'En février 1872, Joseph Tiffin père achète un lot vacant. Il y fait immédiatement ériger un magasin-entrepôt de quatre étages. Le premier et seul occupant en 1873 est le marchand de tissus Alexander A. Murphy, remplacé avant la fin de la décennie par un marchand de meubles, S. R. Parsons, qui loue le bâtiment jusqu''à la fin du XIXe siècle. Vers 1903, l''imprimeur, fabricant et importateur d''articles de bureau Charles F. Dawson y installe son commerce. Il occupe l''immeuble pendant 70 ans, mais n''en sera jamais propriétaire.', 'historic', 45.5018, -73.5592, 50, null::extensions.geography, '387-389 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-19-3889-00', false, null, true),
  ('edifice-mcgill', 'Édifice McGill', 'Sur un emplacement acquis de F.W. Molson et associés, la McGill Building Ltd fait construire cet immeuble locatif de dix étages en 1912. Trois immeubles, datant du milieu du XIXe siècle et logeant des commerces et des entreprises sont démolis pour faire place au nouveau projet élaboré d''après les plans de l''architecte Robert Ernest Bostrom. L''immeuble compte pour locataires un nombre important de compagnies d''assurance, mais aussi quelques bureaux d''avocats et des courtiers en douane, des caractéristiques qui sont présentes durant une bonne partie du XXe siècle.', 'architecture', 45.5011, -73.5592, 60, null::extensions.geography, '485 rue McGill', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-19-4308-00', false, null, true),
  ('magasin-entrepot-ramsay', 'Magasin-entrepôt Ramsay', 'En 1858, M. Alexander Ramsay fait construire cet immeuble après avoir acheté la même année un lot vacant de la veuve Rose Blache. Le bâtiment compte trois étages, incluant le rez-de-chaussée, ainsi qu''un attique muni de petites fenêtres intégrées à la frise, probablement sous une toiture en pente invisible de la rue . À la fin des années 1860, l''attique sera remplacé par deux nouveaux étages et une mansarde. Au lendemain de la construction, A. Ramsay & Son s’installe dans l’immeuble.', 'historic', 45.5012, -73.5589, 50, null::extensions.geography, '415-419 rue des Récollets', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-19-6018-00', false, null, true),
  ('maison-magasin-james-ferrier', 'Maison-magasin James-Ferrier', 'L’homme d’affaires et politicien James Ferrier fait construire un ensemble de trois maisons-magasins au cours de l’année 1842, dont il ne reste plus que l’immeuble le plus à l’est, au coin des rues Notre-Dame et Sainte-Hélène. En juin, Ferrier acquiert l’emplacement sans bâtiments. Dès le mois de décembre, il conclut un bail pour le printemps suivant de la maison-magasin la plus à l’ouest, ce qui suggère que tout le bloc de bâtiments est construit.', 'historic', 45.5015, -73.5589, 50, null::extensions.geography, '400 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-19-6156-00', false, null, true),
  ('magasin-entrepot-johnston', 'Magasin-entrepôt Johnston', 'En novembre 1866, par l’intermédiaire de ses syndics, la communauté presbytérienne de l’église Saint-Paul vend à James Johnston sa propriété au coin nord-ouest des rues Sainte-Hélène et des Récollets. Dans les mois qui suivent, M. Johnston fait démolir l’église et un bâtiment servant d’école qui se trouvent sur les lieux, afin d’y ériger un magasin-entrepôt de quatre étages avec sous-sol. La conception architecturale est confiée à Alexander Cowper Hutchison, et la construction a lieu en 1868.', 'historic', 45.5013, -73.5588, 50, null::extensions.geography, '450 rue Sainte-Hélène', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-19-7137-00', false, null, true),
  ('magasin-entrepot-anglo-canadian-leather', 'Magasin-entrepôt Anglo-Canadian Leather', 'C''est en 1910-1911 que l''entreprise familiale de grossistes et tanneurs de cuir Anglo-Canadian Leather fait construire ce magasin-entrepôt. Conçu pour communiquer avec l''autre magasin-entrepôt adjacent de la compagnie (édifice Shaw), sa réalisation est confiée à l''architecte alors bien en vue Robert Findlay. L''édifice Anglo-Canadian Leather constitue un exemple tardif de magasins-entrepôts réalisé dans le Vieux-Montréal.', 'historic', 45.5018, -73.5587, 50, null::extensions.geography, '372-376 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-19-8380-01', false, null, true),
  ('magasins-entrepots-jacob-henry-joseph-1863-1864', 'Magasins-entrepôts Jacob-Henry-Joseph [1863-1864]', 'En 1863, Jacob Henry Joseph achète un terrain vacant de H. C. Hart. Il y fait construire trois magasins-entrepôts, chacun comprenant quatre étages et un sous-sol. Les travaux débutent à la fin de l’année 1863, sous la direction de l’architecte James Henry Wells, et se terminent en 1864. Ce sont ces trois magasins-entrepôts qui correspondent à l’actuel 442-446 Sainte-Hélène. Jacob Henry Joseph et sa succession conservent la propriété du bâtiment jusqu’au milieu du XXe siècle. Avec ses trois espaces commerciaux, l’immeuble compte trois occupants d’origine.', 'historic', 45.5012, -73.5585, 50, null::extensions.geography, '442-446 rue Sainte-Hélène', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-19-9919-00', false, null, true),
  ('maisons-magasins-jacob-de-witt-i', 'Maisons-magasins Jacob-De Witt I', 'L''homme d''affaires et banquier Jacob De Witt fait construire un ensemble comprenant trois maisons-magasins en 1846, sur un terrain qu''il a acquis seize ans plus tôt avec un hangar donnant sur la rue de Longueuil. Il engage le maçon David Brown pour lui construire les bâtiments d''après les plans de l''architecte Moses Marshall. Cet immeuble compte deux des trois maisons-magasins initialement bâties. À l''instar de bâtiments semblables, celles-ci sont vouées au départ au commerce et à l''habitation.', 'historic', 45.5001, -73.5579, 50, null::extensions.geography, '412-414 rue McGill', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-27-4599-00', false, null, true),
  ('magasins-entrepots-margaret-benny', 'Magasins-entrepôts Margaret-Benny', 'Margaret Benny, la veuve du marchand et industriel Thomas Peck, fait construire cet immeuble en 1880-1881. Il est composé de trois magasins-entrepôts, lesquels logent au départ un locataire chacun. Parmi les occupants d’origine, on retrouve entre autres un grossiste de chapeaux et de fourrures, un commerce d’alimentation et, à partir de 1882, un fabricant d’articles de papier. Entre 1964 et 1975, le magasin-entrepôt au sud perd deux étages. On reconstruit ces deux étages en 1991 lors d’importants travaux de restauration. Le bâtiment est alors transformé en immeuble de bureaux.', 'historic', 45.5002, -73.5581, 50, null::extensions.geography, '420 rue McGill', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-28-2609-00', false, null, true),
  ('maison-magasin-jacob-de-witt-ii', 'Maison-magasin Jacob-De Witt II', 'L''homme d''affaires et banquier Jacob De Witt fait construire un ensemble comprenant trois maisons-magasins en 1846, sur un terrain qu''il a acquis seize ans plus tôt avec un hangar donnant sur la rue de Longueuil. Il fait appel au maçon David Brown pour lui construire l''ensemble selon les plans de l''architecte Moses Marshall. Cet immeuble comprend la maison-magasin la plus au nord de l''ensemble. Comme d''autres bâtiments semblables, celle-ci est dédiée au départ au commerce et à l''habitation. En 1847, les marchands en gros Kershaw & Whitenhall en sont les premiers locataires.', 'historic', 45.5001, -73.558, 50, null::extensions.geography, '416 rue McGill', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-28-3703-00', false, null, true),
  ('edifice-shaughnessy', 'Édifice Shaughnessy', 'L''édifice Shaughnessy doit son nom à sir Thomas Shaughnessy qui acquiert, au début du XXe siècle, une propriété située sur la rue McGill, propriété sur laquelle, quelques mois avant d''entreprendre la nouvelle construction, étaient érigés deux hôtels. Shaughnessy est président de la Canadian Pacific Railway Co., mais il est aussi président de la firme Dorchester Realties à laquelle il transfert les titres de propriété en 1912.', 'architecture', 45.5005, -73.5573, 60, null::extensions.geography, '401-407 rue McGill', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-28-8742-00', false, null, true),
  ('magasin-entrepot-jesse-joseph-iv', 'Magasin-entrepôt Jesse-Joseph IV', 'Ce magasin-entrepôt fait partie d’une série de cinq bâtiments construits en 1857 par Jesse Joseph, marchand et consul de Belgique, d''après les plans de l''architecte James H. Springle. C’est en 1853 que Jesse Joseph s’est porté acquéreur d’un terrain sur la rue Le Moyne sur lequel se trouvent alors des hangars en bois entourant une cour intérieure. Le magasin-entrepôt compte à l’origine trois étages complets et un quatrième étage attique. Trois autres magasins-entrepôts compléteront ensuite l''ensemble dont Jesse Joseph demeurera propriétaire jusqu’à sa mort, en 1904.', 'historic', 45.5008, -73.5573, 50, null::extensions.geography, '390 rue Le Moyne', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-28-9082-00', false, null, true),
  ('magasin-entrepot-jesse-joseph-iii', 'Magasin-entrepôt Jesse-Joseph III', 'Ce magasin-entrepôt est construit en 1857, avec quatre autres semblables, par Jesse Joseph, marchand et consul de Belgique, d''après des plans de l''architecte James H. Springle. C’est en 1853 que Jesse Joseph s’est porté acquéreur d’un terrain, rue Le Moyne, sur lequel se trouvent alors des hangars en bois entourant une cour intérieure. À l’origine, le magasin-entrepôt compte trois étages, incluant le rez-de-chaussée, ainsi qu’un quatrième étage attique. Trois autres magasins-entrepôts compléteront ensuite l''ensemble dont Jesse Joseph demeurera propriétaire jusqu’à sa mort, en 1904.', 'historic', 45.5009, -73.5572, 50, null::extensions.geography, '386 rue Le Moyne', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-28-9589-00', false, null, true),
  ('magasin-entrepot-gault-brothers', 'Magasin-entrepôt Gault Brothers', 'Le commerce de la Gault Brothers Co. connaissant une forte expansion, les frères Gault retiennent les services de l’architecte John James Browne afin de construire un nouvel immeuble pour abriter leurs bureaux et salles de montre. Le terrain convoité pour ce projet se trouve en face des anciens locaux de la Gault Brothers Co. Andrew Frederick Gault l’achète en 1870 de la succession Olivier Théophile Bruneau. Au moment de la transaction, un vieil immeuble en pierre de trois étages occupe une partie du lot. Le bâtiment et ses dépendances sont aussitôt démolis.', 'historic', 45.5015, -73.5582, 50, null::extensions.geography, '447-449 rue Sainte-Hélène', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-29-1958-00', false, null, true),
  ('immeuble-jesse-joseph-vi', 'Immeuble Jesse-Joseph VI', 'L’homme d’affaires Jesse Joseph fait construire cet immeuble en 1884-1885. Entre 1885 et 1898, la confiserie James W. Tester and Co. occupe ce bâtiment ainsi que l’immeuble voisin au sud. La compagnie emploie environ 80 personnes dans ces deux bâtiments, produisant des produits chocolatiers, des caramels et autres confiseries. En 1903, l’immeuble subit d’importants dommages lors d’un incendie : le toit d’origine, en fausse mansarde, disparaît fort probablement à ce moment.', 'historic', 45.4995, -73.5559, 50, null::extensions.geography, '122-124 rue McGill', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-37-9931-00', false, null, true),
  ('magasin-entrepot-jesse-joseph-ii', 'Magasin-entrepôt Jesse-Joseph II', 'Jesse Joseph, marchand et consul de Belgique, acquiert en 1853 un grand terrain situé sur la rue Le Moyne. Sur ce terrain se trouvaient des hangars de bois entourant une cour intérieure. Joseph décide d’y faire construire, en 1857, une série de cinq magasins-entrepôts conçus par l''architecte James H. Springle, dont quatre subsistent aujourd’hui : les 370, 376, 386 et 390 Le Moyne. Avec le 366 Le Moyne et les 373 et 377 Saint-Paul Ouest, ils forment l’ensemble magasin-entrepôt Joseph.', 'historic', 45.501, -73.5571, 50, null::extensions.geography, '376 rue Le Moyne', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-38-1697-01', false, null, true),
  ('magasin-entrepot-jesse-joseph-vi', 'Magasin-entrepôt Jesse-Joseph VI', 'Ce bâtiment fait partie d''un ensemble formé de cinq unités situées rue LeMoyne et deux unités contigües rue St-Paul O. Jesse Joseph possède déjà depuis cinq ans un immeuble de bureaux à l''emplacement de l''actuel 377 St-Paul O., lorsqu’il décide en 1858 de le faire démolir et de construire ce magasin-entrepôt, comptant trois étages et un attique. Contrairement à tous les autres magaisns-entrepôts de l''ensemble, qui n''ont qu''un occupant à l''origine, celui-ci en accueille trois dès 1859.', 'historic', 45.5009, -73.5568, 50, null::extensions.geography, '377 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-38-1697-02', false, null, true),
  ('edifice-de-la-canadian-express', 'Édifice de la Canadian Express', 'Cet édifice, oeuvre de l’agence d’architectes Hutchison and Wood, est construit entre l’automne 1906 et le printemps 1908 par la compagnie ferroviaire du Grand Tronc. Les terrains sont acquis en 1905-1906 par le Grand Tronc, puis les bâtiments qui s’y trouvent sont démolis pour faire place à un élégant gratte-ciel de dix étages, le maximum alors autorisé. L’édifice possède cependant une structure d’acier suffisamment solide pour ajouter, lorsque la réglementation municipale le permettra, d’autres étages.', 'architecture', 45.5003, -73.5567, 60, null::extensions.geography, '351-355 rue McGill', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-38-3220-00', false, null, true),
  ('magasin-entrepot-jesse-joseph-v', 'Magasin-entrepôt Jesse-Joseph V', 'Ce bâtiment fait partie d''un ensemble formé de cinq unités situées rue LeMoyne et deux unités contigües rue St-Paul O. Jesse Joseph possède déjà depuis cinq ans un bâtiment commercial à l''emplacement de l''actuel 373 St-Paul O., lorsqu’il décide en 1858 de le faire démolir et de construire ce magasin-entrepôt comptant trois étages et un attique. Le nouveau bâtiment accueille son premier occupant en 1859 : le commerce en gros de quincaillerie Foley & Co. louera l''immeuble jusqu’en 1862.', 'historic', 45.501, -73.5567, 50, null::extensions.geography, '373 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-38-3297-00', false, null, true),
  ('immeuble-ward', 'Immeuble Ward', 'Cet immeuble est construit en 1905-1906 par Joseph Ward, grossiste en alimentation et échevin de la Ville de Montréal entre 1904 et 1918. Conçu par l’agence d’architectes J. Wright and Son, il loge à l’origine les bureaux de la Joseph Ward Company Limited, un commerce de fournitures électriques et un fabricant d’articles de papier. La Joseph Ward Company Limited quitte en 1924, mais la succession de Joseph Ward conserve les titres de propriété jusqu’en 1994. En 2005, on entame la transformation de l’immeuble en copropriétés (Europa Place d’Youville).', 'historic', 45.5008, -73.5562, 50, null::extensions.geography, '361-363 place D''Youville', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-38-7079-02', false, null, true),
  ('magasin-entrepot-jesse-joseph-i', 'Magasin-entrepôt Jesse-Joseph I', 'Ce magasin-entrepôt fait partie d’une série de cinq bâtiments construits en 1857 par Jesse Joseph, marchand et consul de Belgique, d''après les plans de l''architecte James H. Springle. C’est en 1853 que Jesse Joseph s’est porté acquéreur d’un terrain sur la rue Le Moyne sur lequel se trouvaient alors des hangars en bois entourant une cour intérieure. Le magasin-entrepôt compte à l’origine trois étages complets et un quatrième étage attique. Trois autres magasins-entrepôts compléteront ensuite l''ensemble dont Jesse Joseph demeurera propriétaire jusqu’à sa mort, en 1904.', 'historic', 45.5011, -73.557, 50, null::extensions.geography, '370 rue Le Moyne', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-39-0911-00', false, null, true),
  ('magasin-entrepot-jesse-joseph-vii', 'Magasin-entrepôt Jesse-Joseph VII', 'Jesse Joseph, un important homme d’affaires montréalais, acquiert, en 1853, un terrain au coin des rues Le Moyne et Saint-Pierre. Sur ce terrain se trouvent alors quatre bâtiments en pierre dont deux qui sont réunis. Sur le terrain, Jesse Joseph entreprend, en 1863-1864, la construction du 366 Le Moyne. Ce bâtiment forme, avec six autres magasins-entrepôts, l’ensemble Joseph. Le magasin-entrepôt est construit sur le même modèle que les bâtiments voisins sur Le Moyne, ce qui nous porte à croire qu''il a été construit d''après les plans de l''architecte James H.', 'historic', 45.5012, -73.557, 50, null::extensions.geography, '366 rue Le Moyne', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-39-1121-00', false, null, true),
  ('magasin-entrepot-donald-ross-ii', 'Magasin-entrepôt Donald-Ross II', 'Ce magasin-entrepôt de trois étages a été construit en 1859-1860 par la succession Ross et par Donald Ross, un des co-héritiers de cette succession. La succession acquiert la propriété avant 1858 et amorce en 1859 un projet que Donald Ross mènera à terme l’année suivante. C’est la succession qui semble avoir fait démolir un bâtiment commercial situé sur ce terrain et qui aurait entrepris la construction d’un nouveau magasin-entrepôt. Donald Ross est toutefois propriétaire lorsque le premier locataire s’y installe en 1860.', 'historic', 45.501, -73.5567, 50, null::extensions.geography, '367-369 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-39-3606-00', false, null, true),
  ('magasin-entrepot-donald-ross-i', 'Magasin-entrepôt Donald-Ross I', 'Ce magasin-entrepôt de même que son voisin a été construit par l’homme d’affaires montréalais Donald Ross. Ross hérite d’un bâtiment commercial sis sur ce terrain, le fait démolir et entreprend la construction d’un nouvel immeuble de trois étages en 1860. Ross n’occupe jamais l’immeuble mais en conserve la propriété jusqu’à son décès au début des années 1870. Plus tard, il sera légué au Trafalgar Institute, une école privée pour jeunes filles établie grâce à la générosité de Ross.', 'historic', 45.5011, -73.5566, 50, null::extensions.geography, '361-365 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-39-4015-00', false, null, true),
  ('edifice-beardmore', 'Édifice Beardmore', 'En 1899, la firme Beardmore & Co. se porte acquéreur d''un immeuble érigé sur un terrain, propriété de la succession James S. Evans. En 1901, un incendie détruit le bâtiment et les propriétaires mandatent l''architecte Howard Colton Stone pour la construction d''un entrepôt de sept étages, en pierre et en brique. Terminé en 1903, l''immeuble reprend les règles de la colonne antique : une structure en trois registres composée d''une base (socle), d''un fût (étages intermédiaires) et d''un chapiteau. Un modèle de référence qui s''impose à l''époque. Cette année-là, la Beardmore & Co.', 'historic', 45.5017, -73.5566, 50, null::extensions.geography, '417-419 rue Saint-Pierre', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-39-4272-00', false, null, true),
  ('immeuble-john-fisher', 'Immeuble John-Fisher', 'Le marchand John Fisher fait bâtir cet immeuble en 1834. Propriétaire de l’emplacement avec deux vieilles maisons et leurs dépendances depuis 1832, Fisher engage les maçons entrepreneurs William Lauder et William Spiers ainsi que le charpentier Olivier Fréchette pour lui construire le nouveau bâtiment. Les épiciers Neil et Robertson McIntosh sont les premiers occupants de la moitié nord de l’immeuble. Ils y tiennent leur épicerie et, bien qu’aucune source n’ait pu le confirmer, ils habitent probablement dans des logements aux étages.', 'historic', 45.5012, -73.5565, 50, null::extensions.geography, '351-355 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-39-5123-00', false, null, true),
  ('immeuble-coristine', 'Immeuble Coristine', 'Cet immeuble est construit en trois étapes. La première débute en 1901 pour se terminer en 1902, la seconde a lieu en 1904 et la troisième se déroule en 1907. L’architecte d’origine américaine Howard Colton Stone supervise l’ensemble des travaux. En janvier 1901, les bâtiments abritant le commerce de fourrures de la James Coristine & Co. passent au feu lors du grand incendie du quartier Ouest du Vieux-Montréal. Suite à la catastrophe, James Coristine décide de construire un nouvel immeuble où il pourra non seulement loger son entreprise, mais aussi louer des espaces de bureaux.', 'historic', 45.5018, -73.5562, 50, null::extensions.geography, '290 rue Le Moyne', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-39-7693-00', false, null, true),
  ('maison-magasin-francois-benoit', 'Maison-magasin François-Benoît', 'L''aubergiste François Benoît acquerrait ce terrain en 1843, mais il conserva les anciennes bâtisses (deux immeubles à deux étages dont une maison de pierre et une autre de brique) jusqu''en 1849. Cette année-là il engageait le maçon Vital Gibault pour construire un nouvel édifice de pierre taillée à trois étages. La mort subite de Gibault, à peine quelques semaines après la signature du marché, força Benoît à engager François-Xavier Boucher et Étienne Couturier dit Lajoie afin de compléter l''immeuble.', 'historic', 45.5012, -73.556, 50, null::extensions.geography, '320-326 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-39-8924-00', false, null, true),
  ('immeuble-jesse-joseph-v', 'Immeuble Jesse-Joseph V', 'L’homme d’affaires Jesse Joseph fait construire cet immeuble en 1884-1885. Entre 1885 et 1898, la confiserie James W. Tester and Co. occupe ce bâtiment ainsi que l’immeuble voisin au nord. La compagnie emploie environ 80 personnes dans ces deux bâtiments, produisant des produits chocolatiers, des caramels et autres confiseries. En 1903, l’immeuble subit d’importants dommages lors d’un incendie : le toit d’origine, en fausse mansarde, disparaît fort probablement à ce moment.', 'historic', 45.4995, -73.5558, 50, null::extensions.geography, '120 rue McGill', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-47-0728-00', false, null, true),
  ('edifice-des-douanes', 'Édifice des Douanes', 'Au début des années 1910, le gouvernement du Canada obtient des soeurs Grises le terrain nécessaire pour ériger son nouvel édifice des douanes. Les bâtiments démolis en 1911 servaient à des marchands de grain et de charbon. On y retrouvait aussi un modeste édifice des douanes du gouvernement fédéral. Cet ensemble disparate avait été érigé au début des années 1870 au moment de l''ouverture de la rue Normand. Les travaux de construction du nouvel immeuble sont exécutés sous la direction du Ministère des travaux publics, mais les architectes E.L.', 'historic', 45.4998, -73.5554, 50, null::extensions.geography, '400 place D''Youville', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-47-6466-00', false, null, true),
  ('magasins-des-soeurs-grises-iii', 'Magasins des soeurs Grises III', 'C''est en 1874 que les sœurs Grises confient à l''architecte Michel Laurent la construction de ce bâtiment qui comprend six magasins-entrepôts mitoyens. L''immeuble occupe des lots compris entre l''Ancien Hôpital général et la rue Saint-Pierre. Jusqu''à 1980, la proximité du port attire plusieurs grossistes et distributeurs qui utilisent les locaux comme entrepôts. Parmi ceux-ci, citons l''importateur de tissus E. W. Mudge, présent durant 70 ans, ainsi que le fabricant et marchand de cordages, de ficelles, de toiles et de voiles pour bateaux, Gourock Ropework Export Co.', 'historic', 45.5006, -73.5551, 50, null::extensions.geography, 'None place D''Youville', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-48-7126-01', false, null, true),
  ('ancien-hopital-general-de-montreal', 'Ancien hôpital général de Montréal', 'L''Hôpital Général se distingue comme étant le plus vieil immeuble dans l''arrondissement historique après le Vieux Séminaire. La survie du bâtiment ne fut cependant pas toujours assurée : la dissolution de la communauté fondatrice au début du XVIIIe siècle, des incendies en 1765 et 1900 et l''expansion des activités commerciales reliées au port à partir du milieu du XIXe siècle ont tour à tour menacé l''existence de l''immeuble.', 'historic', 45.5003, -73.555, 50, null::extensions.geography, '138-146 rue Saint-Pierre', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-48-7126-02', false, null, true),
  ('magasins-des-soeurs-grises-i', 'Magasins des soeurs Grises I', 'En 1872-1873, les sœurs Grises font construire, sous la supervision de l''architecte Michel Laurent, un bâtiment qui comprend 11 magasins-entrepôts mitoyens. Les six unités à partir de la place d''Youville sont réalisées en 1872 tandis que les cinq autres unités au sud sont complétées l''année suivante. Deux autres bâtiments, aujourd''hui démolis, sont construits en 1873 sur le terrain arrière. Pendant près de un siècle, de nombreux locataires oeuvrant dans divers secteurs d''activités occupent l''immeuble.', 'historic', 45.5008, -73.5548, 50, null::extensions.geography, '127-147 rue Saint-Pierre', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-48-9183-00', false, null, true),
  ('entrepot-hubert-pare', 'Entrepôt Hubert-Paré', 'Le marchand Hubert Paré fait construire cet entrepôt vers 1843. Paré et son épouse, Justine Vinet dit Souligny, héritent de la propriété avec un entrepôt de deux étages en 1842. Un bail de février 1845 confirme la présence du bâtiment de quatre étages. Les marchands généraux J.& T. Gordon en sont, selon toute vraisemblance, les premiers occupants. L''immeuble qui sert à des fins d''entreposage est brièvement utilisé par les douanes puis par des firmes de marchands au cours des décennies 1850 à 1870.', 'historic', 45.5016, -73.5544, 50, null::extensions.geography, '130 rue du Port', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-49-8945-03', false, null, true),
  ('gare-de-la-montreal-southern-counties-railway-co', 'Gare de la Montreal Southern Counties Railway Co.', 'Cette gare est construite en 1923 par le Canadien National pour les besoins d’une de ses filiales, la Montreal Southern Counties Railway (MSCRy). Elle remplace la première gare de la MSCRy, construite vers 1909. La MSCRy offre deux services distincts. D’une part, un train de banlieue relie Montréal et des villes de la Rive-Sud, dont Saint-Lambert, Longueuil et Greenfield Park. D’autre part, un interurbain assure la liaison avec Granby via un réseau de villes régionales. Les deux lignes ferroviaires terminent leurs trajets au terminus de la rue McGill après avoir franchi le pont Victoria.', 'historic', 45.499, -73.5542, 50, null::extensions.geography, '600 rue Marguerite-D''Youville', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-56-6927-00', false, null, true),
  ('magasins-des-soeurs-grises-iv', 'Magasins des soeurs Grises IV', 'Vers le milieu des années 1870, les soeurs Grises confient à l''architecte Michel Laurent l''élaboration de plans pour la construction d''un nouveau bâtiment dans les anciens jardins de la communauté. L''immeuble, dont la volumétrie est la plus importante de l''ensemble des magasins des sœurs Grises, est construit en 1874-1875. Il comprend cinq magasins-entrepôts mitoyens, tous identiques hormis celui longeant la rue d''Youville, deux fois plus grand que les autres.', 'historic', 45.5, -73.5544, 50, null::extensions.geography, '355-367 rue Marguerite-D''Youville', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-57-3693-00', false, null, true),
  ('magasins-des-soeurs-grises-ii', 'Magasins des soeurs Grises II', 'Ce magasin-entrepôt est construit d’avril à juin 1873 selon les plans de l’architecte Michel Laurent. Son premier locataire, la Hudson’s Bay Co., utilise les lieux comme entrepôt pendant un peu moins de 10 ans. Le bâtiment demeure ensuite plus ou moins occupé jusqu’à la fin du XIXe siècle. En 1896, le magasin-entrepôt connaît un changement important de fonction alors que le Catholic Sailors’ Club loue tout le bâtiment et aménage des salles de lecture, un club social, des bureaux et même un petit musée.', 'historic', 45.5004, -73.5537, 50, null::extensions.geography, '329 rue de la Commune Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-58-6532-02', false, null, true),
  ('edifice-des-commissaires', 'Édifice des Commissaires', 'L''édifice des Commissaires a été érigé sur un terrain acquis par le gouvernement fédéral en 1870. Il est alors vacant à la suite d''un incendie qui a détruit des magasins-entrepôts. En 1873, l''architecte Henri-Maurice Perrault présente des plans pour la construction d''un immeuble destiné à recevoir les bureaux de l''administration du Port de Montréal. Les plans sont approuvés, mais un revirement de situation inexpliqué entraîne la tenue d''un nouveau concours. En août 1874, les travaux sont finalement confiés à deux firmes d''architectes qui doivent travailler en collaboration : A.C.', 'historic', 45.4997, -73.5533, 50, null::extensions.geography, '357 rue de la Commune Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0039-67-0353-00', false, null, true),
  ('edifice-greenshields', 'Édifice Greenshields', 'L''édifice Greenshields, oeuvre de l''agence d’architectes Hutchison and Wood, est construit en deux phases : la première est réalisée en 1899 et la seconde en 1906-1907. L''homme d''affaires Duncan McIntyre acquiert d''abord le lot appartenant à l''homme d''affaires William Clendinneng en 1885. L''immeuble qui s''y trouvait est incendié vers la fin de l''année 1898. Jane A. Cassils, la veuve de Duncan McIntyre, y fait alors construire un bâtiment de sept étages. En mars 1906, elle achète quatre lots adjacents dont les bâtiments donnant sur la rue Craig ont été incendiés peu de temps auparavant.', 'historic', 45.502, -73.561, 50, null::extensions.geography, '759 square Victoria', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-00-0205-01', false, null, true),
  ('immeuble-du-centre-de-commerce-mondial-de-montreal', 'Immeuble du Centre de commerce mondial de Montréal', 'Cet immeuble est construit entre 1988 et 1991. Conçu par plusieurs firmes d’architectes montréalaises, il abrite entre autres le Centre de commerce mondial de Montréal (CCMM). Les promoteurs visent avec ce projet une clientèle associée au commerce international, qu’elle provienne de l’administration publique ou de l’entreprise privée. On construit à cette fin un immeuble de bureaux qui s’élève de part et d’autre de la ruelle des Fortifications. Les deux sections ainsi créées sont reliées par des passerelles de verre.', 'historic', 45.5022, -73.5603, 50, null::extensions.geography, '359-413 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-00-5947-01', false, null, true),
  ('hotel-inter-continental', 'Hôtel Inter-Continental', 'Cet hôtel est construit entre 1988 et 1991 par la chaîne hôtelière japonaise Inter-Continental. Les architectes Arcop, Provencher et Roy conçoivent cet édifice, lequel est relié au Centre de commerce mondial de Montréal (CCMM). Pour sa construction, on a démoli l’immeuble Mitchell. Lorsque le projet du Centre de commerce mondial de Montréal (CCMM) est présenté au public en 1987, on met de l’avant la multifonctionnalité de ce complexe en y intégrant un hôtel luxueux.', 'architecture', 45.5029, -73.5602, 60, null::extensions.geography, '360 rue Saint-Antoine Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-00-5947-02', false, null, true),
  ('edifice-de-la-james-c-wilson-co', 'Édifice de la James C. Wilson Co.', 'L''édifice Wilson, conçu par les architectes Edward C. et John W. Hopkins, est construit en 1888-1889. Le fabricant d''articles de papier James Crockett Wilson, qui a déjà pignon sur la rue Craig, achète cette propriété en 1884. Les trois maisons en brique de deux étages qui s’y trouvent, une sur la rue Craig et deux sur la ruelle des Fortifications, sont détruites en 1888 dès l''amorce des travaux de construction. L''édifice Wilson, constitue, avec son ascenseur pour passager et ses sept étages, l''un des édifices les plus hauts et les plus modernes de la métropole.', 'historic', 45.5026, -73.5607, 50, null::extensions.geography, '380 rue Saint-Antoine Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-00-5947-03', false, null, true),
  ('edifice-nordheimer', 'Édifice Nordheimer', 'En décembre 1886, un incendie ravage le Nordheimer''s Hall, un bâtiment de trois étages en pierre qui abrite entre autres un amphithéâtre et le commerce d''articles de musique de A. S. Norheimer. Samuel Nordheimer, propriétaire du terrain depuis 1856, demande alors à l''architecte John James Browne de concevoir un magasin-entrepôt. Les travaux débutent au printemps de 1888 et se terminent vers la fin de la même année. Le magasin A. S. Nordheimer occupe en partie les deux premiers étages du nouvel immeuble, le deuxième étant réservé à la salle de montre pour pianos.', 'historic', 45.5026, -73.5598, 50, null::extensions.geography, '363 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-00-5947-04', false, null, true),
  ('immeuble-waltons-lunch', 'Immeuble Walton''s Lunch', 'Construit en 1922, l''édifice du Walton''s Lunch n''est plus aujourd''hui qu''un vestige incorporé au Centre du commerce mondial. En 1921, la Beaver Investment Company Limited, devenue plus tard la Walton''s Limited, acquérait de la succession de John Hannan et de Thomas Spratt cette propriété de la rue Saint-Jacques (Hannan et Spratt avaient eux-même acquis cette propriété en 1909 à la suite d''une transaction avec Thomas Shaughnessy, président du Canadien Pacifique).', 'historic', 45.5019, -73.56, 50, null::extensions.geography, 'None rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-00-5947-07', false, null, true),
  ('edifice-de-la-merchants-bank', 'Édifice de la Merchants'' Bank', 'Les fortifications de Montréal sont démolies au début du XIXe siècle. Les lots ainsi dégagés peuvent être affectés à d’autres fonctions urbaines. Le terrain occupé aujourd’hui par l’édifice de la Merchants’ Bank, et au milieu duquel passait la muraille, est cédé à Louis Hector Le Fournier Dudivier. Ce terrain est limité au nord par la ruelle du Glacis (l’actuelle ruelle des Fortifications), au sud par la rue Saint-Jacques et à l’est par la rue de la Poudrière (le prolongement de la rue Saint-Pierre vers le nord).', 'historic', 45.5027, -73.5597, 50, null::extensions.geography, '355 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-10-0289-00', false, null, true),
  ('magasin-entrepot-joseph-tiffin-1866-1867', 'Magasin-entrepôt Joseph-Tiffin [1866-1867]', 'L’édifice Savage and Lyman est construit en 1866 et non en 1871 comme l’indiquent plusieurs sources. En février 1866, Joseph Tiffin père achète le lot 171 de Marie Jeanne Hervieux. Ce lot, ayant front sur la rue Saint-Jacques (à l’époque Great Saint-James) au coin de Dollard, correspond à 60 % de la superficie au sol de l’édifice actuel (dans sa partie avant). Lors de la transaction, on trouve sur le lot 171 un bâtiment de trois étages abritant des logements et des magasins liés au secteur de l’édition.', 'historic', 45.502, -73.5595, 50, null::extensions.geography, '380-384 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-10-1512-00', false, null, true),
  ('banque-royale', 'Banque Royale', 'En 1907, la Banque Royale du Canada déménage son siège social de Halifax à Montréal. En pleine expansion, elle se sent vite à l’étroit dans son immeuble de la rue Saint-Jacques. Pour régler ce problème chronique d’espace, le conseil d’administration de la banque la plus importante du Canada commande en 1926 un édifice prestigieux à une agence réputée d’architectes new-yorkais : York & Sawyer. Cette firme, qui se spécialise dans l’architecture bancaire, s’associe à l’architecte attitré de la banque, S. G. Davenport.', 'architecture', 45.5023, -73.5591, 60, null::extensions.geography, '360 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-10-4639-00', false, null, true),
  ('edifice-de-linsurance-exchange', 'Édifice de l''Insurance Exchange', 'L’édifice Insurance Exchange est construit en 1923-1924 selon les plans de l’architecte David Jérôme Spence. La compagnie Insurance Exchange Corporation Limited achète au début des années 1920 cinq lots contigus dans le quadrilatère formé des rues Saint-Jacques, Notre-Dame, Saint-Jean et Saint-Pierre. Près d’une dizaine de bâtiments sont détruits pour la construction de ce gratte-ciel. Parmi ceux-ci, on compte plusieurs magasins-entrepôts sur la rue Notre-Dame qui furent occupés, jusqu’en 1912, par l’immense magasin S. Carsley & Co.', 'architecture', 45.5028, -73.5587, 60, null::extensions.geography, '272-276 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-10-8190-00', false, null, true),
  ('edifice-montreal-star-iii', 'Édifice Montreal Star III', 'Depuis la deuxième guerre mondiale, le Montreal Star, journal distribué en après-midi, est en pleine expansion. En plus d’être le journal anglophone le plus important à Montréal, il est considéré comme étant l’un des grands journaux du monde. Au fil des ans, le Star, qui loge dans de vieux édifices de la rue Saint-Jacques, modifie régulièrement l’organisation intérieure de ses locaux afin de s’adapter aux exigences de l’augmentation constante de sa production.', 'historic', 45.5037, -73.5596, 50, null::extensions.geography, '250 rue Saint-Antoine Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-11-0582-00', false, null, true),
  ('edifice-de-la-canada-life', 'Édifice de la Canada Life', 'En 1894-1895, la compagnie d''assurance-vie Canada Life fait ériger un gratte-ciel de huit étages sur la rue Saint-Jacques. Elle confie le projet à l''architecte Richard A. Waite, un Américain qui a déjà réalisé pour la compagnie dans les années 1880 le siège social de Hamilton et la succursale de Toronto. La Canada Life choisit le site voisin du prestigieux Temple building (démoli en 1907). Pour son nouvel édifice, un bâtiment de trois étages qui s''y trouvait est démoli vers le début de l''année 1894 et vers la fin de 1895 l''édifice de la Canada Life est terminé.', 'architecture', 45.5029, -73.5595, 60, null::extensions.geography, '275 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-11-1613-00', false, null, true),
  ('edifice-canadian-imperial-bank-of-commerce', 'Édifice Canadian Imperial Bank of Commerce', 'Cet édifice est érigé entre 1907 et 1909 afin de loger les bureaux montréalais de la Canadian Bank of Commerce, une banque fondée à Toronto en 1867 et qui porte le nom de Canadian Imperial Bank of Commerce (CIBC) depuis 1961. La conception de la banque est confiée à l’agence d’architectes torontoise Darling and Pearson. L’édifice est le deuxième chantier majeur sur ce site en moins de 20 ans. En 1888-1889, on démolissait en effet l’église méthodiste St. James pour ériger l’immeuble Temple. Cet immeuble de bureaux de sept étages était l’un des édifices les plus prestigieux de la métropole.', 'historic', 45.5031, -73.5594, 50, null::extensions.geography, '265 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-11-2737-00', false, null, true),
  ('immeuble-metropolitan', 'Immeuble Metropolitan', 'En janvier 1902, l''immeuble de la Guardian Fire and Life Assurance Company, construit en 1874-1875 par la Citizens Insurance Company of Canada, est complètement détruit par un incendie. La compagnie décide cependant de construire son nouveau siège social canadien sur un autre terrain de la rue Saint-Jacques et elle retient une solution quelque peu inusitée pour l''utilisation de son terrain vacant. En 1903, elle accorde en effet un bail de 20 ans à la Metropolitan Bank à la condition que cette dernière y fasse rapidement construire un immeuble de bureaux.', 'historic', 45.5033, -73.5592, 50, null::extensions.geography, '261 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-11-3857-00', false, null, true),
  ('edifice-de-la-hanson-brothers', 'Édifice de la Hanson Brothers', 'Cet édifice d’inspiration Art déco, oeuvre de l’architecte Harold Lea Fetherstonhaugh, est construit en 1928 par la compagnie Hanson Brothers, une maison de courtage en valeurs mobilières spécialisée dans les obligations. Un bâtiment – probablement une maison-magasin de trois étages et demi de la première moitié du XIXe siècle – est détruit pour faire place au nouvel immeuble. Les bureaux de la maison Hanson Brothers occupent à l’origine trois des quatre étages.', 'historic', 45.5034, -73.5592, 50, null::extensions.geography, '255 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-11-4365-00', false, null, true),
  ('edifice-du-montreal-star-i', 'Édifice du Montreal Star I', 'En février 1885, Hugh Graham, propriétaire du journal Montreal Star, se porte acquéreur auprès de Andrew Stewart Ewing d''un immeuble de trois étages situé sur la rue Saint-Jacques afin d''y installer les bureaux et les équipements de son journal. Vers la fin de 1893, Graham achète de son voisin à l''ouest, David Ross McCord, un immeuble de trois étages. Vers le printemps 1899, les deux immeubles sont démolis et Graham fait appel à l''architecte Alexander Francis Dunlop pour préparer les plans d''un immeuble plus spacieux qui répondrait mieux aux besoins grandissants de l''entreprise.', 'historic', 45.5036, -73.559, 50, null::extensions.geography, '241-245 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-11-5385-00', false, null, true),
  ('edifice-de-la-london-and-lancashire-life', 'Édifice de la London and Lancashire Life', 'En mai 1898, la compagnie d''assurance britannique London and Lancashire Life Assurance Company achète un lot vacant sur la rue Saint-Jacques pour y construire son siège social canadien. Ce terrain était auparavant occupé par une partie du « bloc Barron », un bâtiment de quatre étages détruit par un incendie en décembre 1896. Selon toute vraisemblance, le nouvel immeuble de bureaux de sept étages est complété avant la fin de l''année 1898. De style beaux-arts, il est l''oeuvre de l''architecte Edward Maxwell assisté de son jeune frère William Sutherland.', 'historic', 45.5033, -73.5586, 50, null::extensions.geography, '244 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-11-9155-00', false, null, true),
  ('edifice-de-la-banque-depargne', 'Édifice de la Banque-d''Épargne', 'En 1869, la Banque d''Épargne de la Cité et du District de Montréal achète un terrain au coin des rues Saint-Jacques et Saint-Jean pour y installer son siège social. Le petit bâtiment commercial qui s''y trouve est démoli et on confie à l''architecte Michel Laurent la construction d''un immeuble de quatre étages. Cette première section, occupée dès 1871, est un des rares exemples d''édifice bancaire canadien conçu par un architecte francophone. En 1874, la Banque d''Épargne achète le lot voisin et entreprend, l''année suivante, un premier agrandissement.', 'historic', 45.5031, -73.5585, 50, null::extensions.geography, '262-266 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-11-9227-00', false, null, true),
  ('edifice-de-la-guardian-fire-and-life', 'Édifice de la Guardian Fire and Life', 'En janvier 1902, la compagnie d''assurance Guardian Fire and Life Assurance Company achète un terrain vacant sur la rue Saint-Jacques pour y construire son siège social canadien. Acquis auprès de Thomas Philippe Barron, ce terrain était auparavant occupé par une partie du « bloc Barron », un imposant édifice de quatre étages qu''un incendie avait détruit en décembre 1896. La construction du nouvel édifice, un gratte-ciel de neuf étages d''inspiration beaux-arts, débute au printemps 1902 pour se terminer vers la fin de la même année.', 'architecture', 45.5034, -73.5585, 60, null::extensions.geography, '240 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-11-9970-00', false, null, true),
  ('edifice-du-montreal-star-ii', 'Édifice du Montreal Star II', 'En février 1922, un incendie ravage l’immeuble de la Standard Life, œuvre remarquée de l’architecte américain Richard Waite réalisée entre 1883 et 1885. Le propriétaire voisin, le quotidien Montreal Star, manque alors d’espace : il saisit l’occasion et achète l’emplacement en 1923. À la fin de 1926, on obtient les permis pour ériger un immeuble de bureaux de 15 étages mais, pour des raisons inconnues, seuls les fondations et les deux sous-sols seront réalisés dans un premier temps. Sans attendre la poursuite des travaux, les presses de la Montreal Star Publishing Co.', 'architecture', 45.5037, -73.5591, 60, null::extensions.geography, '231-235 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-12-6101-00', false, null, true),
  ('edifice-national-trust', 'Édifice National Trust', 'En 1903 la compagnie de fiducie National Trust fait l''achat de la propriété sur laquelle s''érigera quelques années plus tard l''édifice actuellement en place. Au moment de l''acquisition par le National Trust, le terrain est occupé par un immeuble appartenant à la Standard Life Insurance. En 1914, on procède à sa démolition. La compagnie requiert alors les services de l''architecte Kenneth Guscotte Rea pour la construction d''un immeuble de bureaux répondant spécifiquement à ses besoins.', 'historic', 45.5038, -73.5588, 50, null::extensions.geography, '225 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-12-6813-00', false, null, true),
  ('ancien-siege-social-de-la-banque-royale', 'Ancien siège social de la Banque Royale', 'Cet édifice est construit en 1907-1908 pour héberger le siège social de la Banque Royale. Il est conçu selon les plans de l’architecte d’origine américaine Howard Colton Stone. Le sculpteur américain Henry Augustus Lukeman réalise quant à lui les quatre immenses statues qui ornent le bâtiment. La Banque Royale quitte l’édifice en 1928 pour s’installer un peu plus à l’ouest, dans son nouveau siège social de 22 étages. L’immeuble est alors vendu à la Banque Provinciale du Canada. Cette dernière y installe son siège social qu’elle agrandit en 1958 en achetant l’édifice voisin.', 'historic', 45.5039, -73.5586, 50, null::extensions.geography, '221 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-12-7525-01', false, null, true),
  ('edifice-dominion-express', 'Édifice Dominion Express', 'En 1907, le prestigieux St-Lawrence Hall, un hôtel situé à l''angle des rues Saint-François-Xavier et Saint-Jacques, est vendu à la Compagnie du chemin de fer Canadien Pacifique. Trois ans plus tard, le Canadien Pacifique revend l''hôtel à une de ses filiales spécialisée dans l''expédition de colis. La Dominion Express reçoit le mandat de faire construire un nouvel immeuble de bureaux sur cet emplacement de choix. Les travaux de démolition du St-Lawrence Hall débutent en juillet 1910 et la construction du nouvel immeuble suit immédiatement.', 'architecture', 45.5042, -73.5586, 60, null::extensions.geography, '201-215 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-12-8750-00', false, null, true),
  ('immeuble-peter-redpath', 'Immeuble Peter-Redpath', 'Cet immeuble de bureaux est construit en 1881 par Peter Redpath, un industriel dont le nom est associé à la raffinerie de sucre Redpath située sur le canal de Lachine. De 1882 à 1891, le bâtiment loge des bureaux de la Hudson’s Bay Company. À la fin des années 1880, l’hommes d’affaires et député Donald Alexander Smith (Lord Strathcona), très lié à la Hudson’s Bay Company, y tient aussi un bureau. L’immeuble est vendu en 1892 au marchand Andrew Frederick Gault dont la succession détient les titres de propriétés jusqu’en 1928. L’immeuble conserve la même fonction durant tout le XXe siècle.', 'historic', 45.5026, -73.5581, 50, null::extensions.geography, '282 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-20-2374-00', false, null, true),
  ('immeuble-george-washington-stephens', 'Immeuble George-Washington-Stephens', 'George W. Stephens fait construire cet immeuble en 1883. Stephens, avocat et député libéral de Montréal-Centre, achète ce terrain des héritiers de John Caverhill en janvier 1883. Au printemps, on démoli le bâtiment de bois qui s’y trouve, puis on érige cet immeuble de bureaux. À l’origine, George W. Stephens dispose d’un bureau au troisième étage, tandis qu’une dizaine de locataires se partagent le reste de l’immeuble. Fait à noter, l’importante firme comptable P. S. Ross and Sons loge dans ce bâtiment entre 1885 et 1895. Au début des années 2000, l’immeuble est transformé en condominiums.', 'historic', 45.5024, -73.558, 50, null::extensions.geography, '470 rue Saint-Alexis', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-20-3557-00', false, null, true),
  ('edifice-waddell', 'Édifice Waddell', 'En 1879, le marchand de matériel ferroviaire Samuel Waddell acquiert un lot de la Metropolitan Bank et d''Henry Hogan. Waddell fait démolir les bâtiments qui s''y trouvent au printemps 1884, puis on entame la construction d''un immeuble de bureaux de quatre étages. L''édifice, terminé vers la fin de l''année 1884, est l''oeuvre du duo d''architectes père-fils, John W. et Edward C. Hopkins. La partie de l''édifice accessible par la rue Notre-Dame est d''abord occupée principalement par la Mutual Life Insurance Company, puis par la London Assurance Corporation de 1888 à 1914.', 'historic', 45.5028, -73.5579, 50, null::extensions.geography, '260-264 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-20-3794-01', false, null, true),
  ('edifice-de-la-sun-life', 'Édifice de la Sun Life', 'L''édifice Sun Life est construit en 1890-1891. La compagnie d''assurance-vie montréalaise achète d''abord un lot des héritiers d''Alfred Larocque durant l''été 1889. On trouve alors sur le terrain une maison-magasin et des dépendances, lesquelles sont démolies pour le projet. La compagnie lance ensuite, à l''automne 1889, un concours d''architecture que remporte l''architecte Robert Findlay. Les travaux débutent vers le printemps 1890 et se terminent au début de 1891. Les nombreuses sculptures qui ornent les façades sont l''oeuvre de l''artiste Henry Beaumont.', 'historic', 45.5027, -73.558, 50, null::extensions.geography, '266 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-20-3794-02', false, null, true),
  ('immeuble-furness', 'Immeuble Furness', 'Cet immeuble est construit en 1921 par la Furness, Withy & Company Limited, une compagnie britannique spécialisée dans le transport maritime. Cette dernière achète d’abord le lot en 1920. Le bâtiment de cinq étages qui s’y trouve, l’immeuble Fraser, est démoli au printemps 1921. En 1922, la Furness, Withy & Company Limited et des filiales de la compagnie occupent les deux premiers étages.', 'historic', 45.5021, -73.5574, 50, null::extensions.geography, '315 rue du Saint-Sacrement', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-20-8425-00', false, null, true),
  ('edifice-lewis', 'Édifice Lewis', 'En 1913, un nouvel immeuble de bureaux, situé à l''angle des rues Saint-Jean et de l''Hôpital accueille ses premiers occupants. Il s''élève sur des lots remembrés où avaient été érigés au XIXe siècle de plus petits bâtiments occupés par des marchands et divers représentants. William Francis Lewis a graduellement acquis ces lots avant d''en transférer la propriété à la Lewis Building Co. qui, en 1912, fait construire le nouveau gratte-ciel. L''architecte Kenneth Guscotte Rea est le concepteur de cet imposant immeuble de 10 étages. La Lewis Building Co.', 'architecture', 45.5027, -73.5573, 60, null::extensions.geography, '459-465 rue Saint-Jean', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-20-9193-00', false, null, true),
  ('immeuble-geoffrion-et-perodeau', 'Immeuble Geoffrion et Pérodeau', 'Cet immeuble Art déco est construit en 1930 pour les courtiers Henri Geoffrion et Horace Pérodeau. Sa conception a été confiée à l’architecte Henri S. Labelle. À l’origine, la firme de courtage Geoffrion & Cie occupe le rez-de-chaussée en entier, tandis que les étages supérieurs logent des sociétés oeuvrant dans le même domaine. Geoffrion et Pérodeau vendent l’immeuble dès 1934, en pleine crise économique. En 1945, il est acheté par une autre firme de courtage, la L. G. Beaubien & Cie. Cette dernière occupe tout l’édifice jusqu’au début des années 1960, puis s’en départit en 1973.', 'historic', 45.5036, -73.5579, 50, null::extensions.geography, '221-229 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-21-4393-00', false, null, true),
  ('maison-magasin-louis-tancrede-bouthillier-1836', 'Maison-magasin Louis-Tancrède-Bouthillier [1836]', 'L''inspecteur de potasse Louis-Tancrède Bouthillier fait construire cette maison-magasin en 1836. Bouthillier fait l''acquisition des biens de ses défunts parents en 1833, dont cet emplacement avec une maison en pierre, un entrepôt et autres dépendances. Trois ans plus tard, il engage le maçon et entrepreneur Louis Comte pour construire le bâtiment. Cette maison-magasin, comme d''autres immeubles semblables, possède au départ une double vocation résidentielle et commerciale.', 'historic', 45.5035, -73.5575, 50, null::extensions.geography, '214-222 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-21-7969-01', false, null, true),
  ('entrepot-bouthillier', 'Entrepôt Bouthillier', 'Jean Bouthillier ou son fils Louis-Tancrède font construire ce bâtiment ente 1825 et 1837. Ce dernier, situé dans la cour arrière de l''emplacement, sert dès le départ de dépendance à l''immeuble principal donnant sur la rue Notre-Dame. Au moins dès 1837, les deux bâtiments sont reliés par une aile en brique. Dans les années 1840 et pour le siècle à venir, cette dépendance est louée à l''occupant du magasin du côté ouest de la maison-magasin rue Notre-Dame. Elle sert d''atelier comme d''entrepôt à des marchands, à des fabricants notamment de coffres, à des courtiers et à des tailleurs.', 'historic', 45.5034, -73.5573, 50, null::extensions.geography, null, 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-21-7969-02', false, null, true),
  ('edifice-de-lexchange-bank', 'Édifice de l''Exchange Bank', 'En 1873, Charles S. Rodier vend un terrain à la Exchange Bank of Canada par l''intermédiaire d''un membre du conseil d''administration, A. W. Ogilvie. La banque fait aussitôt démolir les immeubles commerciaux qui s''y trouvent et confie à l''architecte John William Hopkins le soin d''ériger son siège social. La construction de l''immeuble de bureaux de quatre étages débute vers le printemps de 1874 et se termine vers la fin de la même année.', 'historic', 45.5036, -73.5573, 50, null::extensions.geography, '200-210 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-21-8891-00', false, null, true),
  ('edifice-de-la-yorkshire-insurance', 'Édifice de la Yorkshire Insurance', 'La Yorkshire Insurance Co. inaugure en 1911 son nouvel immeuble de bureaux de 10 étages. En 1909, la compagnie d''assurances britannique a acheté de la succession E.J. Bourne, épouse du défunt Matthew Hamilton Gault, un petit terrain situé sur la rue Saint-Jacques et sur lequel se trouve un immeuble en pierre de trois étages et demi avec porte cochère menant à des dépendances. Ce vieux bâtiment, occupé par un fabricant de plumes et de crayons et quelques agents de compagnies ferroviaires, sont démolis en 1910 et les travaux de construction débutent aussitôt.', 'architecture', 45.5039, -73.5581, 60, null::extensions.geography, '210-212 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-22-2324-00', false, null, true),
  ('edifice-mcdougall-et-cowans', 'Édifice McDougall et Cowans', 'Cet édifice Art déco est construit par la Anglo-American Trust Co. en 1929-1930. L’architecte James Cecil McDougall en dessine les plans, tandis que les bas-reliefs sont réalisés par Henri Hébert, le fils du sculpteur Louis-Philippe Hébert. Une ouverture permet d’accéder au bâtiment voisin de la rue Saint-François-Xavier, une propriété de la Anglo-American Trust Co. depuis 1925 (bâtiment disparu). En 1930, la firme de courtiers McDougall & Cowans, dont les propriétaires possèdent également la Anglo-American Trust Co., s’installent au rez-de-chaussée et au deuxième étage.', 'historic', 45.5039, -73.5577, 50, null::extensions.geography, '201 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-22-4429-02', false, null, true),
  ('edifice-de-la-banque-canadienne-nationale', 'Édifice de la Banque-Canadienne-Nationale', 'La construction atteint des chiffres records à Montréal en 1965. On y investit pour 300 millions de dollars, dépassant ainsi les 244 millions de l’année précédente. Montréal est en pleine ébullition et, depuis dix ans, les nouveaux édifices changent rapidement le profil de la ville : l’hôtel Queen Elizabeth, l’aérogare de Dorval, l’édifice d’Hydro-Québec, la Place des Arts, la place Ville-Marie, la place Victoria, l’Expo 67 , Habitat 67, la place Bonaventure.', 'architecture', 45.5043, -73.5576, 60, null::extensions.geography, '500 place d''Armes', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-22-6465-00', false, null, true),
  ('edifice-de-la-montreal-street-railway', 'Édifice de la Montreal Street Railway', 'La construction de l''édifice de la Montreal Street Railway s''échelonne sur près de trois ans, entre le printemps 1893 et la fin de 1895. La Montreal Street Railway Company acquiert d''abord le terrain en mars 1893 de l''homme d''affaires George B. Burland. On retrouve alors sur cette propriété un immeuble de trois étages qu''occupe le rembourreur R. N. Tombyll depuis 20 ans. La compagnie fait démolir ce bâtiment peu après et elle embauche les architectes John William Hopkins et Edward C. Hopkins pour la construction de leur siège social.', 'historic', 45.5053, -73.5582, 50, null::extensions.geography, '750 côte de la Place-d''Armes', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-23-1979-00', false, null, true),
  ('banque-de-montreal', 'Banque de Montréal', 'Fondée en 1817, la Banque de Montréal - la première banque canadienne - connaît une telle croissance de son chiffre d''affaires qu''elle doit quitter son premier immeuble de la rue Saint-Jacques, occupé depuis 1819, après seulement 25 ans . En 1845, la banque achète un terrain, alors utilisé comme cimetière, ainsi qu''un immeuble appartenant à la fabrique de la paroisse Notre-Dame et qui loge des bureaux, du côté nord-ouest de la place d''Armes. La Banque engage l''architecte John Wells pour concevoir son nouveau siège social.', 'historic', 45.505, -73.5583, 50, null::extensions.geography, '119 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-23-2008-01', false, null, true),
  ('edifice-du-royal-trust', 'Édifice du Royal Trust', 'En 1908, la fiducie du Royal Trust fait l’acquisition auprès de la Alliance Assurance Company d’un emplacement sur lequel on retrouve alors l’Imperial Building, un immeuble construit en 1889 qui avait lui-même remplacé un bâtiment dont la construction remontait à 1846 (la City Bank). Pour la Royal Trust, le choix du site est stratégique, l’entreprise disposant de solides liens avec la Banque de Montréal, son voisin immédiat.', 'architecture', 45.5051, -73.5578, 60, null::extensions.geography, '105-107 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-23-4757-00', false, null, true),
  ('edifice-de-la-life-association-of-scotland', 'Édifice de la Life Association of Scotland', 'En 1868, John Fraser, directeur de la compagnie d''assurances Scottish Life Association, achète deux lots vacants de la Trust and Loan of Upper Canada. Les bâtiments érigés sur ces prestigieux terrains bordant la Place d''Armes avaient été démolis peu de temps auparavant afin de permettre l''élargissement de la rue Saint-Jacques. Agissant au nom de la compagnie, Fraser mandate les architectes Hopkins & Wily pour la construction d''un immeuble de bureaux. L''édifice de quatre étages, inspiré du style Second Empire, est érigé en 1870.', 'historic', 45.5054, -73.5576, 50, null::extensions.geography, '701-711 côte de la Place-d''Armes', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-23-6691-00', false, null, true),
  ('banque-du-peuple', 'Banque du Peuple', 'L''édifice de la Banque du Peuple est construit en 1893-1894 selon les plans de la firme d''architectes Perrault, Mesnard et Venne. En 1893, la Banque du Peuple possède trois bâtiments contigus sur la rue Saint-Jacques, dont son siège social érigé en 1871-1872 (Henri-Maurice Perrault, architecte). Les deux autres, construits en 1869, furent acquis en 1890 auprès d''Alexander Cross. Ces trois immeubles sont démolis au printemps 1893, à l''exception de la façade du siège social de 1871-1872 qu''on intègre à un nouvel immeuble de bureaux de sept étages.', 'architecture', 45.5056, -73.5575, 60, null::extensions.geography, '53-57 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-24-7505-00', false, null, true),
  ('ancien-siege-social-de-la-banque-du-peuple', 'Ancien siège social de la Banque du Peuple', 'En 1871-1872, la Banque du Peuple fait construire son siège social sur un lot vacant acquis au printemps 1871 de l''avocat et homme d''affaires Henry Judah. L''immeuble de trois étages, oeuvre de l''architecte Henri-Maurice Perrault, s''insère alors parmi les nouveaux bâtiments de ce tronçon de la rue Saint-Jacques élargi à la fin des années 1860. De 1872 au début des années 1890, la Banque du Peuple en est l''unique occupant. Vingt ans à peine après la construction initiale, la Banque du Peuple manque d''espace.', 'historic', 45.5054, -73.5574, 50, null::extensions.geography, '53-57 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-24-7505-01', false, null, true),
  ('edifice-alexander-cross', 'Édifice Alexander-Cross', 'L''avocat Alexander Cross acquiert en 1867 et 1868 trois lots contigus sur la rue Saint-Jacques. Ces lots sont vacants, car la Ville de Montréal a exproprié les deux édifices s''y trouvant afin d''élargir la Petite rue Saint-Jacques, dont l''immeuble où Alexander Cross avait son cabinet d''avocat. En lieu et place de ces bâtiments, Cross fait construire en 1869 un édifice multifonctionnel beaucoup plus imposant.', 'historic', 45.5057, -73.5573, 50, null::extensions.geography, '43-51 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-24-8523-00', false, null, true),
  ('edifice-la-presse', 'Édifice La Presse', 'En 1955, La Presse, le plus grand quotidien de langue française en Amérique, s’apprête à entrer dans une ère moderne d’automatisation de sa production grâce à la construction d’un nouvel édifice. Celui-ci sera situé sur la rue Saint-Laurent, entre la rue Saint-Antoine - la rue Craig de l’époque - et la ruelle des Fortifications. Pour réaliser ce projet, il faut démolir de nombreux bâtiments existant sur ce site, sans compter les vestiges des anciennes fortifications que l’on découvre lors des travaux d’excavation. L’architecte Jacques M.', 'historic', 45.5064, -73.5573, 50, null::extensions.geography, '750 boulevard Saint-Laurent', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-24-8997-00', false, null, true),
  ('immeuble-clegg', 'Immeuble Clegg', 'En 1903, la firme de courtiers d’assurances James J. Riley & Sons engage l’agence d’architectes Finley and Spence pour la construction d’un immeuble de deux étages. L’immeuble est vendu en 1949 à la Kerr Steamship Limited, une société maritime américaine dont le président est Alfred Clegg. La façade est alors totalement refaite, si bien que l’immeuble possède dorénavant les apparences d’un bâtiment de la fin des années 1940. En 1956, on y ajoute un étage. La Kerr Steamships Limited se départit de l’immeuble en 1977.', 'historic', 45.5026, -73.5571, 50, null::extensions.geography, '455 rue Saint-Jean', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-30-0671-00', false, null, true),
  ('immeuble-robert-hampson-son', 'Immeuble Robert Hampson & Son', 'Cet immeuble de bureaux est construit en 1926-1927. Robert Hampson, président de la Robert Hampson & Son, une compagnie d’agents d’assurances fondée en 1864, achète d’abord cette propriété en 1907. L’entreprise quitte l’édifice du Corn Exchange et s’installe dans le bâtiment de trois étages qui occupe l’emplacement. Pour répondre aux besoins de la compagnie, l’agence d’architectes Hutchison and Wood apporte alors des modifications à ce bâtiment. En 1926, il est démoli pour faire place à un nouvel immeuble Art déco.', 'historic', 45.5025, -73.557, 50, null::extensions.geography, '451 rue Saint-Jean', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-30-1663-00', false, null, true),
  ('edifice-du-montreal-board-of-trade', 'Édifice du Montreal Board of Trade', 'L’édifice du Board of Trade est construit en 1902-1903. Son histoire remonte cependant au début des années 1890 lorsque le Montreal Board of Trade acquiert le terrain sur lequel est érigé l’édifice actuel. L’association d’hommes d’affaires lance alors un concours d’architecture remporté par l’agence d’architectes bostonnienne Shepley, Rutan and Coolidge. En 1892-1893, le premier édifice du Board of Trade est érigé. Le 23 janvier 1901, un énorme incendie frappe le quartier Ouest du Vieux-Montréal. L’édifice du Board of Trade est complètement détruit.', 'historic', 45.502, -73.5569, 50, null::extensions.geography, '300 rue du Saint-Sacrement', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-30-2107-00', false, null, true),
  ('immeuble-walter-benny', 'Immeuble Walter-Benny', 'Le maître boulanger Walter Benny fait construire cet immeuble en 1834-1835. Benny acquiert en décembre 1833 l’emplacement avec une maison, une boutique et ses dépendances, la maison donnant sur la rue du Saint-Sacrement devant être enlevée par l’ancien propriétaire. Lorsque Benny loue l’emplacement en novembre 1835 pour le mois de mai suivant, il y a fait bâtir un nouvel immeuble en pierre de trois étages, incluant le rez-de-chaussée. Les épiciers de gros George D. Watson et John Black occupent les lieux jusqu’en 1847.', 'historic', 45.5026, -73.5569, 50, null::extensions.geography, '239 rue du Saint-Sacrement', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-30-2178-00', false, null, true),
  ('immeuble-john-lovell-son', 'Immeuble John Lovell & Son', 'John Lovell, un des plus importants imprimeur et éditeur au Canada, fait construire cet immeuble en 1884. Depuis 1845, Lovell est propriétaire de l’emplacement de la rue Saint-Nicolas et y mène ses activités commerciales. Vers le début de l’année 1884, un incendie détruit les bâtiments qui s’y trouvent. On construit alors un nouvel immeuble pour loger la John Lovell & Son, une entreprise qui, comme les précédentes entreprises de Lovell, imprime un nombre impressionnant de publications comprenant entre autres des manuels scolaires, des périodiques littéraires et des bottins.', 'historic', 45.5024, -73.5562, 50, null::extensions.geography, '423 rue Saint-Nicolas', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-30-7651-00', false, null, true),
  ('edifice-du-c-p-r-telegraph', 'Édifice du C. P. R. Telegraph', 'En 1900-1901, la compagnie ferroviaire Canadien Pacifique fait construire ce gratte-ciel afin de loger entre autres certaines de ses divisions, notamment son service de télégraphie. En mai 1900, deux membres de la haute direction de l’entreprise, le nouveau président Thomas Shaughnessy et Richard B. Angus, font l’acquisition de deux propriétés sur la rue de l’Hôpital. La première appartenait à George-Casimir Dessaulles, ancien maire de Saint-Hyacinthe pendant près de 25 ans, la seconde à la succession John James Arnton.', 'architecture', 45.5032, -73.5566, 60, null::extensions.geography, '204 rue de l''Hôpital', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-31-4347-00', false, null, true),
  ('maison-magasin-frederic-auguste-quesnel', 'Maison-magasin Frédéric-Auguste-Quesnel', 'Cette maison-magasin de trois étages, y compris le rez-de-chaussée, est construite en 1842. Frédéric-Auguste Quesnel est propriétaire de cet emplacement depuis près de 30 ans, lorsqu’il décide de remplacer la vieille maison en pierre d’un étage qui s’y trouvait déjà lors de son acquisition. De 1844 à 1850, les libraires et imprimeurs Armour & Ramsay y installent leur commerce dans les deux magasins du rez-de-chaussée et Hew Armour habite dans un logement situé au-dessus, les étages supérieurs des maisons-magasins étant au départ consacrés à l’habitation.', 'historic', 45.5032, -73.5564, 50, null::extensions.geography, '436-440 rue Saint-François-Xavier', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-31-5036-00', false, null, true),
  ('ancienne-bourse-de-montreal', 'Ancienne Bourse de Montréal', 'Le Montreal Stock Exchange (Bourse de Montréal) fait construire cet édifice en 1903-1904. À la suite de l’incendie de l’immeuble du Board of Trade en janvier 1901, le Montreal Stock Exchange se retrouve sans lieu d’échanges. Le conseil d’administration décide alors de se doter d’un édifice comparable aux grandes bourses du monde. En janvier 1903, après de longues négociations, le Montreal Stock Exchange acquiert des sulpiciens une propriété sur la rue Saint-François-Xavier. Pour la conception de l’édifice, on fait appel à l’Américain George B.', 'historic', 45.5036, -73.5565, 50, null::extensions.geography, '453-457 rue Saint-François-Xavier', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-31-5980-01', false, null, true)
insert into public.landmarks (slug, name, description, category, latitude, longitude, geofence_radius_m, geofence_polygon, address, neighbourhood, source_name, source_url, source_license, source_record_id, needs_review, review_note, is_active) values
  ('edifice-montreal-curb-market', 'Édifice Montreal Curb Market', 'Le Montreal Stock Exchange (Bourse de Montréal) fait construire l’édifice du Montreal Curb Market en 1928-1929. En 1903, le Montreal Stock Exchange avait acquis des sulpiciens une grande propriété sur la rue Saint-François-Xavier. On construisit alors l’édifice du Montreal Stock Exchange sur la majeure partie du terrain, mais on avait conservé la vieille maison de deux étages et demi au sud. En 1928, on décide de démolir cette maison afin de construire un immeuble pour loger le Montreal Curb Market, une bourse où l’on transige des jeunes titres et des valeurs spéculatives.', 'historic', 45.5034, -73.5562, 50, null::extensions.geography, '449-451 rue Saint-François-Xavier', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-31-5980-02', false, null, true),
  ('maison-magasin-james-hutchison', 'Maison-magasin James-Hutchison', 'Cette maison-magasin en pierre de trois étages, incluant le rez-de-chaussée, avec un coin arrondi est construite en 1841-1842. En août 1840, James Hutchison achète cet emplacement au coin des rues Saint-François-Xavier et Saint-Sacrement avec une maison en pierre d’un étage et autres bâtiments. Un litige concernant un mur mitoyen et la présence des premiers locataires en mai 1842, en l’occurrence les marchands de dry goods (tissus, mercerie et peut-être autres produits) Robert Patterson & Company, confirment une construction au cours de 1841-1842.', 'historic', 45.5031, -73.5563, 50, null::extensions.geography, '430-434 rue Saint-François-Xavier', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-31-7133-00', false, null, true),
  ('edifice-de-la-montreal-telegraph', 'Édifice de la Montreal Telegraph', 'Cet édifice demeure la propriété de la Montreal Telegraph Co., qui y occupe des bureaux pendant près de 75 ans. En 1870, cette entreprise de communication par fils achète de la succession Valois le lot situé au coin des rues Saint-François-Xavier et Saint-Sacrement. La compagnie, déjà en activité dans un édifice adjacent au lot acheté, est en pleine croissance sous la férule de son richissime président, Sir Hugh Montagu Allan. En 1872, la Montreal Telegraph démolit les bâtiments acquis deux ans plus tôt, construit son siège social en 1873 et s’y installe en 1874.', 'historic', 45.5029, -73.5561, 50, null::extensions.geography, '422-424 rue Saint-François-Xavier', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-31-8618-00', false, null, true),
  ('immeuble-joseph-amable-berthelot', 'Immeuble Joseph-Amable-Berthelot', 'L’ancien juge de la Cour Supérieure Joseph-Amable Berthelot fait construire cet immeuble de bureaux en 1886. Conçu par l’architecte Victor Roy, le bâtiment remplace deux immeubles servant de cabinets à des membres des professions libérales. À l’origine, il compte trois étages (incluant le rez-de-chaussée) et un demi-étage sous les combles. Parmi les premiers occupants, on retrouve entre autres les importateurs de matières premières Winn & Holland, la compagnie d’assurances Fire Insurance Association of London, les bureaux de la Merchant’s Bank of Halifax et une compagnie de télégraphie.', 'historic', 45.5033, -73.5561, 50, null::extensions.geography, '439-447 rue Saint-François-Xavier', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-31-8654-00', false, null, true),
  ('edifice-des-sulpiciens-iii', 'Édifice des Sulpiciens III', 'La construction de cet immeuble de bureaux, le dernier érigé par les sulpiciens sur leurs terrains vacants de la rue Saint-François-Xavier, est réalisée en 1874. L''un des premiers locataires du rez-de-chaussée est une succursale de la Banque d''Hochelaga, remplacée par la Merchants Bank of Halifax à la fin des années 1880, puis par la Dominion Bank au début du XXe siècle. Plusieurs compagnies d''assurances se retrouvent aux étages supérieurs ainsi que les architectes Théodore Daoust à la fin du XIXe siècle et Eugène Payette de 1911 à 1947.', 'historic', 45.5039, -73.5572, 50, null::extensions.geography, '140 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-32-1407-01', false, null, true),
  ('edifice-des-sulpiciens-ii', 'Édifice des Sulpiciens II', 'Construit en 1870 par les sulpiciens sur un terrain vacant, cet immeuble de bureaux situé à deux pas de la place d''Armes est occupé dès l''année suivante par plusieurs professionnels, marchands et compagnies d''assurances, dont certaines spécialisées dans le domaine maritime. De plus, une succursale de la Banque Royale du Canada s''installe au rez-de-chaussée. Parmi les premiers occupants, notons la présence de l''arpenteur et architecte Henri-Maurice Perrault, rejoint en 1874 par son fils Maurice et, en 1880, par l''architecte Albert Mesnard.', 'historic', 45.5037, -73.5569, 50, null::extensions.geography, '465-471 rue Saint-François-Xavier', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-32-1407-02', false, null, true),
  ('edifice-des-sulpiciens-i', 'Édifice des Sulpiciens I', 'Cet immeuble est érigé par les sulpiciens en 1861 sur un terrain vacant. Dès sa construction, l''immeuble est occupé par l''arpenteur et architecte Henri-Maurice Perrault et par le comptable Thomas Johnson. Le premier y conserve son bureau jusqu''en 1871, puis déménage dans l''édifice Sulpicien II que l''on vient de terminer sur le terrain voisin. Quant au second, il cède rapidement sa place à diverses entreprises liées au monde de la finance puis de la télégraphie. En 1872, l''immeuble est entièrement occupé par la Dominion Telegraph Co.', 'historic', 45.5037, -73.5567, 50, null::extensions.geography, '459-461 rue Saint-François-Xavier', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-32-1407-03', false, null, true),
  ('presbytere-de-la-paroisse-notre-dame-de-montreal', 'Presbytère de la paroisse Notre-Dame de Montréal', 'À la suite d''une entente entre l''évêque de Montréal et la Compagnie de Saint-Sulpice en novembre 1840, les sulpiciens acceptaient « pour toujours et irrévocablement » la charge de former des aspirants au sacerdoce dans le diocèse de Montréal. Cet accord marquait la fondation du Grand Séminaire. Faute d''espace, il fallait loger la nouvelle institution dans l''immeuble du Collège de Montréal sur la rue Saint-Paul en attendant la construction d''un immeuble permanent consacré aux activités du séminaire.', 'religious', 45.5043, -73.5565, 60, null::extensions.geography, '116 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-32-7223-02', false, null, true),
  ('edifice-de-la-new-york-life-insurance', 'Édifice de la New York Life Insurance', 'La compagnie d''assurance-vie New York Life Insurance fait construire ce prestigieux immeuble de bureaux en 1887. La conception est confiée à la firme d''architectes Babb, Cook & Willard, de New York. Le chantier dure jusqu''au printemps 1889 et exige la démolition d''un immeuble de deux étages datant de la première moitié du XIXe siècle. La compagnie propriétaire fait de cet immeuble son siège social pancanadien, mais n''en utilise qu''une petite partie, soit le 4e et le 8e étages, où elle installe sa bibliothèque.', 'architecture', 45.5053, -73.5571, 60, null::extensions.geography, '511 place d''Armes', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-33-0573-00', false, null, true),
  ('edifice-versailles', 'Édifice Versailles', 'En 1913, un nouvel immeuble de dix étages est érigé sur la rue Saint-Jacques, tout juste à l''arrière de l''édifice de la New York Life Assurance. Son propriétaire, Joseph Versailles, a acquis l''emplacement en 1910 et, dans le but d''y faire construire un immeuble locatif, y a fait démolir le bâtiment de trois étages utilisé alors comme auberge. Versailles confie le projet de construction aux architectes Ross et MacFarlane.', 'architecture', 45.5055, -73.5569, 60, null::extensions.geography, '60 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-33-1793-00', false, null, true),
  ('edifice-duluth', 'Édifice Duluth', 'En 1893 Joseph Ovide Gravel, Adolphe Roy et George H. Matthews font l''acquisition de la propriété de Duncan McEachran et associés. Ils sont alors propriétaires de deux bâtiments presque centenaires qui abritent des commerces et des logements. En 1910, Gravel achète les parts de ses partenaires. Deux ans plus tard, il entreprend la construction de l''immeuble Duluth, baptisé ainsi en l''honneur de Daniel Greysolon, dit sieur du Luth, tour à tour écuyer et explorateur et qui aurait vécu en ces lieux en 1675.', 'architecture', 45.505, -73.5563, 60, null::extensions.geography, '84-88 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-33-6340-00', false, null, true),
  ('maison-magasin-jean-bruneau', 'Maison-magasin Jean-Bruneau', 'La construction de cette maison-magasin peut être située entre 1837 et 1849. En février 1837, le marchand de vêtements Jean Bruneau acquiert cet emplacement rue Notre-Dame avec une maison en pierre de deux étages. Avant 1849 d’après des représentations du quartier dessinées par John Murray, il fait bâtir une maison-magasin en pierre de taille de quatre étages avec une aile en arrière du côté ouest reliant le bâtiment à un entrepôt sur la rue Saint-Sulpice. Bruneau utilise lui-même le premier étage du bâtiment à des fins commerciales et les étages supérieurs comme résidence.', 'historic', 45.5051, -73.5563, 50, null::extensions.geography, '78-82 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-33-7151-00', false, null, true),
  ('immeuble-desmarais-robitaille', 'Immeuble Desmarais-Robitaille', 'Cet immeuble, conçu par l’architecte Georges-Alphonse Monette, est construit en 1929 pour la maison Desmarais & Robitaille, une entreprise spécialisée dans la vente d’articles religieux et d’ornements liturgiques. Il remplace une maison-magasin de deux étages avec combles datant du début du XIXe siècle. Pour répondre à ses besoins, Desmarais & Robitaille achète également en 1929 le bâtiment voisin à l’est.', 'historic', 45.5052, -73.5561, 50, null::extensions.geography, '70 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-33-8163-00', false, null, true),
  ('magasin-entrepot-merrill', 'Magasin-entrepôt Merrill', 'En 1866, Hyacinthe et Henry Merrill, sociétaires de H. & H. Merrill, font construire ce nouveau magasin-entrepôt de quatre étages qui remplace deux maisons-magasins qui n''étaient plus habitées mais seulement utilisées à des fins d''affaires. Le nouvel immeuble est terminé au début de 1867. Il a été conçu par l''architecte T. Fahrland et le contrat de décoration intérieure des deux premiers étages est confié à M. Andrea Molinelli, maître meublier et sculpteur. La société H. & H.', 'historic', 45.5053, -73.5561, 50, null::extensions.geography, '60 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-33-9074-00', false, null, true),
  ('maisons-magasins-de-lhotel-dieu', 'Maisons-magasins de l''Hôtel-Dieu', 'Les maisons-magasins de l''Hôtel-Dieu, dont il ne reste plus que des vestiges, sont construites en 1843. À partir des années 1820, les Religieuses hospitalières de Saint-Joseph de l''Hôtel-Dieu de Montréal décident de faire bâtir des immeubles locatifs sur le périmètre de leur terrain pour soutenir financièrement leurs œuvres au cœur du Vieux-Montréal. À l''été 1843, elles font ainsi construire six maisons-magasins de deux étages et demi sur la rue Saint-Joseph (rue Saint-Sulpice).', 'historic', 45.5049, -73.5561, 50, null::extensions.geography, '457-459 rue Saint-Sulpice', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-33-9940-00', false, null, true),
  ('edifice-alexandre-bourgeau', 'Édifice Alexandre-Bourgeau', 'La construction de cet immeuble de bureaux, oeuvre de l’architecte Alphonse Raza, débute en 1888 pour se terminer au début de l’année 1889. Le marchand et fabricant de produits alimentaires Alexandre Bourgeau acquiert d’abord le terrain en 1886 et y fait construire un premier bâtiment. Ce dernier est détruit lors d’un incendie durant l’hiver 1888. Bourgeau et le propriétaire voisin, l’imprimeur Louis Perrault, commandent alors à Raza la construction de deux immeubles identiques de six étages. Lors de leur inauguration, ils figurent parmi les édifices de bureaux les plus élevés à Montréal.', 'historic', 45.506, -73.5571, 50, null::extensions.geography, '31 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-34-0557-00', false, null, true),
  ('immeuble-themis', 'Immeuble Thémis', 'Le 5 avril 1927, l’architecte Jean-Julien Perrault acquiert quatre lots à l’angle des rues Saint-Laurent et Saint-Jacques. Deux jours plus tard, il vend le tout à Immeuble Themis ltée, une société qui entreprend les démarches pour construire un immeuble de bureaux. Elle engage à cette fin l’agence d’architectes Perrault et Gadbois dirigée par les architectes Joseph Roméo Gadbois et ... Jean-Julien Perrault. Tous les bâtiments sur le site sont détruits durant le printemps 1927 et le nouvel édifice est complété au début de l’année 1928.', 'architecture', 45.5062, -73.5563, 60, null::extensions.geography, '10-12 rue Saint-Jacques', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-34-6884-00', false, null, true),
  ('immeuble-mussen', 'Immeuble Mussen', 'Cet immeuble est construit en 1904-1905 d’après les plans de l’agence d’architectes MacVicar and Heriot. Il a été commandé par la succession de Thomas Mussen. L’immeuble remplace le bâtiment qui abrita longtemps le commerce de gros de Thomas Mussen, un marchand de tissus, d’articles de mercerie et de produits divers (dry goods). Le nouvel immeuble comprend à la fois des bureaux et des espaces pour exercer des activités commerciales.', 'historic', 45.5061, -73.556, 50, null::extensions.geography, '1 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-34-9573-00', false, null, true),
  ('magasin-entrepot-edwin-atwater-ii', 'Magasin-entrepôt Edwin-Atwater II', 'Propriétaire depuis 1854 du bâtiment à vocation commerciale sis sur cet emplacement, Edwin Atwater le fait démolir pour construire un nouveau magasin-entrepôt en 1858. Cet immeuble fait partie d’un ensemble de trois bâtiments contigus construits à la même époque pour deux propriétaires différents. En 1859, le commerce en gros de dry goods (tissus et divers articles de mercerie) Donnely Cameron Co. s’installe dans l’immeuble et l’occupe jusqu’en 1867. De 1858 à 1900 environ, le magasin-entrepôt restera la propriété de Edwin Atwater et de ses héritiers.', 'historic', 45.5023, -73.5557, 50, null::extensions.geography, '231 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-40-1247-00', false, null, true),
  ('magasin-entrepot-edwin-atwater-i', 'Magasin-entrepôt Edwin-Atwater I', 'Propriétaire depuis 1854 du bâtiment à vocation commerciale sis sur cet emplacement, Edwin Atwater le fait démolir pour construire un nouveau magasin-entrepôt en 1858. Le nouvel immeuble fait partie d’un ensemble de trois bâtiments contigus construits à la même époque pour deux propriétaires différents. De 1859 à 1864, le marchand de dry goods (tissus, articles de mercerie et peut-être autres produits) Andrew Robertson & Co. est le seul locataire ; son très court séjour annonce une instabilité qui caractérisera l’immeuble pendant de nombreuses années.', 'historic', 45.5024, -73.5557, 50, null::extensions.geography, '225-227 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-40-1554-00', false, null, true),
  ('magasin-entrepot-john-pratt-1858', 'Magasin-entrepôt John-Pratt [1858]', 'John Pratt, un important homme d’affaires de Montréal, acquiert le 221 St-Paul Ouest en 1858. Il fait démolir l’ancien bâtiment à vocation commerciale et résidentielle situé sur l’emplacement pour faire construire un magasin-entrepôt. Cet immeuble appartient à un ensemble de trois bâtiments contigus construits au même moment par deux propriétaires différents. Dès 1859, John Pratt occupe à lui seul le nouveau magasin-entrepôt. L’année suivante, il s’associe à Charles F. Pratt pour former John Pratt & Co., une société vouée au commerce en gros de cuir qui demeure dans le bâtiment jusqu’en 1870.', 'historic', 45.5025, -73.5556, 50, null::extensions.geography, '221 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-40-1861-00', false, null, true),
  ('magasin-entrepot-john-pratt-1865-1866', 'Magasin-entrepôt John-Pratt [1865-1866]', 'En 1865, John Pratt, un important homme d’affaires de Montréal, achète le bâtiment situé sur cet emplacement et fait aussitôt démolir l’immeuble à vocation commerciale qui s’y trouve. Au courant de l’année 1865-1866, Pratt fait construire un magasin-entrepôt à l’image de sa propriété voisine, soit le 221 St-Paul O. Dès 1866, le marchand en gros de dry goods (marchand importateur de tissus et d’articles de mercerie) Joseph May s’installe dans l’immeuble jusqu’en 1869.', 'historic', 45.5025, -73.5556, 50, null::extensions.geography, '215 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-40-2471-00', false, null, true),
  ('immeuble-william-hutchison', 'Immeuble William-Hutchison', 'Le marchand William Hutchison fait bâtir cet immeuble en 1818, sur un emplacement qu''il a acquis l''année précédente avec une maison en pierre et ses dépendances. Il engage le maître maçon Moses Knapp pour lui construire, sous la supervision de l''architecte et entrepreneur John Try, un bâtiment comprenant une maison-magasin de trois étages sur la rue Saint-Paul et un entrepôt de quatre étages sur la rue des Commissaires (place D''Youville) avec une cour intérieure desservit par deux portes cochères.', 'historic', 45.5022, -73.5553, 50, null::extensions.geography, '224-234 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-40-4528-00', false, null, true),
  ('maison-magasin-louis-tancrede-bouthillier-1837', 'Maison-magasin Louis-Tancrède-Bouthillier [1837]', 'Cette maison-magasin est construite en 1837. Louis-Tancrède Bouthillier, inspecteur de potasse, devient en 1833 propriétaire des biens de ses défunts parents comprenant cet emplacement de la rue Saint-Paul avec une maison en pierre de deux étages et dépendances. Quatre ans plus tard, le maçon Louis Comte est engagé pour y ériger une maison-magasin divisée en deux parties inégales. Le premier bail retrouvé de cet immeuble remonte à 1846, lorsque le papetier et relieur Robert Graham s’établit dans la partie est du bâtiment pour plusieurs années.', 'historic', 45.5025, -73.5553, 50, null::extensions.geography, '206 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-40-5860-01', false, null, true),
  ('immeuble-julien-perrault', 'Immeuble Julien-Perrault', 'Julien Perrault, marchand de bois, fait construire cet immeuble en 1831. Perrault était propriétaire de l’emplacement et d’une maison en pierre de deux étages par la donation que lui en avait fait sa mère, Marie-Anne Tavernier, en 1816. Conçu principalement pour le commerce mais aussi pour l’habitation, le nouvel immeuble se trouve à proximité du port et à l’angle de deux axes commerciaux majeurs. Il semble que William et Cyrus Brewster, quincailliers, y établissent leur commerce et leur résidence à compter de 1833.', 'historic', 45.5026, -73.5552, 50, null::extensions.geography, '200 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-40-6370-01', false, null, true),
  ('immeuble-benjamin-berthelet', 'Immeuble Benjamin-Berthelet', 'Ce bâtiment est construit en 1834-1835. Le médecin Benjamin Berthelet obtient en juin 1833 cet emplacement avec deux maisons en pierre de deux étages par donation de sa mère, Marguerite Viger. À l’automne, Berthelet engage le maître maçon Jean-Baptiste Soubre dit Saint-Jean pour lui construire le nouveau bâtiment. Celui-ci est principalement conçu pour le commerce, quoiqu’il ait peut-être servi à des fins résidentielles pendant quelques années. La firme de marchands de Baltimore Thomas McAdam & Company en devient la première locataire.', 'historic', 45.5027, -73.5551, 50, null::extensions.geography, '363 rue Saint-François-Xavier', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-40-6799-02', false, null, true),
  ('maison-pierre-berthelet-1805', 'Maison Pierre-Berthelet [1805]', 'Le marchand et propriétaire foncier Pierre Berthelet fait vraisemblablement construire cette maison entre 1805 et 1809. Berthelet acquiert en 1804 un emplacement au coin des rues de la Capitale et Saint-François-Xavier avec une maison et ses dépendances. Il achète la continuation de ce terrain des Commissaires pour le démantèlement des fortifications en 1805. Dans un bail de 1809, il loue à l’aubergiste Joseph Tourelle une maison en pierre de trois étages qui couvre tout le lot et qui semble bien être le bâtiment actuel.', 'historic', 45.5026, -73.5548, 50, null::extensions.geography, '185-187 place D''Youville', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-40-8076-00', false, null, true),
  ('maison-joseph-athanase-normandeau', 'Maison Joseph-Athanase-Normandeau', 'Joseph-Athanase Normandeau fait construire cette maison en 1827. Ayant appartenu aux défunts Jean-Baptiste Deleigne et Geneviève Piette, cet emplacement sur lequel est bâtie une maison en pierre de trois étages devient en 1823 la propriété unique de Normandeau et de son épouse Thérèse Deleigne, fille des défunts. À la suite d’un incendie survenu à l’automne 1826 et ayant consumé tout le bâtiment, Normandeau engage les maçons Vital Gibault et Louis Tribot dit Lafricain pour le rebâtir.', 'historic', 45.5027, -73.5548, 50, null::extensions.geography, '181 place D''Youville', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-40-8482-00', false, null, true),
  ('edifice-william-watson-ogilvie', 'Édifice William-Watson-Ogilvie', 'En 1890, l’important homme d’affaires William W. Ogilvie achète cette propriété sur la place D’Youville et fait construire cet immeuble. Ce bâtiment, oeuvre de l’agence d’architectes Hutchison and Steele, remplace trois magasins construits vers le milieu des années 1850. Fait inusité, une partie de la façade d’un ancien magasin, donnant sur la rue du Port, est intégrée à la nouvelle construction. Il faut attendre l’année 1903 avant que le bureau d’architectes Hutchison and Wood harmonise la façade de cette section avec le reste du bâtiment.', 'historic', 45.502, -73.5546, 50, null::extensions.geography, '224 place D''Youville', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-40-9905-00', false, null, true),
  ('magasin-entrepot-harrison-stephens-ii', 'Magasin-entrepôt Harrison-Stephens II', 'L’homme d’affaire montréalais d’origine américaine Harrison Stephens fait construire, en 1868, un ensemble formé de deux magasins-entrepôts au coin nord-est des rues Saint-Paul et Saint-François-Xavier. À cet endroit, se trouvait auparavant un bâtiment dont la fonction était commerciale. Il fut démoli pour faire place aux nouvelles constructions. Stephens est propriétaire de ce bâtiment et de son voisin jusqu’à sa mort en 1881. Ce magasin-entrepôt compte deux occupants d’origine qui se partagent l’espace pour une année seulement.', 'historic', 45.5029, -73.5554, 50, null::extensions.geography, '191 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-41-4010-00', false, null, true),
  ('magasin-entrepot-frothingham-and-workman', 'Magasin-entrepôt Frothingham and Workman', 'Entre 1858 et 1868. John Frothingham et sa fille Louisa acquièrent deux lots sur lesquels on retrouve trois bâtiments en pierre de trois étages. John Frothingham décède en 1870 et ses enfants poursuivent le projet. Les trois bâtiments, occupés par diverses petites entreprises, sont démolis à l''été 1871 pour faire place au nouveau magasin-entrepôt, dessiné par George Browne et érigé en moins de deux mois. Ce nouveau bâtiment joint l’entrepôt Louisa Goddard situé à l’arrière. La quincaillerie Frothingham & Workman Co.', 'historic', 45.5034, -73.5553, 50, null::extensions.geography, '157-163 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-41-4063-01', false, null, true),
  ('entrepot-louisa-goddard-frothingham', 'Entrepôt Louisa-Goddard-Frothingham', 'La quincaillerie Frothingham and Workman Co. achète en août 1852 de Jacob DeWitt un terrain de forme irrégulière où se trouvaient un magasin en pierre donnant sur la rue Saint-Paul et une écurie. Le tout est en ruines à la suite d''un incendie majeur ayant détruit plusieurs immeubles à l''est de la place Royale. Sur l''emplacement de l''écurie, la compagnie fait construire en 1855 un entrepôt de quatre étages et demi, selon les plans de George Browne. Le premier occupant en 1856 est le marchand de cuir Seymour and Whitney Co.', 'historic', 45.5035, -73.5554, 50, null::extensions.geography, null, 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-41-4063-04', false, null, true),
  ('magasin-entrepot-harrison-stephens-i', 'Magasin-entrepôt Harrison-Stephens I', 'En 1868, l’homme d’affaire montréalais Harrison Stephens fait construire un ensemble de deux magasins-entrepôts au coin nord-est des rues Saint-Paul et Saint-François-Xavier. Sur cet emplacement se trouvait auparavant un bâtiment commercial qui sera démoli pour faire place aux nouvelles constructions. Le propriétaire constructeur n’a jamais occupé lui-même ce magasin-entrepôt. Il l’a plutôt loué à diverses entreprises dont la première est celle d’Anthony McKeand, un agent manufacturier qui l’occupe seulement un an, de 1870 à 1871.', 'historic', 45.503, -73.5553, 50, null::extensions.geography, '185 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-41-4418-00', false, null, true),
  ('maison-magasin-john-mckenzie', 'Maison-magasin John-McKenzie', 'Cette maison-magasin, telle que nous pouvons la voir aujourd''hui, date de 1829. Au printemps de cette année-là, le marchand John McKenzie, un des associés de la firme Hector Russel & Company (dry goods), achète l''emplacement avec une maison en pierre de deux étages et un autre bâtiment, ainsi qu''un lot contigu rue Saint-François-Xavier. Trois mois plus tard, il engage le maître maçon Louis Comte pour effectuer des transformations majeures à la maison: la façade est démolie et refaite en pierre de taille bouchardée et un étage est ajouté.', 'historic', 45.5031, -73.5553, 50, null::extensions.geography, '171 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-41-4635-00', false, null, true),
  ('maison-pierre-berthelet-1822', 'Maison Pierre-Berthelet [1822]', 'Cette maison-magasin est bâtie en 1822. À la suite d''un incendie, Pierre Berthelet, propriétaire de l''emplacement depuis 1784, engage le maçon et entrepreneur Joseph Godard dit Lapointe pour rebâtir deux maisons en pierre de trois étages. L''une d''elles, celle se trouvant du côté nord-est du lot, est aujourd''hui l''immeuble au 177-179, rue Saint-Paul Ouest. Le marchand Isidore Malo en devient vraisemblablement le premier locataire.', 'historic', 45.503, -73.5553, 50, null::extensions.geography, '177-179 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-41-4825-00', false, null, true),
  ('maison-magasin-marguerite-barron', 'Maison-magasin Marguerite-Barron', 'On ignore les circonstances entourant la construction de l''immeuble actuel. En 1842, Marguerite Barron, épouse en secondes noces de Charles M. Delisle, acquerrait la propriété de la succession de Pierre Foretier, propriété sur laquelle était érigée une ancienne maison de pierre à deux étages. De toute évidence, la construction du bâtiment actuel daterait de la période entre cette acquisition et la première mention de Benjamin Workman, pharmacien et chimiste, comme locataire en 1845 dans l''annuaire MacKay. Workman occupa le bâtiment jusqu''en 1855.', 'historic', 45.5032, -73.5549, 50, null::extensions.geography, '370 place Royale', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-41-7541-00', false, null, true),
  ('maison-magasin-denis-benjamin-viger', 'Maison-magasin Denis-Benjamin-Viger', 'Acquise par Denis Viger vers 1780, cette parcelle demeura entre les mains de ses descendants pendant presque deux siècles et généra des revenus de location. À la suite du partage de la succession de Viger en 1814, son fils Denis-Benjamin devenait propriétaire de deux maisons en pierre à deux étages alors érigées sur le terrain. En 1841, il engagea Augustin Laberge, maître menuisier et entrepreneur, pour la construction d''une bâtisse en pierre taillée de trois étages qui occuperait entièrement le lot.', 'historic', 45.5036, -73.5547, 50, null::extensions.geography, '359 place Royale', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-41-9798-00', false, null, true),
  ('entrepot-john-ostell', 'Entrepôt John-Ostell', 'L’immeuble John Ostell occupe l’emplacement du premier séminaire des sulpiciens, appelé aussi Château de Maisonneuve, construit vers 1663. Vendu par les sulpiciens en 1716, ces derniers le rachètent en 1842, pour le louer aussitôt au quincaillier Frothingham & Workman Co. Ce vieux bâtiment est détruit à l''été 1852 dans un incendie qui dévaste le secteur de la rue Saint-Paul à l''est de la place Royale. Les sulpiciens font construire immédiatement un nouvel entrepôt, dessiné par John Ostell. En 1853 la quincaillerie Frothingham & Workman Co s’y installe de nouveau.', 'historic', 45.5037, -73.5552, 50, null::extensions.geography, '147 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-42-4600-01', false, null, true),
  ('magasin-entrepot-tracey-wilson', 'Magasin-entrepôt Tracey-Wilson', 'Ann Tracey et son mari Charles Wilson font probablement ériger ce bâtiment en 1853-1854 sur un terrain acquis un an plus tôt. À cet endroit, se trouvait auparavant une maison-magasin qui a été détruite lors de l’important incendie du 6 juin 1852. La première entreprise à prendre place dans l’immeuble, et à l’occuper en entier, est Brown, Swan & Co., une compagnie spécialisée dans la vente en gros de dry goods (tissus, articles de mercerie et peut-être d’autres produits). Elle n’y demeure pas très longtemps, soit trois ans, de 1854 à 1857.', 'historic', 45.5042, -73.5548, 50, null::extensions.geography, '105 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-42-8759-00', false, null, true),
  ('magasin-entrepot-beaudry-sebastopol', 'Magasin-entrepôt Beaudry-Sébastopol', 'Ce magasin-entrepôt a été construit en 1858 par Jean-Louis Beaudry, homme d’affaires et politicien montréalais. Il a acquis le terrain en 1852-1853, alors que s’y trouvent les ruines d’une maison-magasin, démolie par l’important incendie du 6 juin 1852. Après cinq ans de démêlés judiciaires, Beaudry réussit à faire valoir ses droits sur le terrain et peut ainsi entreprendre la construction du magasin-entrepôt. Il fait inscrire dans la pierre les lettres JL BEAUDRY et SEBASTOPOL, sûrement pour commémorer la célèbre bataille de 1855. L''architecte est Michel Laurent.', 'historic', 45.5043, -73.5547, 50, null::extensions.geography, '101 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-42-9067-00', false, null, true),
  ('magasins-de-lhotel-dieu-ix', 'Magasins de l''Hôtel-Dieu IX', 'Les Religieuses hospitalières de Saint-Joseph font construire ce magasin-entrepôt en 1873-1874 sur le site de leur ancien hôpital, détruit en 1860. Oeuvre de l’architecte Henri-Maurice Perrault, il comprend quatre des quatorze magasins-entrepôts conçus lors de la troisième et dernière phase de construction des magasins de l''Hôtel-Dieu. L’immeuble est d’abord occupé par des marchands et des grossistes.', 'historic', 45.5053, -73.5556, 50, null::extensions.geography, '59-71 rue De Brésoles', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-43-1973-00', false, null, true),
  ('magasins-de-lhotel-dieu-viii', 'Magasins de l''Hôtel-Dieu VIII', 'Les Religieuses hospitalières de Saint-Joseph font construire ce magasin-entrepôt en 1873-1874 sur le site de leur ancien hôpital, détruit en 1860. Oeuvre de l’architecte Henri-Maurice Perrault, il fait partie des quatorze magasins-entrepôts conçus lors de la troisième et dernière phase de construction des magasins de l''Hôtel-Dieu. Entre 1875 et 1890, le marchand de meubles Adolphe Bélanger se sert de l’immeuble comme entrepôt pour son commerce situé dans le bâtiment voisin de la rue Notre-Dame.', 'historic', 45.5055, -73.5555, 50, null::extensions.geography, '55-57 rue De Brésoles', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-43-3196-00', false, null, true),
  ('magasins-de-lhotel-dieu-iv', 'Magasins de l''Hôtel-Dieu IV', 'Les Religieuses hospitalières de Saint-Joseph font construire cet immeuble en 1871-1872 sur le site de leur ancien hôpital, détruit en 1860. L’architecte Michel Laurent en dessine les plans, s’inspirant des magasins voisins de la rue Saint-Paul réalisés dix ans auparavant. L''immeuble comprend six des onze magasins-entrepôts conçus lors de la seconde phase de construction des magasins de l''Hôtel-Dieu. Les premiers occupants, essentiellement des marchands et des grossistes, s’installent en 1872. En octobre 1874, un incendie détruit complètement un magasin-entrepôt.', 'historic', 45.5049, -73.5553, 50, null::extensions.geography, '425-445 rue Saint-Sulpice', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-43-4527-00', false, null, true),
  ('magasins-de-lhotel-dieu-iii', 'Magasins de l''Hôtel-Dieu III', 'Les Religieuses hospitalières de Saint-Joseph font construire cet immeuble en 1871-1872 sur le site de leur ancien hôpital, détruit en 1860. L’architecte Michel Laurent en dessine les plans, s’inspirant des magasins-entrepôts voisins de la rue Saint-Paul réalisés dix ans auparavant. L''immeuble comprend cinq des onze magasins-entrepôts conçus lors de la seconde phase de construction des magasins de l''Hôtel-Dieu. Les premiers occupants, essentiellement des grossistes, s’installent en 1872. Dans la nuit du 13 janvier 1886, un incendie détruit complètement le magasin-entrepôt du quincaillier B.', 'historic', 45.5052, -73.5551, 50, null::extensions.geography, '50-62 rue De Brésoles', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-43-6170-00', false, null, true),
  ('magasins-de-lhotel-dieu-ii', 'Magasins de l''Hôtel-Dieu II', 'Les Religieuses hospitalières de Saint-Joseph font construire cet immeuble en 1861 sur le site de leur ancien hôpital, détruit en 1860. L''immeuble, oeuvre de l''architecte Victor Bourgeau, comprend quatre des dix magasins-entrepôts conçus lors de la première phase de construction des magasins de l''Hôtel-Dieu. Au moment où s''achève la construction du bâtiment, en 1861, le gouvernement britannique doit faire face à la menace américaine. Il envoie donc des milliers de soldats à Montréal.', 'historic', 45.5046, -73.5547, 50, null::extensions.geography, '85-87 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-43-9102-00', false, null, true),
  ('magasin-entrepot-genin-trudeau', 'Magasin-entrepôt Genin-Trudeau', 'Dans les années 1860, la succession Louis Plessis Bélair possède sur la rue Notre-Dame un vieil immeuble de trois étages en pierre, à l''arrière duquel se trouvent une dépendance et une cour intérieure. En 1867, la succession Bélair entreprend la démolition des bâtiments et vend le lot vacant à Louis Boyer. Celui-ci fait aussitôt construire un magasin-entrepôt de cinq étages. Le premier et seul occupant en 1868 est le tailleur et marchand de tissus James Morrison Co.', 'historic', 45.5056, -73.5558, 50, null::extensions.geography, '38-42 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-44-0804-00', false, null, true),
  ('magasin-entrepot-louis-masson', 'Magasin-entrepôt Louis-Masson', 'En 1892-1893, la succession Masson fait ériger ce magasin-entrepôt de trois étages. Il est conçu par la firme d''architectes Perrault et Mesnard avec la participation du sculpteur Henry Beaumont. Le bâtiment porte le nom d''un membre de la succession Masson, Louis Masson, le fils de Joseph Masson, autrefois seigneur de Terrebonne. La Société des arts du Canada, « établie dans le but de répandre le goût des arts, d''encourager et d''aider les artistes », occupe l''immeuble en entier de 1893 à 1901. Ils sont suivis, entre 1902 et 1908, par la librairie Cadieux, Derome et Cie.', 'historic', 45.5056, -73.5557, 50, null::extensions.geography, '30-34 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-44-1317-00', false, null, true),
  ('maison-magasin-cuvillier-ostell', 'Maison-magasin Cuvillier-Ostell', 'Au printemps 1836, l’encanteur et courtier Augustin Cuvillier désirant moderniser l’apparence de sa maison en pierre de trois étages datant du début du siècle, engage le maçon James Peddie et le charpentier William Crockford pour en refaire la façade en pierre de taille conformément au plan de l’architecte John Ostell. L’immeuble, qui prend les traits des maisons-magasins, est divisé en espaces commerciaux au rez-de-chaussée, alors que les étages supérieurs sont voués à l’habitation.', 'historic', 45.506, -73.5557, 50, null::extensions.geography, '4 rue Notre-Dame Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-44-3541-01', false, null, true),
  ('magasins-de-lhotel-dieu-vii', 'Magasins de l''Hôtel-Dieu VII', 'Les Religieuses hospitalières de Saint-Joseph font construire ce magasin-entrepôt en 1873-1874 sur le site de leur ancien hôpital, détruit en 1860. Oeuvre de l’architecte Henri-Maurice Perrault, il fait partie des quatorze magasins-entrepôts conçus lors de la troisième et dernière phase de construction des magasins de l''Hôtel-Dieu. Il se distingue des autres magasins-entrepôts du complexe par sa localisation particulière sur le plan cadastral. Plus large que ses voisins, une grande partie de l’immeuble se retrouve privée de source lumineuse naturelle.', 'historic', 45.5057, -73.5554, 50, null::extensions.geography, '51-53 rue De Brésoles', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-44-4011-00', false, null, true),
  ('edifice-metropole', 'Édifice Métropole', 'L’histoire de cet édifice est étonnante. Érigé en 1903-1904, il est déplacé de son emplacement d’origine et reconstruit à l’identique à l’angle des rues Notre-Dame et Saint-Laurent en 1928-1929. En 1903-1904, la Banque d’Ottawa fait ériger ce gratte-ciel de dix étages sur la rue Saint-Jacques d’après les plans de l’architecte d’origine américaine Howard Colton Stone. L’immeuble de bureaux atteint alors la hauteur maximale autorisée (environ 130 pieds).', 'architecture', 45.5062, -73.5553, 60, null::extensions.geography, '4 rue Notre-Dame Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-44-4680-00', false, null, true),
  ('magasins-de-lhotel-dieu-x', 'Magasins de l''Hôtel-Dieu X', 'Les Religieuses hospitalières de Saint-Joseph font construire cet immeuble, qui comprend trois magasins-entrepôts mitoyens, en 1888-1889. Il remplace trois magasins-entrepôts conçus par Henri-Maurice Perrault en 1873-1874 et détruits lors d’un incendie le 13 janvier 1886 . Les magasins-entrepôts de 1888-1889 comptent trois étages, deux de moins que ceux construits quinze ans plus tôt. Ils reprennent toutefois essentiellement le vocabulaire architectural des immeubles précédents, les baies cintrées du rez-de-chaussée en moins.', 'historic', 45.5056, -73.555, 50, null::extensions.geography, '19 cours Le Royer', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-44-6811-00', false, null, true),
  ('magasins-de-lhotel-dieu-vi', 'Magasins de l''Hôtel-Dieu VI', 'Les Religieuses hospitalières de Saint-Joseph font construire cet immeuble en 1873-1874 sur le site de leur ancien hôpital, détruit en 1860. Oeuvre de l’architecte Henri-Maurice Perrault, il comprend à l’origine deux magasins-entrepôts mitoyens de cinq étages. Ils font partie des quatorze magasins-entrepôts conçus lors de la troisième et dernière phase de construction des magasins de l''Hôtel-Dieu. Les magasins-entrepôts restent vacants durant les premières années, puis des marchands s’y installent à la fin des années 1870.', 'historic', 45.5057, -73.5552, 50, null::extensions.geography, '433 rue Saint-Dizier', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-44-6811-02', false, null, true),
  ('maison-du-barreau', 'Maison du Barreau', 'En 1984, une importante entreprise canadienne de produits pharmaceutiques, d''équipement d''hôpitaux et de cliniques dentaires, la maison Casgrain et Charbonneau Ltée avait, depuis quelques années, laissé vacant son immeuble de la rue Saint-Laurent. Le Barreau, dont le membership était en pleine expansion, désirait regrouper tous ses services disséminés à travers la ville de Montréal et privilégiait un emplacement à proximité du nouveau Palais de justice. Construit en 1942 suivant les plans de Ludger Venne, l''édifice Casgrain et Charbonneau répondait à leurs critères.', 'historic', 45.5061, -73.5548, 50, null::extensions.geography, '445-465 boulevard Saint-Laurent', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-44-8667-00', false, null, true),
  ('immeuble-joseph-moise-valois', 'Immeuble Joseph-Moïse-Valois', 'Cet immeuble est construit en 1886 par le notaire et libraire Joseph-Moïse Valois. Il remplace une maison-magasin en pierre de trois étages avec combles. En 1886, Valois vient tout juste de rompre son association d’affaires avec son beau-frère, le libraire et imprimeur Charles-Odilon Beauchemin. Valois loue d’abord son immeuble à la maison Desaulniers Frères & Cie, des fabricants et importateurs de statues et d’articles religieux, et à Adélard Boucher, un marchand de musique en feuilles. Valois n’y installe son commerce de livres que durant quelques années, entre 1891 et 1895.', 'historic', 45.5066, -73.555, 50, null::extensions.geography, '32-36 rue Notre-Dame Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-45-6924-00', false, null, true),
  ('caserne-de-pompiers-no-2', 'Caserne de pompiers no 2', 'La décision de prolonger la rue Saint-Jacques à l''est de Saint-Gabriel, jusqu''au Palais de Justice, entraîne la démolition de l''ancienne caserne de pompiers no 6. On choisit de la relocaliser sur la partie nord d''un terrain appartenant à la succession de Robert Hallowell, sur lequel se trouve un vieil entrepôt occupé par un marchand de café. L''expropriation a lieu au printemps 1871 et les soumissions sont acceptées en juillet. En mai 1872, la nouvelle caserne entre en fonction.', 'historic', 45.5067, -73.5547, 50, null::extensions.geography, '444-448 rue Saint-Gabriel', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-45-9129-00', false, null, true),
  ('annexe-du-vieux-palais-de-justice', 'Annexe du Vieux-Palais-de-Justice', 'Le gouvernement du Québec fait construire cet édifice en 1903-1905. Sa conception est confiée aux architectes du ministère de la Colonisation et des Travaux publics, dont les plans sont révisés par N. A. Cantin, un architecte canadien établi à New York. À l’été 1902, Lomer Gouin, le ministre de la Colonisation et des Travaux publics, annonce la construction de l’annexe du palais de justice. Les travaux débutent durant l’été 1903 avec la démolition de la plus vieille église protestante de Montréal, voire du Canada : l’église presbytérienne St. Gabriel (érigée en 1792).', 'historic', 45.5076, -73.5556, 50, null::extensions.geography, '85 rue Notre-Dame Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-46-4111-00', false, null, true),
  ('vieux-palais-de-justice-de-montreal', 'Vieux palais de justice de Montréal', 'À la suite de l’incendie du palais de justice de Montréal (1799-1803), survenue en 1844, le gouvernement du Canada-Uni lance en octobre 1849 un concours d’architecture en vue de la construction d’une nouvelle « maison de justice » sur le même site. La prestigieuse commande est remportée par les architectes John Ostell et Henri-Maurice Perrault, devant le réputé George Browne. Les contrats avec les entrepreneurs sont octroyés en novembre 1850 et les travaux débutent au printemps de l’année 1851.', 'historic', 45.508, -73.555, 50, null::extensions.geography, '155 rue Notre-Dame Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-46-7464-00', false, null, true),
  ('entrepot-pierre-beaudry', 'Entrepôt Pierre-Beaudry', 'Le commerçant Pierre Beaudry fait bâtir cet entrepôt en 1828. Beaudry est devenu le seul propriétaire de l''emplacement avec une maison et des écuries en bois en 1823. Cinq ans plus tard, il engage le maçon Louis Comte pour y construire un entrepôt en pierre de trois étages. Tout indique qu''à l''origine le bâtiment sert à des fins strictement commerciales, peut-être pour le compte de Beaudry ou pour d''autres marchands, jusqu''au début des années 1840.', 'historic', 45.5022, -73.5541, 50, null::extensions.geography, '201-207 rue de la Commune Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-50-4235-00', false, null, true),
  ('immeuble-du-montreal-sailors-institute', 'Immeuble du Montreal Sailors'' Institute', 'En 1875, le Montreal Sailors’ Institute(MSI) s’installe sur cet emplacement pour desservir les marins de la marine marchande en escale à Montréal. Par la suite, le nombre des marins qui utilisent les services du MSI croît au rythme des activités portuaires. En 1940, les anciens bâtiments sont trop exigus et, en plein conflit mondial, le Conseil d’administration de l’organisme demande à l’architecte C.R.Titley de concevoir les plans pour un nouvel édifice. La construction est cependant retardée jusqu’en 1953 à cause d’une pénurie de matériaux et de main d’œuvre.', 'historic', 45.5029, -73.5546, 50, null::extensions.geography, '165-169 place D''Youville', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-51-0415-00', false, null, true),
  ('magasin-entrepot-hannibal-whitney', 'Magasin-entrepôt Hannibal-Whitney', 'En 1852, lors de l’important incendie survenu dans le secteur de la Place Royale, la propriété de H. H. Whitney est détruite. L’année suivante, en 1853-1854, il fait démolir les ruines du bâtiment incendié et construire un ensemble de deux magasins-entrepôts de quatre étages. Un seul a survécu. Ce magasins-entrepôt accueille son premier occupant en 1854, Alexander Walker, marchand de dry goods (tissus, articles de mercerie, peut-être d''autres produits).', 'historic', 45.5036, -73.5544, 50, null::extensions.geography, '355 place Royale', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-51-1892-00', false, null, true),
  ('boyers-block', 'Boyer''s Block', 'Situé aux abords de la Place Royale, cet immeuble est construit en 1857 par l’homme d’affaires Louis Boyer; le Boyer’s Block (le nom est taillé dans la pierre du côté de place Royale) demeure longtemps aux mains de la famille Boyer. Louis Boyer fait construire ce bâtiment sur un emplacement acquis la même année de la Champlain & St. Lawrence Railroad Co. Sur le site se trouvaient alors les ruines de deux maisons-magasins appartenant auparavant à John Molson et détruites lors d’un important incendie en juin 1852.', 'historic', 45.5036, -73.5542, 50, null::extensions.geography, '133 rue de la Commune Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-51-3588-00', false, null, true),
  ('magasin-entrepot-william-lyman', 'Magasin-entrepôt William-Lyman', 'En juin 1852, l’incendie qui dévaste le secteur de la Place Royale détruit une maison-magasin située sur cet emplacement. Dans les mois qui suivent, William Lyman achète le terrain et fait construire un magasin-entrepôt de quatre étages. La construction est terminée au printemps 1854 mais l’immeuble reste vacant. C’est seulement en 1855 que Benjamin et Henry Lyman, les frères du propriétaire, et leur associé Alfred Savage, apothicaires et grossistes en produits pharmaceutiques sous la raison sociale de Lyman Savage & Co., s’y installent.', 'historic', 45.5039, -73.5544, 50, null::extensions.geography, '116 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-52-1723-00', false, null, true),
  ('magasin-entrepot-william-murray', 'Magasin-entrepôt William-Murray', 'Propriétaire depuis quelques années d’une maison-magasin située sur ce terrain, William Murray la voit partir en fumée lors de l’incendie de juin 1852 dans le secteur de la Place Royale. Il fait aussitôt construire un magasin-entrepôt de trois étages qui accueille ses premiers occupants en 1853. La propriété demeure aux mains du constructeur et de sa famille jusqu’en 1934.', 'historic', 45.5042, -73.5543, 50, null::extensions.geography, '100-104 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-52-2542-01', false, null, true),
  ('magasin-entrepot-william-cormack', 'Magasin-entrepôt William-Cormack', 'Au cours de l’important incendie de juin 1852 dans le secteur de la Place Royale, la maison-magasin de William Cormack est détruite. Il procède aussitôt à la construction d’un nouveau magasin-entrepôt de trois étages qui accueille ses premiers occupants au printemps 1853. Les deux espaces locatifs seront occupés, pendant plusieurs années, par les locataires de l’ancien bâtiment: les commerçants Cumming & Galbraith et la société Archibald Laurie & Co., marchands de tissus et d’étoffes (dry goods).', 'historic', 45.504, -73.5543, 50, null::extensions.geography, '110-112 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-52-2542-02', false, null, true),
  ('edifice-london-house-coffee', 'Édifice London House Coffee', 'Peter Charles Larkin, propriétaire de la Salada Tea Co., achète en 1910, de Marie-Louise et Marie-Malvina Généreux, un immeuble qu''il occupe déjà depuis 1895. Il y a en effet ouvert la succursale montréalaise de son entreprise d''importation et de transformation de thé. Après l''achat, Larkin procède à la démolition du bâtiment de pierre qui y était érigé et fait construire en 1911 un magasin-entrepôt de même dimension au sol, mais plus élevé (cinq étages) et plus solide (béton renforcé).', 'historic', 45.5044, -73.5543, 50, null::extensions.geography, '90 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-52-2675-00', false, null, true),
  ('magasin-entrepot-racine', 'Magasin-entrepôt Racine', 'En avril 1885, George B. Burland fait l''acquisition d''un lot dans le quartier Centre auprès du shérif du district de Montréal. On y trouve alors un magasin sur la rue Saint-Paul datant de 1859 et un entrepôt sur la rue des Commissaires. Ces bâtiments sont réduits en cendres lors d''un incendie en mars 1886. Burland commande peu après la construction d''un magasin-entrepôt de quatre étages à l''architecte John James Brown. Le bâtiment est complété à la fin de 1886 ou au début de 1887. Le magasin-entrepôt est d''abord loué à la R.', 'historic', 45.5047, -73.5539, 50, null::extensions.geography, '60 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-52-4891-01', false, null, true),
  ('magasin-entrepot-paul-galarneau', 'Magasin-entrepôt Paul-Galarneau', 'En 1853, Paul Médard Galarneau et Charles Damase Roy font l''acquisition d''une maison de pierre de trois étages sur la rue Saint-Paul dans laquelle ils déménagent leur commerce (maison Galarneau et Roy). Peu après le décès de Roy, en 1859, Galarneau y installe son propre commerce de dry goods (tissus, articles de mercerie et produits divers), la maison P. M. Galarneau et Cie. Selon toute vraisemblance, Galarneau fait construire un nouveau magasin-entrepôt pour son commerce en 1874-1875. Le bâtiment, de style néo-renaissance, possède quatre étages à l''origine. La maison P. M.', 'historic', 45.5047, -73.5541, 50, null::extensions.geography, '64 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-52-4891-02', false, null, true),
  ('magasin-entrepot-alexandre-roy', 'Magasin-entrepôt Alexandre-Roy', 'En 1853, la maison Galarneau et Roy, des marchands de dry goods (tissus, articles de mercerie et produits divers), acquiert du shérif de Montréal une propriété sur laquelle on retrouve une maison. Selon toute vraisemblance, on démolit la maison au début de l''année suivante puis on entame peu après la construction d''un magasin-entrepôt de trois étages. Le bâtiment aurait été terminé dès l''été 1854. En 1854-1855, l''immeuble est occupé par l''encanteur Jean Dominique Bernard et des grossistes en quincaillerie.', 'historic', 45.5046, -73.5542, 50, null::extensions.geography, '66 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-52-4891-03', false, null, true),
  ('magasin-entrepot-de-la-congregation-methodiste-st-james', 'Magasin-entrepôt de la congrégation méthodiste St. James', 'En 1861, la congrégation méthodiste St. James fait l''acquisition d''une maison de deux étages et demi datant environ de la fin du XVIIIe siècle. Elle fait démolir cette maison au printemps de 1866 et elle confie aux architectes Cyrus P. et William T. Thomas le soin d''ériger un magasin-entrepôt de quatre étages. Le bâtiment est terminé à la fin de 1866. Le magasin-entrepôt est loué vers le début de 1867 à la maison Foulds & Hodgson, des marchands de dry goods (tissus, articles de mercerie et produits divers) qui occupent déjà le bâtiment voisin à l''ouest.', 'historic', 45.5045, -73.5542, 50, null::extensions.geography, '70 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-52-4891-04', false, null, true),
  ('entrepot-greenshields-hodgson-racine-ltd', 'Entrepôt Greenshields, Hodgson, Racine Ltd.', 'En 1933, les compagnies Greenshields Ltd., Hodgson, Sumner & Co. et A. Racine ltée se fusionnent. Ces importantes entreprises de commerce en gros dans le domaine des tissus et de la mercerie occupent alors plusieurs édifices situés dans le quadrilatère compris entre les rues Saint-Dizier, Saint-Sulpice, Saint-Paul et des Commissaires - l’actuelle rue de la Commune - dont le 65 de la rue de la Commune. Le 6 mars 1963 à 20h 30, un violent incendie se déclare à cet endroit en pleine tempête de neige.', 'historic', 45.5044, -73.5539, 50, null::extensions.geography, '65-71 rue de la Commune Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-52-4891-05', false, null, true),
  ('entrepot-charles-lamontagne', 'Entrepôt Charles-Lamontagne', 'Construit en 1830, l''entrepôt Charles Lamontagne est localisé sur une propriété comprise entre les rues de la Commune et Saint-Paul. L''emplacement est acquis par le marchand Charles Lamontagne en 1823-1824. À la toute fin de l''année 1829, ce dernier engage le maçon Vital Gibault pour la construction d''une « voûte » (entrepôt) de quatre étages en pierre sur la rue de la Commune. Les travaux sont terminés vers la fin du mois de septembre 1830. L''entrepôt est d''abord loué au marchand Norman Bethune.', 'historic', 45.5046, -73.5538, 50, null::extensions.geography, '61-63 rue de la Commune Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-52-4891-06', false, null, true),
  ('immeuble-jean-louis-beaudry', 'Immeuble Jean-Louis-Beaudry', 'Copropriétaire depuis 1863 d’une auberge sise sur cet emplacement, Jean-Louis Beaudry rachète les parts de son associé et, en 1866, fait construire un immeuble de quatre étages, conçu par l’architecte Michel Laurent. Il s''agit d''un bâtiment à l’occupation complexe où prédominent les fonctions de commerce et de bureau. La vocation du bâtiment est étroitement liée aux activités portuaires. Au moment de la construction, il y a quatre unités locatives au rez-de-chaussée, deux au sous-sol et dix unités aux étages, que des regroupements progressifs feront chuter à quatre.', 'historic', 45.5041, -73.5539, 50, null::extensions.geography, '101-105 rue de la Commune Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-52-5540-00', false, null, true),
  ('magasins-de-lhotel-dieu-i', 'Magasins de l''Hôtel-Dieu I', 'Les Religieuses hospitalières de Saint-Joseph font construire cet immeuble en 1861 sur le site de leur ancien hôpital, détruit en 1860. Le bâtiment, oeuvre de l''architecte Victor Bourgeau, comprend six des dix magasins-entrepôts conçus lors de la première phase de construction des magasins de l''Hôtel-Dieu. L’immeuble est à peine terminé qu’on lui trouve une vocation inusitée.', 'historic', 45.505, -73.5545, 50, null::extensions.geography, '45-83 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-53-0844-00', false, null, true),
  ('magasins-de-lhotel-dieu-v', 'Magasins de l''Hôtel-Dieu V', 'En 1873, les Religieuses hospitalières de Saint-Joseph mandatent l’architecte Albert Mesnard, un employé du bureau de l’architecte Henri-Maurice Perrault, pour la conception de cet immeuble qui comprend trois magasins-entrepôts mitoyens. Complété en 1874, il fait partie de la troisième et dernière phase de construction des magasins de l’Hôtel-Dieu, laquelle comprend onze autres unités réalisées par Henri-Maurice Perrault. En 1874, les Hospitalières louent l’immeuble aux grossistes en alimentation Villeneuve & Lacaille.', 'historic', 45.5054, -73.5543, 50, null::extensions.geography, '405-411 rue Saint-Dizier', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-53-2284-00', false, null, true),
  ('maison-magasin-francois-perrin', 'Maison-magasin François-Perrin', 'Cette maison-magasin est construite en 1835. Au cours des années 1830-1831, François Perrin acquiert cet emplacement situé sur la rue Saint-Paul, enfermé de deux côtés par les clôtures des terrains de la Congrégation Notre-Dame et de l''Hôtel-Dieu, avec une maison en pierre d’un étage. Le 31 janvier 1835, Perrin conclut un marché avec Charles Larceneur, maître maçon, pour ériger une maison en pierre grise de trois étages avec, en arrière du côté est, une aile en brique de la même hauteur, le tout selon les plans des entrepreneurs Trudeau et Grenier.', 'historic', 45.5054, -73.5541, 50, null::extensions.geography, '9-11 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-53-3985-00', false, null, true),
  ('magasin-entrepot-masson-i', 'Magasin-entrepôt Masson I', 'En 1854, Edward Wilson entreprend la construction de ce magasin-entrepôt. En juillet de la même année, il vend le lot à Ann Tracey, épouse de Charles Wilson. Ce dernier est alors l''administrateur des biens de Ann Tracey puisqu''elle lui a signé une procuration générale en août 1853. C''est donc vraisemblablement lui qui poursuit et complète les travaux. Le bâtiment constitue alors l’extrémité Ouest d’une série de cinq magasins-entrepôts. Ces cinq nouveaux bâtiments remplacent plusieurs bâtiments de pierre ayant accueilli auparavant principalement des commerces, mais aussi des habitations.', 'historic', 45.5055, -73.554, 50, null::extensions.geography, '1-3 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-53-4497-00', false, null, true),
  ('magasin-entrepot-esprit-genereux', 'Magasin-entrepôt Esprit-Généreux', 'Cet immeuble est construit en 1886, vraisemblablement par l''architecte Michel Laurent. L''échevin Esprit A. Généreux achète d''abord le terrain en 1884 auprès des marchands John et Joseph Shuter. Deux ans plus tard, en mars 1886, un incendie détruit la plupart des bâtiments de la propriété. Généreux fait alors construire un nouveau magasin-entrepôt, lequel a trois étages sur la rue Saint-Paul et quatre étages sur la rue de la Commune.', 'historic', 45.5049, -73.5539, 50, null::extensions.geography, '40-50 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-53-5827-00', false, null, true),
  ('magasin-entrepot-alfred-larocque', 'Magasin-entrepôt Alfred-Larocque', 'François Alfred Chartier Larocque fait construire en 1869 un magasin entrepôt de trois étages sur le côté sud de la rue Saint-Paul (l''édifice comporte quatre étages du côté de la rue de la Commune). L’édifice en pierre de taille sur trois côtés possède une toiture en gravier et ardoise et occupe toute la superficie du lot, contrairement au bâtiment précédent démoli quelques mois plus tôt et qui abritait deux logements au-dessus d’un commerce tenu par un marchand de vin. Avec la construction du nouveau bâtiment, la volumétrie augmente et la fonction résidentielle disparaît.', 'historic', 45.505, -73.5538, 50, null::extensions.geography, '34 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-53-6443-00', false, null, true),
  ('immeuble-robert-unwin-harwood', 'Immeuble Robert-Unwin-Harwood', 'Le quincaillier Robert Unwin Harwood fait construire cet immeuble en 1824-1825. Harwood achète en 1824 l''emplacement avec les ruines d''une maison et ses dépendances. Il engage Joseph Russell Bronsdon et George Cliff pour faire la charpenterie du nouvel immeuble comprenant une maison-magasin sur la rue Saint-Paul et un entrepôt longeant le côté est du lot jusqu''à la rue des Commissaires (rue de la Commune). La quincaillerie William Harwood & Company occupe la moitié est du bâtiment, alors que l''autre moitié est louée par le marchand James Connell.', 'historic', 45.5052, -73.5537, 50, null::extensions.geography, '20-24 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-53-7060-00', false, null, true),
  ('maison-magasin-elizabeth-mittleberger-platt', 'Maison-magasin Elizabeth-Mittleberger-Platt', 'Élisabeth Mittleberger Platt fait construire cette maison-magasin en 1822-1823. La succession de George Platt, dont Mittleberger est l''exécutrice testamentaire, achète l''emplacement en juillet 1822, avec les ruines d''une maison et d''un entrepôt. L''entrepreneur Isaac Shay est engagé pour construire la maison-magasin et un entrepôt donnant sur la rue des Commissaires (de la Commune). La société de chimistes et d''apothicaires Joseph Beckett & Company devient la première locataire des deux bâtiments en mai 1823.', 'historic', 45.5053, -73.5538, 50, null::extensions.geography, '12 rue Saint-Paul Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-53-7677-01', false, null, true),
  ('entrepot-elizabeth-mittleberger-platt', 'Entrepôt Elizabeth-Mittleberger-Platt', 'Élisabeth Mittleberger Platt fait construire cet entrepôt en 1822-1823. La succession de George Platt, dont Mittleberger est l''exécutrice testamentaire, achète l''emplacement en juillet 1822, avec les ruines d''une maison et d''un entrepôt. L''entrepreneur Isaac Shay est engagé pour construire l''entrepôt et une maison donnant sur la rue Saint-Paul. L''entreprise de chimistes et d''apothicaires Joseph Beckett & Company devient la première locataire des bâtiments en mai 1823. L''immeuble de la rue des Commissaires est utilisé à la fois à des fins d''entreposage et de commerce.', 'historic', 45.5052, -73.5535, 50, null::extensions.geography, '3 rue de la Commune Ouest', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-53-7677-02', false, null, true),
  ('edifice-salada', 'Édifice Salada', 'L’édifice Salada est construit en 1917 par la Greater Montreal Land Investment Company. Il a été conçu par l’architecte Alphonse Piché. En 1914, la Greater Montreal Land Investment Company achète un lot que la Ville de Montréal a récemment exproprié afin de prolonger le boulevard Saint-Laurent vers le port. Trois ans plus tard, la compagnie y fait construire cet immeuble, lequel sert d’entrepôt jusqu’à son achat en septembre 1920 par la Salada Tea Company. Jusqu''au début de 1921, on y aménage les bureaux, les espaces d’entreposage et les installations manufacturières de la compagnie.', 'architecture', 45.5059, -73.5541, 60, null::extensions.geography, '2 rue Le Royer', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-54-4039-00', false, null, true),
  ('maison-simon-mctavish', 'Maison Simon-McTavish', 'En 1786, Simon McTavish, « le grand marquis » du commerce des fourrures, est devenu le premier occupant de cette maison nouvellement construite par le négociant Richard Dobie. Cette nouvelle résidence, conçue « in the English taste », remplaçait une ancienne maison en pierre à un étage que Dobie avait achetée en 1780. Lors de la location par McTavish, la forme de la maison était sensiblement différente de celle qu''on voit aujourd''hui.', 'historic', 45.5061, -73.5541, 50, null::extensions.geography, '411-425 rue Saint-Jean-Baptiste', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-54-4075-00', false, null, true),
  ('maison-pierre-joseph-perrault', 'Maison Pierre-Joseph-Perrault', 'Tout indique que le négociant Pierre-Joseph Perrault fait construire cette maison vers 1820. Perrault acquiert l''emplacement et une maison, sans description, du partage de la succession de son père en septembre 1816. Dix ans plus tard, il loue à sa sœur Agathe la maison en brique de trois étages, incluant le rez-de-chaussée. Bien que le bâtiment ne soit vraisemblablement utilisé au départ que pour l''habitation, à compter des années 1830, il sert aussi au commerce, se conformant ainsi aux caractéristiques d''utilisation des maisons-magasins.', 'historic', 45.5058, -73.5538, 50, null::extensions.geography, '3 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-54-5829-01', false, null, true),
  ('magasin-entrepot-masson-ii', 'Magasin-entrepôt Masson II', 'En 1854, Edward Wilson entreprend la construction de ce magasin-entrepôt. En juillet de la même année, il vend le lot à Ann Tracey, épouse de Charles Wilson. Ce dernier est alors l''administrateur des biens de Ann Tracey puisqu''elle lui a signé une procuration générale en août 1853. C''est donc vraisemblablement lui qui poursuit et complète les travaux. À l’origine, le magasin-entrepôt constitue l’extrémité Est d’une série de cinq magasins-entrepôts qui remplacent plusieurs bâtiments de pierre ayant accueilli auparavant divers commerçants et quelques habitations.', 'historic', 45.5057, -73.5539, 50, null::extensions.geography, '1 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-54-5829-03', false, null, true),
  ('magasin-entrepot-bourgouin-et-duchesneau', 'Magasin-entrepôt Bourgouin et Duchesneau', 'En mars 1889, la succession de Claude Melançon acquiert de la Banque Jacques-Cartier une propriété à l’intersection des rues Saint-Paul et Saint-Jean-Baptiste sur laquelle on retrouve une maison en pierre et des dépendances. Dans les mois suivants, les propriétaires y font entreprendre la construction d’un magasin-entrepôt dont les travaux se terminent en 1890. L’immeuble loge d’abord la maison de commerce Bourgouin, Duchesneau & Cie, des grossistes spécialisés dans la vente de tissus, d’articles de mercerie et de produits divers (dry goods, fancy goods and small wares).', 'historic', 45.506, -73.5538, 50, null::extensions.geography, '21 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-54-6760-02', false, null, true),
  ('maison-magasin-macdonell-holmes', 'Maison-magasin Macdonell-Holmes', 'Cette maison-magasin est construite en 1835 à la demande des marchands de dry goods (tissus, articles de mercerie et peut-être autres produits) Macdonell Holmes & Company. En 1832, les associés de l’entreprise acquièrent un emplacement avec une maison et dépendances qu’ils occupent depuis plusieurs années. Au printemps 1835, ils font appel aux architectes Thompson and Parry pour concevoir cette maison-magasin de trois étages, incluant le rez-de-chaussée. L’entreprise occupe les lieux jusqu’en 1839.', 'historic', 45.5062, -73.5536, 50, null::extensions.geography, '37-39 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-54-8179-00', false, null, true),
  ('magasin-entrepot-marie-helene-jodoin', 'Magasin-entrepôt Marie-Hélène-Jodoin', 'Marie-Hélène Jodoin, épouse d''Amable Jodoin fils, acquiert cette propriété en 1872 de l''épicier en gros Victor Hudon qui y occupe alors un bâtiment commercial. Elle fait immédiatement démolir le bâtiment et ses dépendances et entame la construction d''un magasin-entrepôt de plus grande dimension couvrant toute la superficie du lot. Les premiers occupants sont le fabricant de chaussures et de bottes Zéphirin Lapierre et l''épicier en gros Joseph Hudon. Au début des années 1880, Lapierre quitte l''immeuble ; Joseph Hudon en devient ainsi l''unique occupant jusqu''à son départ en 1893.', 'historic', 45.5056, -73.5534, 50, null::extensions.geography, '8 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-54-9014-00', false, null, true),
  ('maison-clement-sabrevois-de-bleury', 'Maison Clément-Sabrevois de Bleury', 'En 1912, la Librairie Beauchemin est installée à cet endroit. Il s’agit des derniers édifices à être intégrés au complexe de la rue Saint-Gabriel par la Librairie Beauchemin Limitée. Celle-ci y a rehaussé la façade d’un étage et y a remplacé un toit à deux versant par un toit plat dont nous voyons encore la marque sur l’édifice voisin. Lorsque Beauchemin déménage en 1964, l’auberge Le Vieux Saint-Gabriel s’y installe et, en 1969, ces deux édifices sont en pleine restauration.', 'historic', 45.5065, -73.5543, 50, null::extensions.geography, '428-430 rue Saint-Gabriel', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-55-3402-01', false, null, true),
  ('entrepot-de-la-compagnie-du-nord-ouest', 'Entrepôt de la Compagnie du Nord-Ouest', 'À la fin du XVIIIe siècle, la société McTavish, Frobisher & Company, qui contrôle la Compagnie du Nord-Ouest, acquiert la plupart des lots compris dans le quadrilatère formé des rues Saint-Paul, de Vaudreuil, Sainte-Thérèse et Saint-Gabriel. C''est ainsi qu''en 1796, la propriété de Antoine Janson dit Lapalme, sur laquelle se trouvait une maison de pierre, est achetée par Joseph Frobisher. À la suite de cette acquisition, McTavish, Frobisher & Company semble avoir fait reconstruire la maison en lui donnant des dimensions plus imposantes.', 'historic', 45.5067, -73.5536, 50, null::extensions.geography, '94 rue Sainte-Thérèse', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-55-7636-00', false, null, true),
  ('edifice-duchesneau-trudeau-i', 'Édifice Duchesneau-Trudeau I', 'Cet édifice, le plus ancien de l''ensemble Duchesneau-Trudeau, est construit au printemps 1910 d''après les plans de l''architecte Cajétan Dufort. Il se trouve sur un terrain acheté en mars 1909 de la succession Simon Valois, important propriétaire foncier de son époque. Un petit bâtiment est alors érigé sur la rue Saint-Paul, probablement de deux ou trois étages, avec porte cochère et ne couvrant que la partie avant du lot. Tous les hangars, écuries et autres dépendances à l''arrière ont été démolis quelques années plus tôt.', 'historic', 45.5064, -73.5535, 50, null::extensions.geography, '79 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-55-8110-01', false, null, true),
  ('edifice-duchesneau-trudeau-iii', 'Édifice Duchesneau-Trudeau III', 'Cet édifice est construit par Duchesneau-Trudeau Ltée vers 1938 et occupe un lot appartenant à l''entreprise depuis juillet 1909. Sur ce terrain se trouvait un immeuble commercial en pierre de trois étages et demie et un entrepôt construit en 1913 à l''arrière du lot. Vers 1938, Duchesneau-Trudeau Ltée fait démolir tous les bâtiments et fait appel aux architectes R. R. Tourville et Lucien Parent pour la conception de l''actuel magasin-entrepôt de sept étages. L''entreprise occupe entièrement l''immeuble jusqu''à la vente de tout l''ensemble en 1978.', 'historic', 45.5065, -73.5534, 50, null::extensions.geography, '81 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-55-8110-02', false, null, true),
  ('edifice-duchesneau-trudeau-ii', 'Édifice Duchesneau-Trudeau II', 'Ce bâtiment construit par la compagnie Duchesneau-Trudeau Ltée est érigé sur un terrain acquis en 1938. La compagnie fait d''abord démolir un bâtiment de quatre étages, qui a longtemps été utilisé comme manufacture de bottes et souliers, puis, probablement durant l''année 1938, fait construire un immeuble de deux étages avec sous-sol où elle y aménage ses services de réception et d''expédition. En 1940, Duchesneau-Trudeau Ltée achète les deux bâtiments adjacents.', 'historic', 45.5066, -73.5536, 50, null::extensions.geography, '415 rue Saint-Gabriel', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-55-8110-03', false, null, true),
  ('entrepot-hudon-et-orsali', 'Entrepôt Hudon et Orsali', 'Les grossistes en alimentation Hudon & Orsali font construire cet entrepôt en 1912 selon les plans de l''architecte Joseph-Ovide Turgeon. Pour Hudon & Orsali, il s''agit d''un agrandissement, puisque la compagnie possède l''immeuble mitoyen qui donne sur la rue Saint-Paul. Le président de Hudon & Orsali, Albert Hudon, fait l''acquisition de la propriété en 1911. Le site comprend à ce moment des bâtiments ayant été reliés à la fin du XIXe siècle. L''imprimeur et libraire Jean-Baptiste Rolland fils avait pu profiter de cet aménagement en y installant la Compagnie d''Imprimerie Moderne dès 1901.', 'historic', 45.507, -73.5535, 50, null::extensions.geography, '110 rue Sainte-Thérèse', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-55-8865-02', false, null, true),
  ('edifice-de-la-sauvegarde', 'Édifice de La Sauvegarde', 'En 1914, la compagnie d''Assurance-Vie La Sauvegarde inaugure son nouveau siège social, un immeuble de dix étages situé sur la rue Notre-Dame est. Le projet de construction a nécessité, en 1912, la démolition de quelques bâtiments dont deux petites maisons de pierre qui avaient été utilisées comme magasin au XIXe siècle. Les architectes Saxe & Archibald conçoivent un immeuble qui souligne la réussite de l''entreprise canadienne-française fondée par Guillaume-Narcisse Ducharme en 1901. La Sauvegarde occupe le 7e étage ainsi qu''une partie du 8e étage de l''immeuble durant plus de 60 ans.', 'architecture', 45.5076, -73.5541, 60, null::extensions.geography, '150-152 rue Notre-Dame Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-56-3534-00', false, null, true),
  ('maison-jean-baptiste-guillon-duplessis', 'Maison Jean-Baptiste-Guillon-Duplessis', 'En 1803, un incendie touche durement ce quartier, détruisant l''ancien ensemble conventuel des jésuites (converti en prisons et en église anglicane sous les Britanniques), l''hôtel Vaudreuil, qui abrite le collège de Montréal, et plusieurs résidences privées. La propriété de Jean-Baptiste Guillon dit Duplessis est épargnée de ces ravages. Vers la fin des années 1800, il profite cependant de la revitalisation du quartier occasionnée par la construction du palais de justice sur le terrain des jésuites et de l''établissement du Marché Neuf sur l''ancien terrain du collège.', 'historic', 45.5078, -73.5542, 50, null::extensions.geography, '160 rue Notre-Dame Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-56-3653-00', false, null, true),
  ('hotel-riendeau', 'Hôtel Riendeau', 'Construit par Joseph Roy de 1852 à 1853 sur les ruines d''une ancienne auberge, ce bâtiment de quatre étages en pierre de taille est aussitôt occupé par l''hôtel Saint-Nicolas. Loué de 1862 à 1869 comme mess des Grenadiers (St. Nicolas Hall), il connaît par la suite diverses affectations: auberge, bureaux de professionnels, École des Arts et Design. En 1879, l''immeuble est intégré à l''hôtel Richelieu de la rue Saint-Vincent, tenu par Isidore Brien dit Durocher.', 'historic', 45.5078, -73.5538, 50, null::extensions.geography, '452-454 place Jacques-Cartier', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-56-6856-01', false, null, true),
  ('immeuble-berthe-hurtubise', 'Immeuble Berthe-Hurtubise', 'Au printemps 1837, l’aubergiste Séraphino Giraldi décide de moderniser la maison en pierre de deux étages qu’il a tout récemment acquise des héritiers Parthenais. Il fait rehausser le bâtiment d’un étage, démolir et reconstruire la façade en pierre de taille. Deux adjonctions en brique liant la maison-magasin à un entrepôt en pierre dans la cour sont aussi ajoutées. L’immeuble, qui prend les traits d’une maison-magasin, est destiné au commerce et à l’habitation.', 'historic', 45.5078, -73.5536, 50, null::extensions.geography, '444-448 place Jacques-Cartier', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-56-6856-02', false, null, true),
  ('entrepot-edward-william-gray', 'Entrepôt Edward-William-Gray', 'Les numéros 427 et 437 rue Saint-Vincent constituent le seul ensemble commercial datant du XVIIIe siècle. Edward William Gray, shérif et marchand de Montréal, a assemblé ce lot à la suite d''une série de quatre transactions entre 1770 et 1783. Il faisait construire les immeubles actuels en deux temps. La partie nord (437 rue Saint-Vincent) fut conçue pour être une voûte « à l''épreuve de feu » joignant le pignon sud d''une maison déjà existante démolie vers 1785. Cette voûte servait d''entrepôt et de magasins pour les encans de marchandises reçues par Gray.', 'historic', 45.5074, -73.5537, 50, null::extensions.geography, '437 rue Saint-Vincent', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-56-8210-01', false, null, true),
  ('maison-edward-william-gray', 'Maison Edward-William-Gray', 'Les numéros 427 et 437 rue Saint-Vincent constituent le seul ensemble commercial datant du XVIIIe siècle. Edward William Gray, shérif et marchand de Montréal, a assemblé ce lot à la suite de quatre transactions effectuées entre 1770 et 1783. Il faisait construire les immeubles actuels en deux temps. La partie nord (437 rue Saint-Vincent) était au départ une voûte « à l''épreuve de feu » joignant le pignon sud d''une maison déjà existante démolie vers 1785. Cette voûte servait d''entrepôt et de magasins pour les encans de marchandises reçues par Gray.', 'historic', 45.5073, -73.5536, 50, null::extensions.geography, '427-429 rue Saint-Vincent', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-56-8210-02', false, null, true)
insert into public.landmarks (slug, name, description, category, latitude, longitude, geofence_radius_m, geofence_polygon, address, neighbourhood, source_name, source_url, source_license, source_record_id, needs_review, review_note, is_active) values
  ('magasin-entrepot-seraphino-giraldi', 'Magasin-entrepôt Séraphino-Giraldi', 'Propriétaire depuis 1827, d’une maison-magasin située sur le terrain du 438-442 Place Jacques-Cartier, Séraphino Giraldi la fait démolir en 1866 et la remplace par ce magasin-entrepôt de quatre étages conçu par l’architecte Henri-Maurice Perreault. À l’origine, le nouvel immeuble abrite deux magasins ; au milieu des années 1870 puis à d’autres moments, un troisième espace locatif s’ajoute, aménagé aux étages supérieurs soit de l’unité sud, soit de l’unité nord. Les premiers occupants du magasin-entrepôt sont des épiciers : le propriétaire constructeur ainsi que la société Hudon & Béliveau.', 'historic', 45.5077, -73.5535, 50, null::extensions.geography, '438-442 place Jacques-Cartier', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-56-9043-00', false, null, true),
  ('edifice-chaussegros-de-lery-i', 'Édifice Chaussegros-de-Léry I', 'Cet immeuble de bureaux est construit entre 1989 et 1991 par la Société immobilière du patrimoine architectural de Montréal (SIMPA) et des partenaires du secteur privé. Conçu par l’architecte Dan Hanganu, il s’agit de la première phase du complexe Chaussegros-de-Léry. La Ville de Montréal loue tout l’immeuble et signe un bail de 20 ans avec les propriétaires. Elle y installe plusieurs de ses services, dont la plupart logeaient auparavant au marché Bonsecours et dans l’édifice de la Banque canadienne nationale sur la place d’Armes.', 'historic', 45.5095, -73.5536, 50, null::extensions.geography, '303 rue Notre-Dame Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-58-9878-01', false, null, true),
  ('edifice-chaussegros-de-lery-ii', 'Édifice Chaussegros-de-Léry II', 'Cet édifice est construit entre 1993 et 1996 par la Société immobilière du patrimoine architectural de Montréal (SIMPA) et des partenaires du secteur privé. Conçu par l’architecte Dan Hanganu, il s’agit de la deuxième phase du complexe Chaussegros-de-Léry. L’édifice compte une centaine d’appartements en copropriété ainsi que des commerces au rez-de-chaussée. Le projet vise clairement à accroître la population résidante du Vieux-Montréal. Ce bâtiment en forme de U est construit en deux étapes.', 'historic', 45.51, -73.5535, 50, null::extensions.geography, '309-329 rue Notre-Dame Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-58-9878-02', false, null, true),
  ('ancienne-annexe-de-lhotel-de-ville', 'Ancienne annexe de l''Hôtel-de-Ville', 'Au début des année 1910, les autorités municipales confient à la firme d’architectes Marchand et Haskell la construction de l’édifice devant accueillir les quartiers de la police et la Cour du Recorder, aujourd''hui la Cour municipale. Un ancien temple anglican, transformé successivement en théâtre et en manufacture, et des résidences construites vers le milieu du XIXe siècle sur les rues Champ-de-Mars et Saint-Louis sont entre autres démolis pour réaliser le projet. Les travaux s’échelonnent de 1912 à 1913 et l’édifice, de style Beaux-Arts, est inauguré en janvier 1914.', 'historic', 45.5099, -73.5542, 50, null::extensions.geography, '775 rue Gosford', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-59-4811-01', false, null, true),
  ('ancien-quartier-general-de-la-police', 'Ancien quartier général de la police', 'Déjà dans les années 1930, la Ville de Montréal est à l''étroit dans ses locaux. Les services municipaux sont en expansion et on doit loger le personnel dans des édifices de fortune disséminés sur le territoire. D''autre part, la cour municipale et le quartier général de la police occupent l''Annexe de l''hôtel de ville depuis son inauguration en 1914. Ces locaux sont devenus insuffisants et la Ville souhaite rapatrier ses différents services dans le secteur de l''hôtel de ville. Ce contexte vient donc favoriser l''idée d''un agrandissement de l''Annexe de l''hôtel de ville.', 'historic', 45.5103, -73.5538, 50, null::extensions.geography, '750 rue de Bonsecours', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-59-4811-02', false, null, true),
  ('magasin-entrepot-louis-archambeault', 'Magasin-entrepôt Louis-Archambeault', 'Le notaire et homme politique Louis Archambeault fait construire ce magasin-entrepôt en 1882-1883. À l''origine, il est occupé entièrement par le manufacturier de souliers et de bottes Zéphirin Lapierre. Au milieu des années 1890, l''entreprise de Lapierre emploie des dizaines d''employés et produit, selon une source de l’époque, environ 1 000 paires de chaussures par jour. Elle quitte l’immeuble en 1899. Le bâtiment sert ensuite, sauf exception, à des activités strictement commerciales.', 'historic', 45.5059, -73.5533, 50, null::extensions.geography, '24 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-64-0140-00', false, null, true),
  ('magasin-entrepot-jean-leclaire', 'Magasin-entrepôt Jean-Leclaire', 'C’est en 1870 que Jean Leclaire fait construire ce magasin-entrepôt. Le terrain sur lequel est construit le bâtiment avait été acquis en 1853 ou 1854 par Jean et François Leclaire. À cet endroit, se trouve alors un bâtiment dont la fonction est commerciale et résidentielle ; peut-être s’agit-il d’une maison-magasin. À partir de 1853-1854, l’entreprise de dry goods F. & J. Leclaire occupe cet ancien bâtiment et le destine uniquement à des activités commerciales jusqu’en 1870, alors qu’il est décidé de faire construire le magasin-entrepôt actuel.', 'historic', 45.506, -73.5533, 50, null::extensions.geography, '28-30 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-64-0550-00', false, null, true),
  ('magasin-entrepot-narcisse-desmarteau', 'Magasin-entrepôt Narcisse-Desmarteau', 'C’est en 1854 que le marchand montréalais Narcisse B. Desmarteau fait construire ce magasin-entrepôt. À cet endroit se trouvait auparavant un bâtiment qui était probablement une maison-magasin et qui a été démolie pour faire place à la nouvelle construction. Les premiers occupants du magasin-entrepôt sont Louis Plamondon, marchand de dry goods & clothing (tissus, articles de mercerie et peut-être d''autres produits) et Desmarteau, Plamondon & Mousseau, compagnie du propriétaire constructeur, qui fait elle aussi dans le dry goods & clothing.', 'historic', 45.5061, -73.5532, 50, null::extensions.geography, '36-40 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-64-1061-00', false, null, true),
  ('magasin-entrepot-hector-lamontagne', 'Magasin-entrepôt Hector-Lamontagne', 'Le marchand d’articles de cuir Siméon Delorme fait construire ce magasin-entrepôt en 1882-1883. Delorme achète la propriété au début de l’année 1882, puis il engage l’agence d’architectes Perrault et Mesnard pour la construction du bâtiment. Dès le printemps, on procède à la démolition des bâtiments sur les lieux, notamment une maison en pierre de deux étages du début du XIXe siècle. Un an plus tard, l’immeuble est terminé : il compte alors quatre étages sur la rue Saint-Paul et cinq étages sur la rue de la Commune (incluant les rez-de-chaussée).', 'historic', 45.5064, -73.5529, 50, null::extensions.geography, '92-94 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-64-3299-00', false, null, true),
  ('edifice-duchesneau-trudeau-iv', 'Édifice Duchesneau-Trudeau IV', 'C''est sur un lot acquis en 1944 que la compagnie Duchesneau-Trudeau Ltée fait ériger ce bâtiment en 1951, quatre ans après qu''un incendie eût ravagé le site. La compagnie fait d''abord démolir une très ancienne maison datant de la fin du XVIIIe siècle, puis mandate l''architecte J. Z. Gauthier pour la construction d''un nouveau magasin-entrepôt de trois étages. Des ouvertures pratiquées dans les murs mitoyens permettent de communiquer avec les autres bâtiments de la compagnie. Après la vente de tous les bâtiments de l''ensemble Duchesneau-Trudeau en 1978, l''immeuble devient inoccupé.', 'historic', 45.5066, -73.5533, 50, null::extensions.geography, '83-85 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-65-0321-00', false, null, true),
  ('immeuble-hudon-et-orsali', 'Immeuble Hudon et Orsali', 'Les grossistes en alimentation Hudon & Orsali font construire cet immeuble en 1904 selon les plans de l’architecte Joseph Sawyer. Plusieurs bâtiments dont démolis pour faire place à cet immeuble imposant, notamment une maison-magasin de trois étages et demi de la première moitié du XIXe siècle. Le nouveau bâtiment dispose d’espaces d’entreposage qui comprennent d’immenses caves à vins et de vastes bureaux. La maison Hudon & Orsali occupe les lieux jusqu’à la fin des années 1940.', 'historic', 45.5068, -73.5532, 50, null::extensions.geography, '105 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-65-0845-00', false, null, true),
  ('magasin-entrepot-jean-baptiste-rolland', 'Magasin-entrepôt Jean-Baptiste-Rolland', 'Libraire de grande renommée, Jean-Baptiste Rolland acquiert la propriété en 1855, procède à la démolition de la maison-magasin qui s’y trouve et fait construire en 1856 un nouveau magasin-entrepôt de quatre étages. Rolland quitte alors la maison-magasin où il résidait et tenait boutique pour s’installer dans le nouvel immeuble. Ce dernier répond mieux aux besoins croissants du commerce de détail et facilite la transition de l’entreprise vers la vente en gros et l’édition. Le magasin-entrepôt accueille la librairie et les entrepôts de Rolland, ainsi que des ateliers d’impression et de reliure.', 'historic', 45.507, -73.5533, 50, null::extensions.geography, '410 rue Saint-Vincent', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-65-0862-02', false, null, true),
  ('magasin-entrepot-persillier-dit-lachapelle', 'Magasin-entrepôt Persillier-dit-Lachapelle', 'Ce magasin-entrepôt est construit en 1868 par la succession Persillier dit Lachapelle. Il s''agit très probablement d''une reconstruction après un incendie, le rez-de-chaussée étant très semblable à celui de l''imposante maison-magasin remplacée, construite environ 25 ans plus tôt et dont la fonction était mixte, soit commerciale et résidentielle. L’architecte du nouveau bâtiment est Narcisse Larue. Le magasin-entrepôt comprend à l’origine deux espaces locatifs de différentes grandeurs. Le bâtiment accueille donc deux premiers occupants. Durant onze ans, de 1869 à 1880, William L.', 'historic', 45.5069, -73.553, 50, null::extensions.geography, '111-115 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-65-2451-00', false, null, true),
  ('magasin-entrepot-come-seraphin-cherrier', 'Magasin-entrepôt Côme-Séraphin-Cherrier', 'Ce magasin entrepôt occupe la partie ouest du vaste lot 95, lequel lot couvre presque tout le quadrilatère, hormis l''édifice au coin de la rue Saint-Paul et de la place Jacques-Cartier. Le lot 95 appartient depuis 1861 à Côme Séraphin Cherrier, et plusieurs bâtiments chargés d''histoire y sont érigés. Sur la partie ouest qui nous concerne se trouvent deux bâtiments en pierre. Le premier édifice, sur la rue Saint-Paul, est occupé depuis de très nombreuses années par le marchand de tabac Jean-Baptiste Desroches, relayé en 1870 par Maurice A. Desroches.', 'historic', 45.5071, -73.553, 50, null::extensions.geography, '153-155 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-65-2573-00', false, null, true),
  ('maison-de-la-minerve', 'Maison de La Minerve', 'Charpentier, sculpteur et marchand, Denis Viger s''établissait à l''angle des rues Saint-Paul et Saint-Vincent où il rassemblait des lots pour créer un plus grand terrain, processus terminé en 1783. Ayant déjà construit une maison (qui n''existe plus) sur le coin des deux rues, il engageait en 1800 le maçon André Auclair pour lui en construire une plus grande, une maison en pierre à deux étages avec toit mansardé, sur un terrain vacant contigu à sa résidence. Une fois la nouvelle maison terminée, Viger l''occupa pendant deux ans avant de la louer à des marchands.', 'historic', 45.5071, -73.5528, 50, null::extensions.geography, '161-163 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-65-3581-00', false, null, true),
  ('magasin-entrepot-amable-prevost-i', 'Magasin-entrepôt Amable-Prévost I', 'Ce bâtiment fait partie de l’ensemble magasins-entrepôts Prévost qui comprend aussi le 100 Saint-Paul Est. Les deux bâtiments, qui en formaient un à l’origine, ont été construits en 1864 par le marchand montréalais Amable Prévost. Ce dernier a fait démolir ce qui était probablement une maison-magasin pour ériger le nouvel immeuble. Le premier occupant du magasin-entrepôt d’origine est Amable Prévost & Co., une entreprise de vente en gros d’articles de dry goods (tissus, articles de mercerie et peut-être d''autres produits), d’épicerie et de provisions diverses.', 'historic', 45.5065, -73.5528, 50, null::extensions.geography, '98 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-65-3709-00', false, null, true),
  ('magasin-entrepot-amable-prevost-ii', 'Magasin-entrepôt Amable-Prévost II', 'Ce bâtiment fait partie de l’ensemble magasins-entrepôts Prévost qui comprend aussi le 98 Saint-Paul Est. Les deux bâtiments, qui en formaient un à l’origine, ont été construits en 1864 par le marchand montréalais Amable Prévost. Ce dernier a fait démolir ce qui était probablement une maison-magasin pour permettre l’érection du nouveau bâtiment. Le premier occupant du magasin-entrepôt est Amable Prévost & Co., une entreprise de vente en gros d’articles de dry goods (tissus, articles de mercerie et peut-être d''autres produits), d’épicerie et de provisions diverses.', 'historic', 45.5065, -73.5528, 50, null::extensions.geography, '100 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-65-4115-00', false, null, true),
  ('immeuble-simon-valois-ii', 'Immeuble Simon-Valois II', 'Tout indique que le bourgeois Simon Valois fait relier en 1858 une maison-magasin et un entrepôt bâtis huit ans plus tôt pour former ce magasin-entrepôt. Propriétaire de l''emplacement depuis 1840, Valois avait fait construire, après un incendie au printemps 1850, une maison-magasin de trois étages sur la rue Saint-Paul vouée au commerce et à l''habitation ainsi qu''un entrepôt de quatre étages sur la rue des Commissaires (rue de la Commune) dédié au commerce. En septembre 1858, l''entreprise E. Hudon Fils & Cie loue les deux bâtiments pour le 1er mai suivant et s''engage d''ici-là à les rénover.', 'historic', 45.5066, -73.5527, 50, null::extensions.geography, '104 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-65-4829-02', false, null, true),
  ('magasin-entrepot-john-pratt', 'Magasin-entrepôt John-Pratt', 'En 1874, John Pratt, de son vrai nom Jean-Baptiste Pratt, et son frère Charles-Ferdinand acquièrent ce terrain de la succession de Joseph Normandeau. Les frères Pratt font aussitôt démolir les deux vieux bâtiments en pierre qui s''y trouvent et y font ériger un magasin-entrepôt de cinq étages, terminé vers le début de 1875. En juin 1876, John Pratt achète la part de son frère. Il décède le mois suivant. Deux locataires occupent l''immeuble en 1875 : l''épicier en gros Gaucher Telmosse Co. et le marchand de tissus Joseph N. Dupuis. Après quelques années, Gaucher Telmosse Co.', 'historic', 45.5069, -73.5526, 50, null::extensions.geography, '120-124 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-65-5953-00', false, null, true),
  ('magasin-entrepot-ricard', 'Magasin-entrepôt Ricard', 'C’est la succession Ricard, formée de Louis Ricard et de Mme Louis H. Latour, qui fait construire ce magasin-entrepôt en 1877-1878. Sur le terrain, se trouve alors une ancienne maison-magasin qui n’a plus de fonction résidentielle depuis le début des années 1860 et qui sera démolie. Au départ, le bâtiment accueille trois locataires qui occupent des espaces de dimension et de valeur inégales. Ces premiers occupants, des marchands, n’y demeurent pas très longtemps. Le tout premier, l’épicier Joseph Robitaille, occupe une partie de l’espace durant un an, de 1878 à 1879.', 'historic', 45.507, -73.5525, 50, null::extensions.geography, '130 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-65-6365-00', false, null, true),
  ('magasin-entrepot-victor-hudon', 'Magasin-entrepôt Victor-Hudon', 'Le propriétaire constructeur de ce magasin-entrepôt est l’homme d’affaires montréalais bien connu, Victor Hudon. C’est en 1861 que le bâtiment est construit à l’endroit où se trouvait auparavant un bâtiment qui était fort probablement une maison-magasin. Lors de la première occupation, le magasin-entrepôt accueille deux occupants. Hudon & Gélinas, marchands de dry goods (tissus, articles de mercerie et peut-être d''autres produits), occupent un espace locatif dont l’adresse est sur la rue St-Paul. Ils demeurent dans le bâtiment pendant neuf ans, de 1862 à 1871.', 'historic', 45.5071, -73.5524, 50, null::extensions.geography, '138 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-65-6982-00', false, null, true),
  ('maison-magasin-jean-baptiste-castonguay', 'Maison-magasin Jean-Baptiste-Castonguay', 'Jean-Baptiste Castonguay fait construire cette maison-magasin en 1828. Castonguay est propriétaire de l’emplacement, avec un bâtiment en bois, par la donation que lui en a fait sa mère en 1827. Une annonce publiée dans La Minerve en janvier 1829, permet à la fois d’apprendre la construction récente de l’immeuble à louer et de connaître ses fonctions d’origine, commerciale et résidentielle, à l’instar des autres maisons-magasins : « deux magasins spacieux avantageusement situés sur le nouveau marché, dans cette nouvelle maison de pierre à deux étages [n’incluant probablement pas le…', 'historic', 45.5076, -73.5533, 50, null::extensions.geography, '432-436 place Jacques-Cartier', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-66-0237-00', false, null, true),
  ('entrepot-frigorifique-cherrier', 'Entrepôt frigorifique Cherrier', 'L''entrepôt frigorifique Cherrier est érigé en deux étapes. La section la plus ancienne est construite le long de la rue Saint-Amable entre 1896 et 1899 sur la propriété de Philomène Charlotte et Marie Jophte Cherrier. Les architectes Cox et Amos intègrent dans la nouvelle construction un des trois bâtiments qui s''y trouvent (vestige Côme Séraphin Cherrier). L''entrepôt terminé, il est aussitôt loué à l''épicier Charles Langlois qui entreprend divers travaux à ses frais, dont l''installation d''un système de réfrigération.', 'historic', 45.5073, -73.5533, 50, null::extensions.geography, '419-423 rue Saint-Vincent', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-66-0401-01', false, null, true),
  ('maison-du-cabinet-de-come-seraphin-cherrier', 'Maison du Cabinet-de-Côme-Séraphin-Cherrier', 'Ce vestige est constitué des murs de façade de l''édifice où logeait le cabinet de l''avocat montréalais Côme Séraphin Cherrier, patriote, propriétaire foncier et cousin de Denis Benjamin Viger, seigneur de l''île Bizard. Cette ancienne maison construite en 1818 possède à l''origine deux étages et demi. Après la mort de Cherrier en 1885, l''édifice est occupé pendant environ 10 ans avant d''être partiellement démoli et intégré à un entrepôt de trois étages. Pour plus de renseignements, veuillez consulter la fiche de l''entrepôt Cherrier dans le présent ensemble.', 'historic', 45.5072, -73.5533, 50, null::extensions.geography, '419-423 rue Saint-Vincent', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-66-0401-02', false, null, true),
  ('magasin-entrepot-thomas-wilson', 'Magasin-entrepôt Thomas-Wilson', 'En 1861, le quincaillier montréalais Thomas Wilson fait construire ce magasin-entrepôt à la forme géométrique particulière. Son emplacement était auparavant occupé par des bâtiments, qui ont été démolis, dont la fonction principale était commerciale, mais dans lesquels il y avait également de l’habitation. Le premier occupant du bâtiment est Thomas Wilson & Co. La compagnie du propriétaire constructeur occupera les lieux pendant trente-deux ans, de 1862 à 1894. Elle est spécialisée dans le commerce, en gros et au détail, de quincaillerie. Par la suite, William Wilson & Co.', 'historic', 45.5074, -73.5523, 50, null::extensions.geography, '158 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-66-7604-01', false, null, true),
  ('magasin-entrepot-thomas-tiffin', 'Magasin-entrepôt Thomas-Tiffin', 'En 1854, Thomas Tiffin acquiert un terrain sur lequel se trouve un bâtiment commercial dans lesquel il y a aussi de l''habitation, au début des années 1850. Thomas Tiffin rénove ce bâtiment en 1855, mais ce n’est visiblement pas suffisant puisqu’il fait construire le magasin-entrepôt actuel en 1857. L’architecte de ce bâtiment est fort probablement William Footner. Tiffin & Co., épiciers, est le premier occupant du magasin-entrepôt. L’entreprise s’y installe dès 1858 et y demeure jusqu’en 1886, soit vingt-huit ans. Au départ, Tiffin & Co.', 'historic', 45.5078, -73.5521, 50, null::extensions.geography, '250 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-66-9451-00', false, null, true),
  ('immeuble-legault-et-masse', 'Immeuble Legault et Masse', 'Ce bâtiment, dont la structure date probablement d''avant 1815, est occupé par une auberge dans les années 1850 et 1860, puis transformé en maison unifamiliale. Napoléon Lefebvre s''en porte acquéreur en juin 1875 à la suite d''un jugement de la cour ordonnant la vente des biens de la succession Alfred Turgeon. Redevenu une auberge vers 1880, le bâtiment est rénové durant l''été 1892, transformé en salle à manger et loué à Auguste Saint-Germain. La facture architecturale de la façade est alors profondément altérée : le toit en pente est relevé et une fausse mansarde est ajoutée.', 'historic', 45.5089, -73.5524, 50, null::extensions.geography, '411 rue Saint-Claude', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-67-7380-02', false, null, true),
  ('magasin-entrepot-donohue', 'Magasin-entrepôt Donohue', 'En 1875, la succession de Timothy Donohue décide de faire construire ce magasin-entrepôt sur un terrain ayant appartenu à Timothy Donohue de 1862 jusqu’à sa mort, en 1873. La succession fait démolir l’ancienne maison en pierre, au toit en pente, mais conserve certaines sections du bâtiment qui sont réutilisables, comme la cave et une petite partie des murs du côté de la rue Saint-Claude. L’architecte Ovide Mailloux a dessiné les plans du magasin-entrepôt. À l’origine, le bâtiment est divisé en trois magasins distincts.', 'historic', 45.5092, -73.553, 50, null::extensions.geography, '300-304 rue Notre-Dame Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-68-2704-01', false, null, true),
  ('maison-william-maitland', 'Maison William-Maitland', 'William Maitland, un des plus importants négociants de la ville, faisait partie d''un groupe restreint de personnes qui, à la fin du XVIIIe siècle, avaient les moyens et le désir de garder à distance leur résidence et leur lieu d''affaires. En 1796, Maitland, avant même d''avoir son titre de propriété, avait engagé le maître maçon François-Xavier Daveluy dit Larose pour la construction d''une maison sur un grand terrain situé sur la rue Notre-Dame, l''artère la plus recherchée à l''époque pour les résidences bourgeoises.', 'historic', 45.5093, -73.5528, 50, null::extensions.geography, '320 rue Notre-Dame Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-68-4420-01', false, null, true),
  ('magasin-entrepot-george-etienne-cartier-i', 'Magasin-entrepôt George-Étienne-Cartier I', 'C’est en 1864 qu’est construit ce magasin-entrepôt, sur un lot vacant depuis plusieurs années. Son propriétaire constructeur n’est nul autre que George-Étienne Cartier, qui travaille alors activement au projet de confédération canadienne. Le bâtiment comprenant deux espaces locatifs, est construit selon « les règles de l’art » et les spécifications de Cartier, comme le stipule le marché de construction. L''architecte du bâtiment est inconnu. Cartier et ses descendants conservent la propriété de l’immeuble jusqu’en 1952.', 'historic', 45.5097, -73.5526, 50, null::extensions.geography, '340-348 rue Notre-Dame Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-68-5769-00', false, null, true),
  ('magasin-entrepot-george-etienne-cartier-ii', 'Magasin-entrepôt George-Étienne Cartier II', 'Ce magasin-entrepôt est construit par l’honorable George-Étienne Cartier en 1864 sur un lot vacant dont il était propriétaire depuis quelques années. La famille Cartier conservera la propriété de l’immeuble jusqu’en 1952. L''immeuble appartient à un ensemble formé de deux bâtiments comptant chacun deux magasins. Il accueille ses premiers occupants en 1865 et en 1866. Il s’agit du prêteur sur gage Jacob L. Moss, présent de 1865 à 1870, et du sellier Robert Morris, dont le séjour ne dure qu’une seule année.', 'historic', 45.5098, -73.5525, 50, null::extensions.geography, '350-350A rue Notre-Dame Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-68-6280-00', false, null, true),
  ('maison-magasin-george-etienne-cartier', 'Maison-magasin George-Étienne Cartier', 'Cette maison-magasin est construite en 1844-1845 à la demande de Georges-Étienne Cartier. Propriétaire de l’emplacement avec une maison au coin sud-ouest des rues Notre-Dame et Bonsecours depuis le printemps 1842, Cartier fait appel à l’entrepreneur Olivier Fréchette pour lui construire la maison-magasin. Comme d’autres bâtiments similaires, celle-ci est conçue pour être utilisée à des fins résidentielles et commerciales.', 'historic', 45.51, -73.5524, 50, null::extensions.geography, '356-362 rue Notre-Dame Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-68-6993-00', false, null, true),
  ('maison-papineau', 'Maison Papineau', 'En 1779, le colonel John Campbell, commissaire responsable des affaires amérindiennes dans le district de Montréal, achetait ce terrain sur lequel l''ancien propriétaire, Joseph Papineau dit Montigny, avait fait construire une maison de bois avec une rallonge en pierre. Campbell attendit l''année 1785 avant d''engager le maçon Jean-Baptiste Cérat dit Coquillard pour y faire bâtir une nouvelle maison de pierre à deux étages en intégrant, semble-t-il, la rallonge.', 'historic', 45.509926, -73.5522, 50, null::extensions.geography, '440 rue de Bonsecours', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-68-7978-01', false, null, true),
  ('maison-jane-tate-ii', 'Maison Jane-Tate II', 'Située à côté de la Maison Papineau, cette maison-magasin appartient à un ensemble formé de deux bâtiments construits en 1863-1864 pour Mlle Jane Tate, sur des terrains qui lui appartiennent depuis 1856. Le bâtiment de pierre de trois étages compte deux unités commerciales au rez-de-chaussée et des logements aux étages. Il est construit sur un terrain vacant adjacent à la résidence de Mlle Tate, démoli pour permettre la construction du bâtiment voisin. Jane Tate s’installe dans un logement des étages supérieurs du 430 Bonsecours dès sa construction et y réside jusqu’à sa mort en 1874.', 'historic', 45.5099, -73.5521, 50, null::extensions.geography, '430 rue de Bonsecours', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-68-9278-01', false, null, true),
  ('immeuble-de-lassociation-des-debardeurs-du-port-de-montreal', 'Immeuble de l''Association des débardeurs du port de Montréal', 'En 1923, à la suite d’un incendie qui ravage deux bâtiments, l’Association des débardeurs syndiqués du port de Montréal acquiert une propriété à l’angle des rues Champ-de-Mars et Bonsecours. Elle y fait construire, en 1924, un immeuble sous la supervision de l’architecte Emmanuel-Arthur Doucet. L’association syndicale s’installe aux deux derniers étages, tandis que les étages inférieurs sont occupés par des grossistes. Au milieu des années 1940, l’immeuble est transformé en manufacture de chaussures par la Bluestone & Co.', 'historic', 45.5106, -73.553, 50, null::extensions.geography, '525-539 rue de Bonsecours', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-69-2462-00', false, null, true),
  ('maison-polyxene-beaudry', 'Maison Polyxène-Beaudry', 'Polyxène Beaudry fait construire cette maison en 1892. La maison compte à l’origine six logements dont la plupart sont occupés par des ménages relativement aisés. La maison a fait l''objet de travaux de restauration en 1986. Elle a été transformée depuis en copropriétés.', 'historic', 45.5109, -73.5529, 50, null::extensions.geography, '422-430 rue du Champ-de-Mars', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-69-3896-00', false, null, true),
  ('magasin-entrepot-alexandre-maurice-delisle', 'Magasin-entrepôt Alexandre-Maurice-Delisle', 'En 1862, l’homme d’affaires montréalais Alexandre-Maurice Delisle acquiert, de la succession de Jacques Viger, un très grand terrain situé au coin sud-est des rues Notre-Dame et Bonsecours. Delisle y fera éventuellement construire un ensemble de quatre bâtiments, dont ce magasin-entrepôt qui comprend deux magasins. Les autres bâtiments de cet ensemble disparaissent dans les années 1970. Après la mort de Delisle, en 1880, sa succession conserve la propriété de cet immeuble jusqu’en 1910. C’est en 1864 que les premiers occupants s’installent sur les lieux.', 'historic', 45.5102, -73.5522, 50, null::extensions.geography, '400-406 rue Notre-Dame Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-69-8820-00', false, null, true),
  ('immeuble-john-elliott', 'Immeuble John-Elliott', 'En 1844, la Corporation de la Ville de Montréal a élaboré un grand projet d''établir des halles du marché afin de mieux répondre aux besoins de la population et à l''image qu''elle se faisait de sa ville. Bien que le Marché Bonsecours ait été la pierre angulaire de cette démarche, le conseil municipal prévoyait un autre immeuble qui servirait à la fois de marché aux poissons et de boutiques.', 'historic', 45.5081, -73.552, 50, null::extensions.geography, '266-272 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-76-0685-00', false, null, true),
  ('hotel-la-prairie', 'Hôtel La Prairie', 'Construite en 1881 par la succession de Jean-Baptiste Beaudry, cet immeuble comprend à l''origine deux auberges, des commerces au rez-de-chaussée et des logements. Entre 1883 et 1909, l’hôtel de Laprairie occupe la majeure partie du bâtiment.', 'historic', 45.5094, -73.5518, 50, null::extensions.geography, '355-363 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-78-0037-01', false, null, true),
  ('auberge-bonsecours-du-vieux-montreal', 'Auberge Bonsecours du Vieux-Montréal', 'Cet ancien bâtiment de service a été transformé en auberge en 2001.', 'historic', 45.5095, -73.5523, 50, null::extensions.geography, null, 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-78-0037-03', false, null, true),
  ('maison-jane-tate-i', 'Maison Jane-Tate I', 'Cette maison-magasin appartient à un ensemble formé de deux bâtiments contigus construits en 1863-1864 pour Mlle Jane Tate, sur des terrains qui lui appartiennent depuis 1856. Le bâtiment de pierre de trois étages compte deux unités commerciales au rez-de-chaussée et des logements aux étages. Il remplace la résidence de Mlle Tate, une petit maison en brique de deux étages; après la construction du nouvel ensemble, cette dernière s’installe dans la partie supérieure de la maison-magasin voisine, au 430 Bonsecours, où elle résidera jusqu’à son décès en 1874.', 'historic', 45.5098, -73.552, 50, null::extensions.geography, '416-420 rue de Bonsecours', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-78-0776-00', false, null, true),
  ('hotel-federal', 'Hôtel Fédéral', 'Cet immeuble est construit en 1881 par la succession Saveuse de Beaujeu. Pour faire place au bâtiment, deux maisons de pierre sont démolies, dont l’auberge de la famille Gadoua, en activité depuis le milieu des années 1860. Cette même famille loue en bonne partie le nouveau bâtiment et y gère une auberge jusqu’en 1887. Un aubergiste du nom d''Antoine Décary ouvre alors l’hôtel Fédéral, lequel demeure en fonction jusqu’en 1905.', 'historic', 45.5096, -73.5521, 50, null::extensions.geography, '367-375 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-78-0951-00', false, null, true),
  ('maison-william-walker-ii', 'Maison William-Walker II', 'William Walker fait construire cet immeuble en 1833 sur un emplacement qu’il a acquis l’automne de l’année précédente. Le bâtiment est probablement à l’origine une maison convertie ultérieurement en maison-magasin, à l’instar de l’immeuble voisin aussi bâti par Walker, à moins qu’il n’ait été dès le départ une maison-magasin conçue pour servir à des fins commerciales et résidentielles. En 1849 du moins, alors que Pierre Jodoin en est le propriétaire depuis trois ans, le bâtiment est le lieu de résidence d’un commissaire-priseur et d’un aubergiste qui y tient aussi son commerce.', 'historic', 45.5097, -73.5517, 50, null::extensions.geography, '383-387 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-78-2763-00', false, null, true),
  ('maison-william-walker-i', 'Maison William-Walker I', 'L’avocat William Walker fait bâtir cette maison en 1831-1832. À l’été 1831, il acquiert l’emplacement vacant au coin des rues Saint-Paul et Bonsecours. Il engage à l’automne le maçon David Scobie pour construire le bâtiment fort probablement en conformité avec les plans de l’architecte John Try. En décembre 1833, Walker vend la maison à Janet Mary Katherine Bruyères, épouse du juge Michael O’Sullivan. Le couple y établit sa résidence. L’avocat Charles-Séraphin Rodier en devient le propriétaire en 1845.', 'historic', 45.5098, -73.5516, 50, null::extensions.geography, '393-395 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-78-3176-00', false, null, true),
  ('chapelle-notre-dame-de-bon-secours', 'Chapelle Notre-Dame-de-Bon-Secours', 'Lieu de pèlerinage et de dévotion depuis le XVIIe siècle, l''actuelle chapelle Notre-Dame-de-Bon-Secours est la seconde construite sur le site. La première, une modeste chapelle érigée à la demande de Marguerite Bourgeoys dans les années 1670, fut très endommagée par un incendie en 1754. Les vestiges de cette chapelle constituent d''ailleurs un des plus importants sites archéologiques du Vieux-Montréal. La fabrique de la paroisse Notre-Dame, propriétaire du terrain, ne put entreprendre la reconstruction de la chapelle qu''en 1771.', 'religious', 45.5098, -73.5511, 60, null::extensions.geography, '400 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-78-7984-01', false, null, true),
  ('maison-louis-viger', 'Maison Louis-Viger', 'Louis Viger fait construire cette maison vers 1765. Viger achète en 1764 cet emplacement situé sur la rue Bonsecours sur lequel est construit un hangar en bois. Dès 1770 une nouvelle maison en pierre est bâtie sur le lot. Quoique le nombre d''étages de ce bâtiment demeure inconnu, il est fort probable qu''il s''agisse de la même maison, en pierre de deux étages, qui se trouve sur l''emplacement en 1808, alors que Viger et son épouse Marie-Agnès Papineau lèguent à leur fils Louis-Michel la résidence familiale.', 'historic', 45.5101, -73.5517, 50, null::extensions.geography, '415 rue de Bonsecours', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-79-2720-00', false, null, true),
  ('maison-du-calvet', 'Maison Du Calvet', 'Avec ses murs massifs de maçonnerie, ses murs coupe-feu incorporant des cheminées, son toit à deux versants et ses esses de fer attachées au pignon, la maison Du Calvet constitue le modèle typique d''une maison bourgeoise du XVIIIe siècle. La date de construction de cette maison a toutefois soulevé la controverse parmi les historiens. À cause de la présence sur ce lot, en 1770, d''une maison en pierre en mauvais état qui n''avait qu''un étage divisé en deux appartements, on peut écarter toute hypothèse qui propose une date antérieure.', 'historic', 45.51, -73.5516, 50, null::extensions.geography, '401 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-79-3803-00', false, null, true),
  ('immeuble-pierre-du-calvet', 'Immeuble Pierre-Du Calvet', 'Le marchand huguenot Pierre Du Calvet fait construire cet entrepôt en 1768, sur un emplacement appartenant à sa belle-famille. Du Calvet qui devait jouir de l''entrepôt sans payer de loyer pour quatre ans, achète l''emplacement au printemps de 1770 comprenant une vieille maison au coin des rues Bonsecours et Saint-Paul qu''il reconstruira et le nouveau bâtiment. Dès le début des années 1780, il semble que Du Calvet rénove l''entrepôt qu''il transforme en auberge. Les biens de Du Calvet, décédé en mer, sont saisis par le shérif en 1787.', 'historic', 45.5102, -73.5515, 50, null::extensions.geography, null, 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-79-4017-00', false, null, true),
  ('maison-magasin-samuel-davies-ii', 'Maison-magasin Samuel-Davies II', 'Le marchand de fourrures Samuel Davies fait construire cette maison-magasin en 1833. Davies acquiert au printemps 1832 un emplacement avec une maison en pierre de trois étages (l’actuel 411-417 rue Saint-Paul Est) et ses dépendances. En plus de rénover le bâtiment existant, Davies engage le maître maçon Thomas Hodgson et le charpentier James Ilsley pour construire une nouvelle maison-magasin. Celle-ci est probablement conçue, comme d’autres bâtiments semblables, pour servir à des fins résidentielles et commerciales.', 'historic', 45.5103, -73.5515, 50, null::extensions.geography, '421-425 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-79-4229-00', false, null, true),
  ('maison-eustache-prevost', 'Maison Eustache-Prévost', 'Construite par le tonnelier Eustache Prévost vers la toute fin du régime français, cette maison constitue le seul exemple d''une habitation artisanale qui subsiste encore dans les confins de la ville fortifiée. Prévost avait acquis ce terrain sur lequel était érigée une maison de bois en 1750, sans doute à cause de la proximité du site de la Canoterie royale où on préparait les expéditions militaires.', 'historic', 45.5106, -73.5514, 50, null::extensions.geography, '445 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-79-4472-00', false, null, true),
  ('hospice-saint-antoine-de-bonsecours', 'Hospice Saint-Antoine-de-Bonsecours', 'Cet ensemble de maisons est construit en 1895 par le Séminaire de Saint-Sulpice. Au départ, les maisons logent principalement des familles dont les chefs de ménage exercent le métier de marchand. Vers 1905, une partie des maisons est transformée en hospice (hospice Saint-Antoine-de-Bonsecours) que l’on confie aux bons soins des soeurs Grises. L’autre partie est convertie en école (école Saint-Antoine). En 1906, on agrandit l’immeuble vers l’ouest ; l’école est alors transférée dans cette nouvelle section.', 'historic', 45.5102, -73.5511, 50, null::extensions.geography, '404-420 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-79-7518-01', false, null, true),
  ('silo-a-grain-no-2', 'Silo à grain no 2', 'En 1909, le silo no 1 et l''élévateur B du Grand Tronc (silo no 5) ne suffisent plus et les autorités portuaires décident de construire un nouveau silo. Les commissaires du Havre choisissent un emplacement situé tout juste derrière le marché Bonsecours. Ils engagent la firme de J. S. Metcalf Co. de Chicago, déjà responsable des silos no 1 et de l''élévateur B. Les travaux débutent en 1910 et se terminent en 1912.', 'historic', 45.5085, -73.5506, 50, null::extensions.geography, 'None promenade du Vieux-Port', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-85-7973-09', false, null, true),
  ('hangar-numero-16', 'Hangar numéro 16', 'En 1909, les commissaires du Havre décident d''entamer la construction du nouveau quai Victoria. Durant les travaux, on prend bien soin de creuser les fondations d''un entrepôt, le hangar no 16. Fin 1911, on commence à ériger une structure d''acier de deux étages. Bien que le hangar soit en opération dès le mois d''août 1912, le premier étage n''est complété qu''au début de l''année 1913.', 'historic', 45.5094, -73.5489, 50, null::extensions.geography, 'None quai de l''Horloge', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0040-85-7973-11', false, null, true),
  ('immeuble-alfred-dolbec', 'Immeuble Alfred-Dolbec', 'Ce bâtiment est construit en 1895 sur un terrain acquis la même année par l''avocat Alfred Dolbec. S''y trouvent un vieux duplex de deux étages et une dépendance, érigés en 1853 par Joseph Robillard. La nouvelle maison de trois étages – rez-de-chaussée commercial et logements aux étages – couvre dorénavant tout le lot. Un magasin de produits de beauté occupe la partie gauche du rez-de-chaussée; leurs propriétaires logent à l''étage supérieur. L''autre commerce appartient à Joseph N. Chagnon (il demeure dans son arrière boutique).', 'historic', 45.5114, -73.5539, 50, null::extensions.geography, '434-444 rue Saint-Antoine Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0041-50-5852-00', false, null, true),
  ('maison-brossard-gauvin', 'Maison Brossard-Gauvin', 'Presque unique en son genre, cette maison est un des deux exemples qui restent de maison en bois que des artisans, des jardiniers ou d''autres ouvriers faisaient construire dans les faubourgs qui entouraient la ville fortifiée. Bien que située dans les confins du Vieux-Montréal actuel, au XVIIIe siècle le site de la maison faisait partie du tout petit faubourg Saint-Louis qui se trouvait hors des murailles dans l''ombre du coteau de la citadelle.', 'historic', 45.5113, -73.5536, 50, null::extensions.geography, '433-435 rue Saint-Louis', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0041-50-7645-00', false, null, true),
  ('refuge-meurling', 'Refuge Meurling', 'En 1912, la ville de Montréal reçoit un legs de Gustave Meurling qui ne doit être utilisé qu''à des fins charitables. La Ville décide alors de construire le refuge Meurling, répondant ainsi aux nombreux réformateurs sociaux qui déplorent le manque d''asile public pour les indigents à Montréal. Le site choisi comprend un ensemble d''immeubles résidentiels répartis sur les rues du Champ-de-Mars et Saint-Louis. Les bâtiments de la rue Saint-Louis, majoritairement construits en bois, logent, au début des années 1910, des journaliers et leurs familles.', 'historic', 45.5111, -73.5533, 50, null::extensions.geography, '435 rue du Champ-de-Mars', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0041-60-0517-00', false, null, true),
  ('maison-joseph-brossard', 'Maison Joseph-Brossard', 'Le menuisier Joseph Brossard fait construire cette maison en 1828. Joseph Brossard père et Marie-Josephte Mathieu font donation à leur fils Joseph et à sa future épouse Marie-Josephte Dupéré, en 1826, de cet emplacement sans bâtiments situé au faubourg Saint-Louis. Brossard fils engage deux ans plus tard Charles-Simon Delorme pour lui bâtir une maison en bois, recouverte de planches en façade et ultérieurement de crépit, avec fondation et cheminées en pierre, rare exemple encore debout des maisons qui peuplaient les faubourgs montréalais au début du XIXe siècle.', 'historic', 45.5114, -73.5532, 50, null::extensions.geography, '454 rue Saint-Louis', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0041-60-1352-00', false, null, true),
  ('maisons-adolphe-faust', 'Maisons Adolphe-Faust', 'Cet immeuble comprend quatre unités résidentielles. Il est construit en deux étapes par le médecin Alphonse Faust (Fausse). Les deux maisons sis à l’est sont construites en 1886. En 1890, Faust acquiert la propriété voisine à l’ouest. Il y fait bâtir en 1891 deux maisons identiques à celles de 1886.', 'historic', 45.5115, -73.553, 50, null::extensions.geography, '464-494 rue Saint-Louis', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0041-60-2468-00', false, null, true),
  ('hotel-le-relais', 'Hôtel Le Relais', 'Construit en 1911, l''hôtel Le Relais est localisé sur un emplacement acquis par Joseph Moreau en 1898. Le site abritait alors une auberge donnant sur la rue Saint-Louis. La construction de la nouvelle aile de la gare Viger incite sans doute Moreau à procéder à l''érection d''un nouvel hôtel faisant front sur la rue Berri. L''hôtel de quatre étage est complété en 1911. L''immeuble terminé, Joseph Moreau cède la propriété à deux de ses enfants, Maria et Joseph, qui le louent aussitôt à l''hôtelier Napoléon Geoffroy, président de la compagnie Le Relais.', 'historic', 45.5117, -73.5529, 50, null::extensions.geography, '756-764 rue Berri', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0041-60-3284-00', false, null, true),
  ('gare-hotel-viger', 'Gare-hôtel Viger', 'La gare-hôtel Viger est construite entre 1896 et 1898 par le Canadien Pacifique d’après les plans de Bruce Price, l’architecte du château Frontenac à Québec (1892-1893). Pour construire cet imposant édifice, la Ville de Montréal et le Canadien Pacifique signent une entente. Le Canadien Pacifique cède ainsi trois importantes propriétés à la Ville de Montréal, tandis que celle-ci exproprie 35 lots entre 1893 et 1895 pour la construction de la gare-hôtel. Des dizaines de bâtiments sont détruits pour le projet, dont de nombreuses maisons. Le square Dalhousie est également rasé.', 'historic', 45.5125, -73.5532, 50, null::extensions.geography, '700 rue Saint-Antoine Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0041-61-1570-01', false, null, true),
  ('gare-berri', 'Gare Berri', 'Cette gare est construite en 1911-1912 par le Canadien Pacifique, soit une dizaine d’années après l’ouverture de la gare-hôtel Viger (1898) dont elle est le prolongement. Le nouveau bâtiment sert à la fois de gare et d''hôtel – les chambres étant situées à l''étage supérieur –, tandis que la gare-hôtel Viger assume désormais une vocation strictement hôtelière.', 'historic', 45.512, -73.5525, 50, null::extensions.geography, '755-775 rue Berri', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0041-61-1570-02', false, null, true),
  ('eglise-orthodoxe-grecque-syrienne-saint-nicolas', 'Église orthodoxe grecque syrienne Saint-Nicolas', 'L’église orthodoxe grecque syrienne Saint-Nicolas est construite en 1910-1912 d’après les plans de l’architecte Charles Bernier. La congrégation syrienne – The Syrian Greek Orthodox Church of Saint-Nicholas of Canada – achète d’abord la propriété en février 1909. On y trouve alors une pension de famille (boarding house) de trois étages en pierre, laquelle est démolie lorsqu’on débute les travaux durant l’été 1910. L’inauguration de l’église, d’abord prévue au début du mois de décembre 1910, est considérablement retardée puisque l’entrepreneur fait faillite.', 'religious', 45.511, -73.5517, 60, null::extensions.geography, '452 rue Notre-Dame Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0041-70-2608-00', false, null, true),
  ('maison-george-etienne-cartier-i', 'Maison George-Étienne-Cartier I', 'L''avocat Arthur Ross fait construire sur un terrain vacant, peut-être par l''entrepreneur Richard Robinson, deux maisons jumelées partageant un passage mitoyen et une porte cochère entre 1836 et 1838. Ross vend la maison à l''ouest (la maison ouest) en décembre 1838 à l''avocat John Bleakley qui y installe sa demeure. La maison devient la propriété de l''avocat et politicien George-Étienne Cartier en 1862.', 'historic', 45.5111, -73.5517, 50, null::extensions.geography, '456-458 rue Notre-Dame Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0041-70-3025-01', false, null, true),
  ('maison-george-etienne-cartier-ii', 'Maison George-Étienne-Cartier II', 'L''avocat Arthur Ross fait construire sur un terrain vacant, peut-être par l''entrepreneur Richard Robinson, deux maisons jumelées partageant un passage mitoyen et une porte cochère entre 1836 et 1838. Ross fait donation de la maison à l''est (appelée maison est) à sa mère en 1839. La maison conserve sa vocation résidentielle jusqu''en 1871. Dans l''intervalle, en 1848, elle devient la propriété de l''avocat et politicien George-Étienne Cartier. Ce dernier en fait sa résidence familiale de 1848 à 1855. La famille Cartier quitte la ville en 1855 et loue la maison à un avocat.', 'historic', 45.5112, -73.5517, 50, null::extensions.geography, '458-460 rue Notre-Dame Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0041-70-3025-02', false, null, true),
  ('maisons-philip-shorts', 'Maisons Philip-Shorts', 'La façade d''origine comprenait deux portes d''entrée distinctes et une porte-cochère. L''apparence actuelle du bâtiment lui a été donnée entre 1927 et 1947.', 'historic', 45.5109, -73.5513, 50, null::extensions.geography, '461 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0041-70-5003-01', false, null, true),
  ('refuge-notre-dame-de-la-merci', 'Refuge Notre-Dame-de-la-Merci', 'En 1930, le journaliste Olivar Asselin, alors secrétaire du Refuge de Notre-Dame-de-la-Merci, invite les bienfaiteurs à l''assemblée générale annuelle du Refuge. Cette œuvre charitable qui s''occupe d''hospitalisation et d''hébergement de la vieillesse indigente a été mise sur pied en 1915 par Achille David, « un communiste chrétien » selon Asselin, qui réussissait tant bien que mal à loger les malades particulièrement démunis. À cause du manque d''argent chronique, ceux-ci étaient expulsés régulièrement de ces locaux de fortune.', 'historic', 45.5109, -73.5514, 50, null::extensions.geography, '459 rue Saint-Paul Est', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0041-70-5003-02', false, null, true),
  ('elevateur-b', 'Élévateur B', 'En 1902, les commissaires du havre confient à la compagnie du Grand Tronc la construction de l’élévateur B et lui cèdent des terrains situés sur la Pointe-du-Moulin. La firme d’ingénierie de Chicago John S. Metcalf Co. est choisie pour ce projet. En 1904, les travaux d’excavation de l’élévateur débutent. Metcalf développe un projet composé d’un système de silos carrés formés de plaques d’acier. Le 28 avril 1906, on inaugure officiellement le nouveau silo qui a une capacité de 1 million de boisseaux. Le nouvel édifice innove en prenant livraison aussi bien des wagons que des barges.', 'historic', 45.4971, -73.5501, 50, null::extensions.geography, 'None quai de la Pointe-du-Moulin', 'Ville-Marie', 'montreal-edifices-patrimoniaux', 'https://donnees.montreal.ca/dataset/les-edifices-patrimoniaux-de-montreal', 'CC-BY-4.0', '0139-13-1892-03', false, null, true),
  ('maison-du-meunier', 'Maison du Meunier', null, 'museum', 45.574862, -73.6611018, 50, null::extensions.geography, '10897 Rue du Pont, Montréal H2B 1Z4', 'Ahuntsic-Cartierville', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1', false, null, true),
  ('maison-du-pressoir', 'Maison du Pressoir', null, 'museum', 45.5759697, -73.6595527, 50, null::extensions.geography, '10865 Rue du Pressoir, Montréal H2B 2L1', 'Ahuntsic-Cartierville', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2', false, null, true),
  ('musee-des-soeurs-de-la-providence', 'Musée des Sœurs de la Providence', null, 'museum', 45.5293742, -73.713635, 50, null::extensions.geography, '12055 Rue Grenet, Montréal H4J 2J5', 'Ahuntsic-Cartierville', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '4', false, null, true),
  ('parc-ahuntsic', 'Parc Ahuntsic', 'Aire de jeux inclusiveMunie de balançoires adaptées avec sièges parents-enfants, d’un module de jeu accès universel, d’un tourniquet d''accès universel, de marquage ludique au sol et de glissades de différentes hauteurs, l''aire de jeux du parc Ahuntsic accueille tous les enfants vivant ou non avec une situation de handicap. L’installation de ces aires de jeux répond aux besoins de tous les enfants, soit ceux qui vivent avec un handicap et tous les autres.Réserver le stade de baseball Gary-CarterPour faire une demande : reservation@sodem.net', 'park', 45.5558014, -73.6647101, 234, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.667496,45.555124],[-73.662425,45.553651],[-73.66079,45.556417],[-73.665863,45.557902],[-73.667496,45.555124]]]]}'),4326)),3))::extensions.geography, null, 'Ahuntsic-Cartierville', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '5', false, null, true),
  ('parc-alice-nolin', 'Parc Alice-Nolin', null, 'park', 45.5337067, -73.6701575, 120, null::extensions.geography, null, 'Ahuntsic-Cartierville', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '6', false, null, true),
  ('parc-avila-vidal', 'Parc Avila-Vidal', 'Activités et prêt au parcJouez au tennis de table!Des raquettes et des balles sont mises à votre disposition gratuitement en été dans les paniers/tiroirs de la table de tennis de table de ce parc.Ce prêt est rendu possible grâce à circonflexe, un programme propulsé par Sport et Loisir de l’île de Montréal grâce à la contribution financière du ministère de l’Éducation.', 'park', 45.5295105, -73.6956702, 70, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.696328,45.530346],[-73.696887,45.529905],[-73.695017,45.52876],[-73.694508,45.529196],[-73.696328,45.530346]]]]}'),4326)),3))::extensions.geography, null, 'Ahuntsic-Cartierville', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '7', false, null, true),
  ('parc-basile-routhier', 'Parc Basile-Routhier', null, 'park', 45.5578041, -73.6721488, 99, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.672556,45.558642],[-73.67298,45.558058],[-73.673147,45.557543],[-73.670298,45.556733],[-73.669844,45.557134],[-73.671235,45.557574],[-73.67091,45.558166],[-73.672556,45.558642]]]]}'),4326)),3))::extensions.geography, null, 'Ahuntsic-Cartierville', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '8', false, null, true),
  ('parc-beau-bois', 'Parc Beau-Bois', null, 'park', 45.5179329, -73.7329017, 120, null::extensions.geography, null, 'Ahuntsic-Cartierville', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '9', false, null, true),
  ('parc-belmont', 'Parc Belmont', null, 'park', 45.5333557, -73.7255393, 78, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.726433,45.532632],[-73.725694,45.532144],[-73.725566,45.532639],[-73.725248,45.532719],[-73.725158,45.533243],[-73.724799,45.53352],[-73.724986,45.533639],[-73.724789,45.533791],[-73.725372,45.534171],[-73.7258,45.533887],[-73.725864,45.533681],[-73.725944,45.533726],[-73.726231,45.53356],[-73.726433,45.532632]]]]}'),4326)),3))::extensions.geography, null, 'Ahuntsic-Cartierville', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '10', false, null, true),
  ('parc-berthe-louard', 'Parc Berthe-Louard', 'On y trouve une patinoire pour le hockey, une patinoire décorative, un terrain de balle, un terrain de pétanque/bocce, une aire de jeux pour enfants, et bien plus encore.', 'park', 45.5592074, -73.6423117, 65, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.643142,45.558648],[-73.642435,45.558442],[-73.642008,45.55896],[-73.641453,45.559374],[-73.641765,45.559738],[-73.642255,45.56003],[-73.643142,45.558648]]]]}'),4326)),3))::extensions.geography, null, 'Ahuntsic-Cartierville', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '11', false, null, true),
  ('parc-camille', 'Parc Camille', 'Un terrain de tennis, ouvert tous les jours de 7 h à 23 h, est à votre disposition d''avril à octobre.Plus d''information : Terrain de tennis du parc Camille', 'park', 45.5104332, -73.7527534, 53, null::extensions.geography, null, 'Ahuntsic-Cartierville', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '12', false, null, true),
  ('parc-dauteuil', 'Parc d''Auteuil', null, 'park', 45.5488739, -73.6568061, 102, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.656228,45.548003],[-73.655362,45.549527],[-73.656793,45.549967],[-73.658146,45.548958],[-73.657537,45.548775],[-73.657778,45.548471],[-73.656228,45.548003]]]]}'),4326)),3))::extensions.geography, null, 'Ahuntsic-Cartierville', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '13', false, null, true),
  ('parc-de-beausejour', 'Parc de Beauséjour', 'Venez profiter des attraits de la nature ou pratiquer des loisirs en plein air.Merci de respecter la réglementation dans les parcs.Attention : Il est désormais interdit d''utiliser un barbecue dans ce parc.Vous pouvez utiliser les tables à pique-nique du parc pour manger. Toutefois, il est important de ne pas laisser de déchets, en raison de la présence de nombreux animaux.En tout temps, il est interdit de nourrir les animaux.', 'park', 45.5277061, -73.7319785, 175, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.734119,45.527292],[-73.7324,45.526216],[-73.732785,45.525962],[-73.732431,45.525759],[-73.731109,45.526164],[-73.729706,45.527369],[-73.732935,45.529372],[-73.733788,45.528703],[-73.734612,45.5276],[-73.734119,45.527292]]]]}'),4326)),3))::extensions.geography, null, 'Ahuntsic-Cartierville', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '14', false, null, true),
  ('parc-de-bordeaux', 'Parc de Bordeaux', 'On y trouve une patinoire, un terrain de jeu pour les enfants, et bien plus encore.', 'park', 45.5418854, -73.6997977, 46, null::extensions.geography, null, 'Ahuntsic-Cartierville', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '15', false, null, true),
