  ('parc-marcelin-wilson', 'Parc Marcelin-Wilson', 'Activités et prêt au parcTennis de tableDes raquettes et des balles sont mises à votre disposition gratuitement l''été, dans les paniers des tables de tennis de table du parc.Ce prêt est rendu possible grâce à circonflexe, un programme propulsé par Sport et Loisir de l’île de Montréal grâce à la contribution financière du ministère de l’Éducation.Terrain de basketballIl comprend un 2 terrains complets et des 2 demi-terrains.Jardin nourricier - en partenariat avec l''école ÉvangélineEspace éducatif et jardin nourricier en libre-service - venez cueillir les fruits l''été!Potager collectif en bacs…', 'park', 45.5361099, -73.6823035, 305, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.681632,45.53717],[-73.681886,45.537143],[-73.685521,45.538446],[-73.685607,45.538571],[-73.685272,45.539168],[-73.687325,45.539817],[-73.688354,45.538233],[-73.688605,45.537988],[-73.681696,45.534822],[-73.68146,45.534784],[-73.680718,45.53499],[-73.679867,45.536329],[-73.680066,45.536487],[-73.681013,45.53683],[-73.681079,45.536972],[-73.681632,45.53717]]],[[[-73.675567,45.534321],[-73.675941,45.534245],[-73.676163,45.534571],[-73.676585,45.534878],[-73.67638,45.535131],[-73.679419,45.536232],[-73.680345,45.534778],[-73.67998,45.534134],[-73.678634,45.533854],[-73.677605,45.533801],[-73.676313,45.533913],[-73.675504,45.534075],[-73.675567,45.534321]]],[[[-73.691064,45.539109],[-73.688837,45.538075],[-73.688577,45.538285],[-73.687944,45.539295],[-73.690484,45.540223],[-73.691064,45.539109]]]]}'),4326)),3))::extensions.geography, null, 'Ahuntsic-Cartierville', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '32', false, null, true),
