  ('avenue-park-stanley', 'Avenue Park Stanley', 'Lieu de détente et de verdure situé entre la rue Basile-Routhier et l’avenue Durham aux abords de la rivière des Prairies, cette avenue piétonne fait le pont entre les parcs Maurice-Richard et Basile-Routhier. La halte du Parcours Gouin est transformée en une oasis où il fait bon se reposer lors d’une promenade à pied ou à vélo. Toutes les semaines, de multiples activités culturelles et sportives gratuites sont proposées.', 'landmark', 45.5583374, -73.6728671, 60, null::extensions.geography, 'Avenue Park Stanley, Montréal', 'Ahuntsic-Cartierville', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '165', false, null, true),
  ('parc-andre-laurendeau', 'Parc André-Laurendeau', 'Accès aux terrains et coûtsLes terrains seront accessibles aux détenteurs d’une carte magnétique disponible au coût de 5 $ plus des frais d’activation de 5 $. Nous vous encourageons à rapporter votre carte de la saison 2025 afin de ne payer que les frais d’activation. La carte magnétique peut également être utilisée pour le tennis libre.Procédure d’achatCentre communautaire d’Anjou – 7800, boul.', 'park', 45.6045576, -73.5701075, 113, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.569089,45.602765],[-73.568954,45.603478],[-73.569153,45.604637],[-73.571899,45.605822],[-73.572377,45.605275],[-73.570389,45.604452],[-73.570836,45.603862],[-73.570549,45.603739],[-73.5706,45.60368],[-73.569514,45.603213],[-73.569683,45.60302],[-73.569089,45.602765]]]]}'),4326)),3))::extensions.geography, null, 'Anjou', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '168', false, null, true),
