  ('parc-goncourt', 'Parc Goncourt', 'Ses installations comprennent deux aires de jeux pour les moins et plus de 5 ans, des terrains de pétanque, de soccer synthétique et de tennis, des aires de repas, un jardin floral ainsi qu’une butte de glissade durant l''hiver.À l''été, la place des Angevins s''anime chaque semaine avec des sessions de danse en ligne, des spectacles à grand déploiement et des fêtes de quartier.', 'park', 45.6022339, -73.557785, 123, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.556801,45.601672],[-73.556527,45.601846],[-73.556161,45.602254],[-73.555987,45.602848],[-73.558974,45.603359],[-73.559581,45.602256],[-73.557272,45.601248],[-73.556801,45.601672]]]]}'),4326)),3))::extensions.geography, null, 'Anjou', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '184', false, null, true),
  ('parc-lucie-bruneau', 'Parc Lucie-Bruneau', 'Pour vous détendre ou vous entraîner, la piscine Lucie-Bruneau, et sa pataugeoire, vous accueillent pour le bain libre et les activités aquatiques.', 'park', 45.604168, -73.58402, 178, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.581968,45.604311],[-73.581776,45.604531],[-73.584657,45.605762],[-73.584766,45.605744],[-73.586433,45.603832],[-73.578243,45.600287],[-73.578079,45.600475],[-73.581221,45.601854],[-73.581405,45.602387],[-73.581691,45.602449],[-73.58194,45.602163],[-73.583105,45.602662],[-73.582487,45.60337],[-73.582657,45.60328],[-73.582874,45.603296],[-73.583013,45.60341],[-73.583003,45.603563],[-73.582835,45.603672],[-73.582523,45.603681],[-73.58217,45.60408],[-73.582608,45.604267],[-73.582249,45.60468],[-73.581854,45.604511],[-73.581968,45.604311]]]]}'),4326)),3))::extensions.geography, null, 'Anjou', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '185', false, null, true),
  ('parc-roger-rousseau', 'Parc Roger-Rousseau', 'Situé dans le secteur est d''Anjou, il est séparé en deux sections. La première se situe à l''arrière du centre Roger-Rousseau et comporte la plupart des installations et terrains sportifs. Un stationnement public permet d''y accéder. La deuxième partie se situe derrière la nouvelle école secondaire d''Anjou présentement en construction. Elle comprend les terrains de soccer et jouxte la piste cyclable Jean Desprez.', 'park', 45.616602, -73.54992, 267, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.537556,45.614804],[-73.544371,45.61769],[-73.544185,45.617904],[-73.547802,45.619442],[-73.547861,45.619374],[-73.547343,45.61915],[-73.547766,45.618669],[-73.548148,45.618835],[-73.548458,45.618482],[-73.551627,45.619857],[-73.551893,45.619555],[-73.55149,45.619383],[-73.551475,45.619313],[-73.551394,45.619406],[-73.549811,45.618731],[-73.550069,45.618437],[-73.549982,45.618399],[-73.549723,45.618694],[-73.545272,45.616812],[-73.545168,45.616559],[-73.544021,45.616069],[-73.543898,45.61621],[-73.541638,45.615308],[-73.541779,45.615066],[-73.541588,45.615287],[-73.541215,45.615127],[-73.541141,45.614975],[-73.54094,45.614986],[-73.540931,45.6149],[-73.541252,45.61453],[-73.541451,45.614616],[-73.541508,45.614551],[-73.53787,45.613914],[-73.537556,45.614804]]],[[[-73.54996,45.618217],[-73.550066,45.6182],[-73.551713,45.616326],[-73.549642,45.615429],[-73.54826,45.617013],[-73.548455,45.617573],[-73.54996,45.618217]]]]}'),4326)),3))::extensions.geography, null, 'Anjou', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '187', false, null, true),
  ('boise-saint-conrad', 'Boisé Saint-Conrad', 'Petit oasis de paix, le parc comprend des installations qui sauront plaire à toute la famille. Les tout-petits peuvent profiter de modules de jeux modernes, alors que les plus grands disposent d''une table de ping pong qui promet de beaux échanges amicaux!', 'park', 45.6117859, -73.5457153, 40, null::extensions.geography, null, 'Anjou', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '191', false, null, true),
  ('bibliotheque-du-haut-anjou', 'Bibliothèque du Haut-Anjou', 'La bibliothèque du Haut-Anjou dessert tout particulièrement les citoyens du secteur nord d''Anjou.Accès aux collections et à l’aide aux lecteursPlus de 130 000 documents : livres, DVD, CD, magazines, journaux, jeux de société, jeux vidéo;Accès à plus de 4 millions de documents du réseau des bibliothèques de Montréal par le biais du service de réservations.Les bibliothécaires spécialisées en recherche peuvent vous aider à :rechercher et identifier des documents qui répondent à vos besoins;rechercher de l’information sur un sujet précis;utiliser les ressources numériques;compléter une demande de…', 'culture', 45.6011467, -73.5756531, 40, null::extensions.geography, '7070 Rue Jarry Est, Montréal H1J 1G3', 'Anjou', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '195', false, null, true),
  ('bibliotheque-jean-corbeil', 'Bibliothèque Jean-Corbeil', 'Accès aux collections et à l’aide aux lecteursPlus de 130 000 documents : livres, DVD, CD, magazines, journaux, jeux de société, jeux vidéo;Accès à plus de 4 millions de documents du réseau des bibliothèques de Montréal par le biais du service de réservations.Les bibliothécaires spécialisées en recherche peuvent vous aider à :rechercher et identifier des documents qui répondent à vos besoins;rechercher de l''information sur un sujet précis;utiliser les ressources numériques;compléter une demande de prêts entre bibliothèques;utiliser les équipements de la bibliothèque;vous initier aux services…', 'culture', 45.6029411, -73.5584147, 40, null::extensions.geography, '7500 Avenue Goncourt, Montréal H1K 3X9', 'Anjou', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '196', false, null, true),
