  ('bibliotheque-benny', 'Bibliothèque Benny', 'La bibliothèque Benny prête désormais des ensembles gratuits de club de lecture à emporter. Les ensembles sont disponibles en libre-service au 1er étage. Chaque trousse contient de 8 à 10 exemplaires d''un même livre avec des outils pour animer votre club. Pour réserver un ensemble, rendez-vous au comptoir adulte ou appelez-nous.', 'culture', 45.4660941, -73.6310229, 40, null::extensions.geography, '6400 Avenue de Monkland, Montréal H4B 1H3', 'Côte-des-Neiges–Notre-Dame-de-Grâce', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '271', false, null, true),
  ('bibliotheque-de-cote-des-neiges', 'Bibliothèque de Côte-des-Neiges', 'La bibliothèque CDN reprend son envol! Suite aux travaux complétés dans la dernière année, plusieurs changement ont été mis en place : Aménagement de nouveaux comptoirs d’accueilInstallation de nouveaux mobiliersPrésence d’un robot de retour libre-service automatiséAjout de dispositifs d’affichage numériquesAménagement d’une salle d’animation (espace jeunesse)', 'culture', 45.4959793, -73.6221542, 40, null::extensions.geography, '5290 Chemin de la Côte-des-Neiges, Montréal H3T 1Y2', 'Côte-des-Neiges–Notre-Dame-de-Grâce', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '279', false, null, true),
