  ('lancien-couvent-des-soeurs-de-sainte-anne', 'L''ancien couvent des Sœurs de Sainte-Anne', null, 'historic', 45.4796638, -73.8731461, 50, null::extensions.geography, '16115 Boulevard Gouin Ouest, Montréal H9H 1C7', 'L''Île-Bizard–Sainte-Geneviève', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '456', false, null, true),
  ('lancien-noviciat-des-peres-de-sainte-croix-college-gerald-godin', 'L''ancien noviciat des Pères de Sainte-Croix (Collège Gérald-Godin)', null, 'historic', 45.4834072, -73.8693265, 50, null::extensions.geography, '15615 Boulevard Gouin Ouest, Montréal H9H 5K8', 'L''Île-Bizard–Sainte-Geneviève', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '457', false, null, true),
  ('salle-pauline-julien', 'Salle Pauline-Julien', 'Creuset de savoir où convergent élèves, jeunes et adultes, le Cegep Gérald-Godin est une maison d’enseignement supérieur qui propose une formation de qualité. Cet imposant bâtiment abrite en son sein la Salle Pauline-Julien. Cette salle de spectacle fait partie intégrante du paysage de Sainte-Geneviève depuis l’an 2000. Avec sa programmation diversifiée, elle a su se positionner comme un acteur clé de l’offre culturelle dans l’Ouest-de-l’île.', 'culture', 45.483344, -73.8690012, 40, null::extensions.geography, '15615 Boulevard Gouin Ouest, Montréal H9H 5K8', 'L''Île-Bizard–Sainte-Geneviève', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '459', false, null, true),
  ('maison-jean-gabriel-picard', 'Maison Jean-Gabriel-Picard', null, 'historic', 45.438797, -73.7170105, 50, null::extensions.geography, '5430 Boulevard Saint-Joseph, Montréal H8T 1S5', 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '467', false, null, true),
  ('maison-quesnel', 'Maison Quesnel', null, 'historic', 45.4364929, -73.7115936, 50, null::extensions.geography, '5010 Boulevard Saint-Joseph, Montréal H8T 1S1', 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '468', false, null, true),
  ('marche-de-lachine', 'Marché de Lachine', 'Ouvert toute l''année, son bâtiment abrite un commerce gourmet, tandis que son espace extérieur accueille, en saison, une sélection de produits horticoles ainsi que des fruits et légumes frais. Durant le mois de décembre, des sapins de Noël y sont offerts.Le marché de Lachine, fondé en 1845, est le plus vieux marché public de Montréal. Découvrez son histoire!', 'market', 45.4349861, -73.6802216, 60, null::extensions.geography, '1865 Rue Notre Dame Ouest, Montréal H8S 2G2', 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '469', false, null, true),
  ('musee-de-lachine', 'Musée de Lachine', 'Le Musée de Lachine regroupe le site patrimonial Le Ber-Le Moyne, une collection archéologique classée ainsi que des bâtiments du 17e siècle.S’y trouve également la Maison Le Ber-Le Moyne, un des bâtiments le plus ancien de l’île de Montréal construit par Jacques Le Ber et Charles Le Moyne. Aussi, une quinzaine d’œuvres du jardin de sculptures sont installées sur l’immense terrain du Musée faisant une belle place à cette collection unique.', 'museum', 45.4296336, -73.6664937, 50, null::extensions.geography, '1 Chemin du Musée, Montréal H8S 4L9', 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '471', false, null, true),
  ('musee-plein-air-lachine', 'Musée plein air Lachine', null, 'museum', 45.4281006, -73.6758881, 50, null::extensions.geography, null, 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '472', false, null, true),
  ('parc-albert-gariepy', 'Parc Albert-Gariépy', null, 'park', 45.4463921, -73.6711197, 40, null::extensions.geography, null, 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '473', false, null, true),
  ('parc-brewster', 'Parc Brewster', 'Le parc Brewster est situé à quelques dizaines de mètres du lac Saint-Louis.Les travaux de réaménagement du parc, réalisés en 2024-2025, font de ce lieu le premier parc éponge à Lachine. Ce parc résilient joue un rôle clé dans la transition écologique grâce à la gestion améliorée des eaux de pluie.Améliorations :Ajout d''un jardin de pluieAménagement d''espaces de détente et remplacement du mobilier urbainDéminéralisation et ajout d''arbres et de végétauxInstallation de brumisateursMise en valeur d''espaces pour le jeu libreRemplacement de l''éclairageInstallation de modules de jeux universels et…', 'park', 45.4371483, -73.7049404, 49, null::extensions.geography, null, 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '474', false, null, true),
  ('parc-carignan', 'Parc Carignan', 'Vous y trouverez une multitude de terrains sportifs pour vous amuser et des endroits pour vous détendre.Activités estivalesCe parc comprend de nombreuses installations sportives. ludiques ou rafraîchissantes : piscine pour enfants, chalet, terrains de baseball, de soccer, de tennis ainsi que des modules de jeux. Du prêt d''équipement sportif (ballons, Spikeball, etc.) est possible durant les heures d''ouverture de la piscine pour enfants.Activités hivernalesUne patinoire avec bandes et un rond de glace pour le patinage libre sont ouverts selon la météo.', 'park', 45.4435005, -73.7020569, 133, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.703145,45.445011],[-73.702774,45.44214],[-73.701007,45.441953],[-73.700951,45.442082],[-73.701341,45.444795],[-73.701466,45.444866],[-73.703145,45.445011]]]]}'),4326)),3))::extensions.geography, null, 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '475', false, null, true),
