  ('parc-des-saules', 'Parc des Saules', 'Le parc des Saules de Lachine est l''endroit tout indiqué pour faire une pause, pique-niquer ou admirer les paysages du lac Saint-Louis.', 'park', 45.4339066, -73.686554, 56, null::extensions.geography, null, 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '478', false, null, true),
  ('parc-dixie', 'Parc Dixie', 'Vous y trouverez une multitude de terrains sportifs pour vous amuser et des endroits pour vous détendre. Activités estivalesCe parc comprend de nombreuses installations sportives et ludiques : chalet, terrains de soccer et de tennis ainsi que des modules de jeux.Activités hivernalesUne patinoire avec bandes et une petite patinoire de plaisance sont ouvertes selon la météo. Des bancs sont installés le long des patinoires afin de chausser les patins. Des toilettes portatives chauffées se trouvent aussi sur place. En saison, consultez la vignette plus bas pour connaître les conditions de glace.', 'park', 45.4432297, -73.7182541, 81, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.71697,45.443417],[-73.717054,45.443681],[-73.719065,45.444128],[-73.718493,45.4421],[-73.717655,45.4423],[-73.717983,45.443592],[-73.71697,45.443417]]]]}'),4326)),3))::extensions.geography, null, 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '479', false, null, true),
