  ('parc-elm', 'Parc Elm', 'Le parc Elm est également un endroit parfait pour profiter des attraits de la nature.', 'park', 45.447085, -73.6402609, 40, null::extensions.geography, null, 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '481', false, null, true),
  ('parc-du-fort-rolland', 'Parc du Fort-Rolland', 'Le parc du Fort-Rolland est un lieu privilégié pour se détendre, profiter des attraits de la nature ou pratiquer des loisirs en plein air.Situé à l''ouest de la 34e Avenue, il offre de magnifiques points de vue sur le lac Saint-Louis. Des aires de pique-nique y sont aménagées. En hiver, les adeptes de ski de fond peuvent profiter du sentier de ski de fond Grand Sud-Ouest.De magnifiques sculptures contemporaines se dressent fièrement dans ce parc. Poursuivez votre route à vélo ou à pied pour découvrir d''autres oeuvres du jardin de sculptures à Lachine.', 'park', 45.4348891, -73.699295, 96, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.701198,45.435047],[-73.703385,45.43536],[-73.703358,45.435181],[-73.701439,45.434938],[-73.701051,45.434768],[-73.700198,45.434731],[-73.69878,45.434497],[-73.696998,45.433869],[-73.695606,45.433547],[-73.695253,45.433419],[-73.694846,45.433111],[-73.694574,45.433358],[-73.699219,45.435057],[-73.699941,45.435176],[-73.701198,45.435047]]]]}'),4326)),3))::extensions.geography, null, 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '482', false, null, true),
  ('parc-francis-daoust', 'Parc Francis-Daoust', null, 'park', 45.439888, -73.6649702, 40, null::extensions.geography, null, 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '483', false, null, true),
  ('parc-grovehill', 'Parc Grovehill', 'Activités estivalesOn y pratique plusieurs sports notamment sur les terrains de basketball, de planche à roulettes et de volleyball récemment rénovés ainsi que sur les terrains de baseball et de soccer.Du soccer libre permet la pratique de ce sport sans réservation :Les lundis et mercredis, du 29 juin au 21 août De 17 h à 19 h pour les 6-12 ansDe 19 h à 21 h pour les 13-17 ansActivités hivernalesOn y glisse en famille sur la grande butte. En début de saison, de la neige est soufflée afin d’avoir une bonne couche de neige pour bien démarrer la saison de la glissade.', 'park', 45.4406624, -73.6946106, 121, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.695607,45.440374],[-73.695532,45.439778],[-73.693521,45.439822],[-73.693801,45.441828],[-73.696185,45.441852],[-73.69611,45.441253],[-73.69567,45.440873],[-73.695607,45.440374]]]]}'),4326)),3))::extensions.geography, null, 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '484', false, null, true),
