  ('parc-rene-levesque', 'Parc René-Lévesque', 'Selon la saison, promenez-vous à pied, à vélo ou en ski de fond sur les différentes pistes du parc René-Lévesque. À travers ses différents circuits, découvrez 22 sculptures contemporaines monumentales qui font partie d''une collection exceptionnelle à Lachine.Au bout de la presqu’île, venez admirer le coucher de soleil, faire une halte ou simplement vous détendre et laisser votre regard se perdre à l’horizon.L''hiver, il est possible d''y pratiquer le ski de fond sur une piste du sentier La Riveraine, qui traverse plusieurs parcs du sud-ouest de Montréal.', 'park', 45.4285736, -73.681427, 258, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.668728,45.430511],[-73.669034,45.430755],[-73.673311,45.429299],[-73.678933,45.430403],[-73.683426,45.430739],[-73.683409,45.430489],[-73.68325,45.430353],[-73.68301,45.430289],[-73.680854,45.430429],[-73.678787,45.43022],[-73.678288,45.430065],[-73.677655,45.429675],[-73.677529,45.429483],[-73.676762,45.4292],[-73.675016,45.429054],[-73.674033,45.429072],[-73.674186,45.429217],[-73.673182,45.429226],[-73.669464,45.430486],[-73.66896,45.430464],[-73.668804,45.430194],[-73.66918,45.429898],[-73.673082,45.428649],[-73.67422,45.428433],[-73.674844,45.428413],[-73.676531,45.428507],[-73.679951,45.429168],[-73.681443,45.429323],[-73.682673,45.429309],[-73.68598,45.429024],[-73.687048,45.429071],[-73.68809,45.429242],[-73.691688,45.430137],[-73.691735,45.430053],[-73.688352,45.429219],[-73.68812,45.428714],[-73.687816,45.428568],[-73.686964,45.428397],[-73.683331,45.428237],[-73.67926,45.427937],[-73.677258,45.427701],[-73.676115,45.427683],[-73.67518,45.427939],[-73.672741,45.428142],[-73.669795,45.429053],[-73.670021,45.429353],[-73.66895,45.429799],[-73.668458,45.430182],[-73.667929,45.430442],[-73.668568,45.430263],[-73.668728,45.430511]]]]}'),4326)),3))::exten