  ('parc-rosewood', 'Parc Rosewood', 'Ce parc comprend des modules de jeux pour les tout-petits et une petite patinoire l''hiver.', 'park', 45.4497405, -73.6523317, 40, null::extensions.geography, null, 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '497', false, null, true),
