  ('parc-saint-louis', 'Parc Saint-Louis', 'Le parc Saint-Louis est un parc riverain du lac Saint-Louis. On y trouve un quai municipal reconnu pour ses magnifiques points de vue sur le lac et les couchers de soleil. On y trouve un phare et une rampe de mise à l''eau. Ce parc comporte de nombreuses tables de pique-nique ainsi que des bancs propices à l''observation du paysage. Le quai est très populaire auprès des pêcheurs. Le parc comporte également un terrain de volley-ball de plage et il est traversé par une piste cyclable et un sentier piétonnier.', 'park', 45.4329175, -73.6932777, 81, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.691911,45.432861],[-73.691835,45.432864],[-73.69173,45.433534],[-73.692277,45.43348],[-73.693265,45.433076],[-73.694574,45.433358],[-73.694846,45.433111],[-73.694227,45.432482],[-73.695016,45.432276],[-73.69496,45.432171],[-73.69379,45.432476],[-73.693294,45.432413],[-73.693259,45.432575],[-73.692659,45.432492],[-73.692636,45.432595],[-73.69293,45.432641],[-73.692828,45.43283],[-73.691911,45.432861]]]]}'),4326)),3))::extensions.geography, null, 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '499', false, null, true),
  ('parc-stoney-point', 'Parc Stoney Point', 'De magnifiques sculptures contemporaines se dressent fièrement dans ce parc. Poursuivez votre route à vélo ou à pied pour découvrir d''autres oeuvres du jardin de sculptures à Lachine. Un parcours en plein air vous propose d’utiliser le mobilier urbain pour vos entrainements ainsi que les éléments naturels existants.', 'park', 45.4356537, -73.7055817, 140, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.703358,45.435181],[-73.703385,45.43536],[-73.705042,45.435943],[-73.705818,45.436507],[-73.70679,45.43683],[-73.707479,45.436825],[-73.708597,45.43652],[-73.709892,45.436307],[-73.711581,45.436367],[-73.713178,45.436692],[-73.713609,45.437027],[-73.713976,45.437474],[-73.714167,45.437399],[-73.713668,45.436773],[-73.713286,45.436514],[-73.71297,45.436422],[-73.71045,45.436032],[-73.709898,45.436028],[-73.708739,45.436238],[-73.708257,45.436124],[-73.705221,45.435018],[-73.704912,45.435062],[-73.704573,45.434976],[-73.704587,45.435044],[-73.704537,45.434985],[-73.70408,45.435115],[-73.703358,45.435181]]]]}'),4326)),3))::extensions.geography, null, 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '500', false, null, true),
  ('parc-summerlea', 'Parc Summerlea', 'On y trouve un quai à l''angle de la 53e Avenue, accessible gratuitement pour la pratique libre de vos activités sportives sur des embarcations légères non motorisées telles que le kayak et la planche à pagaie.De magnifiques sculptures contemporaines se dressent fièrement dans ce parc. Poursuivez votre route à vélo ou à pied pour découvrir d''autres oeuvres du jardin de sculptures à Lachine.', 'park', 45.4381104, -73.7169113, 119, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.720081,45.438899],[-73.720105,45.438428],[-73.718687,45.438227],[-73.716506,45.437732],[-73.715706,45.43767],[-73.715222,45.437497],[-73.71471,45.437449],[-73.714366,45.437334],[-73.714098,45.437307],[-73.714167,45.437399],[-73.713976,45.437474],[-73.714707,45.438101],[-73.715717,45.438479],[-73.71812,45.438876],[-73.719574,45.438841],[-73.720081,45.438899]]]]}'),4326)),3))::extensions.geography, null, 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '501', false, null, true),
