  ('bibliotheque-de-saint-pierre', 'Bibliothèque de Saint-Pierre', 'Nos prêts et services les plus courantsVous avez accès à plusieurs services : prêt de livres, de bandes dessinées, de disques compacts, de DVD, de jeux vidéos, de magazines, de jeux de société, etc. Des journaux sont disponibles sur place. Nos prêts qui se démarquentPour les abonnés adultesDes prêts-surprisesIndécis ou tout simplement curieux?', 'culture', 45.4456702, -73.6515881, 40, null::extensions.geography, '183 Rue des Érables, Montréal H8R 1B1', 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '516', false, null, true),
  ('bibliotheque-saul-bellow', 'Bibliothèque Saul-Bellow', 'La bibliothèque Saul-Bellow se distingue par son architecture moderne, ses équipements à la fine pointe de la technologie et ses espaces conviviaux et confortables. Elle fait partie des bibliothèques de Lachine avec la bibliothèque de Saint-Pierre.Nos prêts et services les plus courantsVous avez accès à plusieurs services : prêt de livres, de bandes dessinées, de disques compacts, de DVD, de jeux vidéos, de magazines, de jeux de société, etc. Des journaux sont disponibles sur place.', 'culture', 45.4400564, -73.6918307, 40, null::extensions.geography, '3100 Rue Saint-Antoine Ouest, Montréal H8S 4E3', 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '521', false, null, true),
