  ('couvent-mont-sainte-anne', 'Couvent Mont-Sainte-Anne', null, 'religious', 45.4427887, -73.6819193, 60, null::extensions.geography, '1950 Rue Provost, Montréal H8S 1P7', 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '531', false, null, true),
  ('la-maison-du-brasseur', 'La Maison du brasseur', 'La maison du Brasseur est située dans le complexe culturel Guy-Descary qui comprend également L''Entrepôt, maison du la culture de Lachine et la Vieille-Brasserie-Dawes. Les bureaux administratifs de la Direction de la culture, du sport, des loisirs et développement social s''y trouvent ainsi que quelques organismes. On peut notamment s''y procurer des billets pour les spectacles de L''Entrepôt, maison de la culture de Lachine. De par sa large fenestration, les salles de la maison du Brasseur offrent une vue incroyable sur le magnifique lac Saint-Louis.', 'historic', 45.4333763, -73.6899336, 50, null::extensions.geography, '2901 Boulevard Saint-Joseph, Montréal H8S 4B7', 'Lachine', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '534', false, null, true),
