  ('parc-raymond', 'Parc Raymond', 'Le parc propose un espace pour trottinettes et planches à roulettes, des terrains de soccer, des jeux d’eau et une aire pour enfants. En hiver, une patinoire extérieure est aménagée. Vérifiez les conditions de glace avant votre visite.', 'park', 45.4278221, -73.6025238, 109, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.602142,45.428482],[-73.602269,45.428568],[-73.603853,45.428823],[-73.604238,45.42764],[-73.603087,45.427517],[-73.59937,45.427379],[-73.599154,45.427629],[-73.602177,45.428117],[-73.602042,45.428531],[-73.602142,45.428482]]]]}'),4326)),3))::extensions.geography, null, 'LaSalle', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '589', false, null, true),
