  ('au-grand-dam', 'Au grand dam', 'Art public : Jacques Bilodeau et Claude Cormier + Associés, Au grand dam, 2016.', 'public-art', 45.4337548, -73.5864521, 25, null::extensions.geography, null, 'LaSalle', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '629', false, null, true),
  ('theatre-desjardins', 'Théâtre Desjardins', 'Le Théâtre Desjardins contribue activement à la mise en lumière de la culture et des arts de la scène. Reconnu comme le diffuseur majeur du Grand Sud-Ouest de Montréal, l’établissement dispose de plusieurs salles pouvant accueillir jusqu’à 813 spectateur(trice)s par événement. Des artistes de renom du Québec et d’ailleurs s''y produisent régulièrement offrant ainsi une multiplicité d’expériences artistiques au public. Une programmation inclusive qui permet une sensibilisation aux arts et à la culture pour toute la population!', 'culture', 45.4364891, -73.6053467, 40, null::extensions.geography, '1111 Rue Lapierre, Montréal H8N 2J4', 'LaSalle', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '635', false, null, true),
