  ('parc-jeanne-mance', 'Parc Jeanne-Mance', 'Parc à chiens et chiens en laisseQu''il soit question d''un petit ou d''un gros toutou, tous les chiens doivent être tenus en laisse dans nos parcs sans exception.Les propriétaires récalcitrants s’exposent à des amendes pouvant atteindre 300 $.À noter que l’aménagement d’un parc à chien clôturé dans le secteur sud près de l’avenue Duluth est prévu au cours du printemps 2025.Il s’agit d’un emplacement temporaire jusqu’à sa relocalisation.Plus de détails ici.Utilisation d''un barbecue dans l''aire de pique-niqueIl est interdit d’utiliser un barbecue, alimenté au charbon de bois, ou tout autre…', 'park', 45.5161487, -73.5850164, 237, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.578146,45.511837],[-73.577816,45.512156],[-73.579824,45.513063],[-73.579519,45.513415],[-73.58168,45.514373],[-73.580985,45.515131],[-73.587849,45.518253],[-73.589037,45.516939],[-73.589002,45.516787],[-73.578146,45.511837]]]]}'),4326)),3))::extensions.geography, null, 'Le Plateau-Mont-Royal', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '676', false, null, true),
  ('parc-jehane-benoit', 'Parc Jehane-Benoit', 'Situé à proximité de l''Institut de tourisme et d''hôtellerie du Québec, reconnu pour la formation et l''enseignement des techniques culinaires, le parc Jehane-Benoit rend hommage à une pionnière québécoise en art culinaire.', 'park', 45.5186534, -73.5690096, 40, null::extensions.geography, null, 'Le Plateau-Mont-Royal', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '677', false, null, true),
  ('parc-la-fontaine', 'Parc La Fontaine', 'Ne manquez pas l’oiseau vedette du parc, l’étourneau sansonnet. Ce volatile au plumage brun est reconnu pour ses capacités d’imitation de chants d’oiseaux. Au fil de vos promenades, découvrez les nombreuses expositions culturelles présentées dans les différents espaces du parc tout au long de l’année.Aires de jeu accessibles toute l’annéeLes balançoires et autres modules des parcs avec aires de jeux de l’arrondissement sont maintenant disponibles toute l’année.La prudence demeure de mise, surtout lors de périodes de gel.Travaux dans le parc La Fontaine : projets en coursVoici tout ce que vous…', 'park', 45.5263376, -73.5689408, 370, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.564481,45.526885],[-73.564149,45.527945],[-73.56949,45.530429],[-73.573345,45.526438],[-73.573293,45.526224],[-73.573895,45.525481],[-73.566808,45.522223],[-73.565802,45.523312],[-73.568601,45.524609],[-73.567678,45.525718],[-73.567434,45.525609],[-73.567225,45.52584],[-73.565108,45.524887],[-73.564481,45.526885]]]]}'),4326)),3))::extensions.geography, null, 'Le Plateau-Mont-Royal', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '678', false, null, true),
  ('parc-lahaie', 'Parc Lahaie', 'Utilisation d''un barbecue dans l''aire de pique-niqueIl est interdit d’utiliser un barbecue, alimenté au charbon de bois, ou tout autre combustible, à l’exception du gaz propane ou du butane, afin d''améliorer la qualité de vie et la sécurité dans nos parcs en plus d''enrayer les risques d''incendie sur le mobilier urbain ainsi que dans les enclos à déchets. Il est interdit également d''abandonner toutes bonbonnes de gaz ou de butane vides.Aussi à lire: Connaître les modalités de la collecte itinérante des résidus domestiques dangereux', 'park', 45.5230368, -73.5918886, 52, null::extensions.geography, null, 'Le Plateau-Mont-Royal', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '679', false, null, true),
  ('parc-laval', 'Parc Laval', 'Le parc Laval est situé entre l''avenue des Pins Est et le square Saint-Louis.Utilisation d’un barbecue dans l’aire de pique-niqueIl est interdit d’utiliser un barbecue, alimenté au charbon de bois, ou tout autre combustible, à l’exception du gaz propane ou du butane, afin d’améliorer la qualité de vie et la sécurité dans nos parcs en plus d’enrayer les risques d’incendie sur le mobilier urbain ainsi que dans les enclos à déchets.', 'park', 45.5169788, -73.5718584, 40, null::extensions.geography, null, 'Le Plateau-Mont-Royal', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '680', false, null, true),
  ('parc-lhasa-de-sela', 'Parc Lhasa-De Sela', 'Chanteuse, auteure et compositrice d’origine américano-mexicaine, Lhasa (1972-2010), avait fait du Mile End son quartier d’adoption et son lieu de création. Les chansons qu''elle a interprétées en français, en anglais et en espagnol ont rayonné à travers le monde.Elle a publié trois albums: La Llorona (1997), The Living Road (2003) et Lhasa (2009).En décembre 2010, le Times de Londres plaçait The Living Road en troisième position des meilleurs disques de musique du monde des 10 dernières années.Aires de jeu accessibles toute l’annéeLes balançoires et autres modules des parcs avec aires de jeux…', 'park', 45.5273077, -73.6047205, 50, null::extensions.geography, null, 'Le Plateau-Mont-Royal', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '681', false, null, true),
  ('parc-louis-reitman', 'Parc Louis-Reitman', null, 'park', 45.5158882, -73.5759735, 40, null::extensions.geography, null, 'Le Plateau-Mont-Royal', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '682', false, null, true),
  ('parc-ludger-duvernay', 'Parc Ludger-Duvernay', 'Venez profiter des attraits de la nature ou pratiquer des loisirs en plein air.Ce parc est aussi un site de compostage collectif.Espace en gestion différenciéeSaviez-vous que plus de 5 500 m² de terrain sont entretenus selon le principe de gestion différenciée dans l’arrondissement? C’est pourquoi l’herbe est plus longue dans certains secteurs de parcs du Plateau, comme celui-ci. Cette approche favorise la biodiversité, aide à lutter contre les changements climatiques et soutient nos efforts de verdissement. Plus de détails ici', 'park', 45.5312538, -73.5920105, 40, null::extensions.geography, null, 'Le Plateau-Mont-Royal', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '683', false, null, true),
  ('parc-napoleon', 'Parc Napoléon', null, 'park', 45.517273, -73.5775166, 40, null::extensions.geography, 'Avenue Coloniale, Montréal H2W 2B8', 'Le Plateau-Mont-Royal', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '684', false, null, true),
  ('parc-saint-michel', 'Parc Saint-Michel', 'Venez profiter des attraits de la nature ou pratiquer des loisirs en plein air.Aires de jeu accessibles toute l’annéeLes balançoires et autres modules des parcs avec aires de jeux de l’arrondissement sont maintenant disponibles toute l’année.La prudence demeure de mise, surtout lors de périodes de gel.', 'park', 45.5239706, -73.5925397, 52, null::extensions.geography, null, 'Le Plateau-Mont-Royal', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '685', false, null, true),
  ('parc-saint-pierre-claver', 'Parc Saint-Pierre-Claver', 'Venez profiter des attraits de la nature ou pratiquer des loisirs en plein air.Aires de jeu accessibles toute l’annéeLes balançoires et autres modules des parcs avec aires de jeux de l’arrondissement sont maintenant disponibles toute l’année.La prudence demeure de mise, surtout lors de périodes de gel.Toilette portable temporaireDe mai à octobre, une toilette temporaire portable est installée dans le parc.', 'park', 45.5398331, -73.5741043, 58, null::extensions.geography, null, 'Le Plateau-Mont-Royal', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '686', false, null, true),
  ('parc-sir-wilfrid-laurier', 'Parc Sir-Wilfrid-Laurier', 'Chiens en laisseQu''il soit question d''un petit ou d''un gros toutou, tous les chiens doivent être tenus en laisse dans nos parcs sans exception.Les propriétaires récalcitrants s’exposent à des amendes pouvant atteindre 600 $.PétanqueUn terrain de pétanque est disponible durant les heures d’ouverture du parc.Contactez-nous pour avoir plus de détails.Microforêt du parc Sir-Wilfrid-LaurierSituée dans le secteur nord-ouest du parc Sir-Wilfrid-Laurier, près de l’aire d’exercice canin, une microforêt aménagée selon la méthode Miyawaki favorise la biodiversité et réduit les îlots de chaleur urbains.', 'park', 45.5321732, -73.5875015, 201, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.590719,45.531912],[-73.586854,45.53019],[-73.584886,45.532392],[-73.588649,45.53414],[-73.590719,45.531912]]]]}'),4326)),3))::extensions.geography, null, 'Le Plateau-Mont-Royal', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '687', false, null, true),
