  ('place-du-coteau-saint-louis', 'Place du Côteau-Saint-Louis', null, 'landmark', 45.5279344, -73.5888225, 60, null::extensions.geography, 'Avenue Laurier Est, Montréal', 'Le Plateau-Mont-Royal', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '833', false, null, true),
  ('rue-marie-anne', 'Rue Marie-Anne', null, 'landmark', 45.5369888, -73.5673743, 60, null::extensions.geography, 'Rue Marie-Anne Ouest, Montréal', 'Le Plateau-Mont-Royal', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '834', false, null, true),
  ('place-guilbault', 'Place Guilbault', 'La rue Guilbault Est a été transformée en une place publique qui marque l’imaginaire des Montréalais avec des structures d''hippopotames ainsi que du mobilier assorti et des ilots de verdure.À la mémoire de Joseph-Édouard GuilbaultLe concept de la place Guilbault se veut un hommage à Joseph-Édouard Guilbault qui a animé ce secteur de la ville au milieu du 19e siècle, en créant notamment un premier jardin botanique, au coin de l’avenue des Pins et du boulevard Saint-Laurent, et en invitant le cirque Hippozoonomadon en 1862 (d’où la présence des hippopotames au cœur du concept d’aménagement).', 'landmark', 45.5148695, -73.5740848, 60, null::extensions.geography, 'Rue Guilbault Est, Montréal', 'Le Plateau-Mont-Royal', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '835', false, null, true),
  ('les-terrasses-roy', 'Les Terrasses Roy', 'L''aménagement des Terrasses Roy, réalisé en 2022-2023, a permis l''élargissement des trottoirs ainsi que l''ajout de mobilier urbain et d''espaces d''agriculture urbaine. Objectifs Offrir une place publique verte, ludique et rassembleuse, inclusive et innovante, pour et par les gens du quartier. Rallier la communauté autour des bienfaits de l’agriculture urbaine.', 'landmark', 45.5165856, -73.5749726, 60, null::extensions.geography, 'Rue Roy, Montréal', 'Le Plateau-Mont-Royal', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '836', false, null, true),
