  ('parc-campbell-ouest', 'Parc Campbell-Ouest', 'Des plateaux d''activités​Venez perfectionner vos tirs dans les paniers de basketball, jouez sur le terrain de pétanque, aux échecs et au ping-pong. Des jeux d''eau sont aussi disponibles pour vous rafraîchir l''été.Un jardin collectif​Un jardin en terre avec quatre bacs de jardinage surélevés, éclairé et bordé d''une forêt nourricière, est ouvert à la culture.', 'park', 45.4578889, -73.5902411, 84, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.588533,45.457471],[-73.588478,45.45808],[-73.590397,45.458165],[-73.590413,45.457656],[-73.589816,45.457628],[-73.589704,45.457526],[-73.588533,45.457471]]],[[[-73.59273,45.458125],[-73.592727,45.457779],[-73.590628,45.457691],[-73.590601,45.458177],[-73.592345,45.458255],[-73.592359,45.458107],[-73.59273,45.458125]]]]}'),4326)),3))::extensions.geography, null, 'Le Sud-Ouest', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '856', false, null, true),
