  ('parc-dargenson', 'Parc D''Argenson', 'On joue dans les parcsVenez bouger et vous amusez gratuitement dans les parc du Sud-Ouest. Consultez toutes les activités en cliquant ici.Piste à rouleaux (pumptrack)Ce parcours en boucle fermée constitué de bosses consécutives et de virages relevés permet d’avancer en gagnant de la vitesse avec le pompage des bras et du corps - de haut en bas.', 'park', 45.476028, -73.5717638, 89, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.573217,45.475996],[-73.573077,45.475529],[-73.571616,45.475568],[-73.570154,45.475745],[-73.571073,45.47662],[-73.571321,45.476472],[-73.571449,45.476579],[-73.572056,45.476563],[-73.572163,45.476649],[-73.573217,45.475996]]]]}'),4326)),3))::extensions.geography, null, 'Le Sud-Ouest', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '861', false, null, true),
