  ('parc-de-la-ferme-brodie', 'Parc de la Ferme-Brodie', 'M. Brodie y habitait et y cultivait des melons et des pommes. La thématique du nouveau module y fait référence!On joue dans les parcsVenez bouger et vous amusez gratuitement dans les parc du Sud-Ouest. Consultez toutes les activités en cliquant ici.', 'park', 45.4782639, -73.5856425, 40, null::extensions.geography, null, 'Le Sud-Ouest', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '863', false, null, true),
  ('parc-de-la-traite-des-fourrures', 'Parc de la Traite-des-Fourrures', 'Situé à côté de l’école Saint-Zotique, il est accessible au grand public après les cours, de 18 h à 22 h.', 'park', 45.4714884, -73.5896524, 40, null::extensions.geography, null, 'Le Sud-Ouest', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '864', false, null, true),
