  ('societe-historique-de-saint-henri', 'Société historique de Saint-Henri', null, 'museum', 45.4777937, -73.5851775, 50, null::extensions.geography, '521 Place Saint-Henri, Montréal H4C 2S1', 'Le Sud-Ouest', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '970', false, null, true),
  ('square-sainte-elisabeth', 'Square Sainte-Élisabeth', 'Un espace naturel pour se divertirLes jeunes peuvent jouer en toute sécurité dans la zone de jeu clôturée dans un décor naturel. Pour les journées chaudes, une pompe à eau est disponible pour créer une multitude de sculptures de sable. Pour se rafraîchir, un brumisateur est aussi installé. Les aires gazonnées permettent de s’adonner à de nombreuses activités libres et pique-niquer avec son voisinage ou en famille.Transition écologique et biodiversitéTout a été mis en oeuvre pour favoriser la transition écologique et la gestion durable du square Sainte-Élisabeth.', 'park', 45.4748878, -73.5926091, 41, null::extensions.geography, null, 'Le Sud-Ouest', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '971', false, null, true),
