insert into public.landmarks (slug, name, description, category, latitude, longitude, geofence_radius_m, geofence_polygon, address, neighbourhood, source_name, source_url, source_license, source_record_id, needs_review, review_note, is_active) values
  ('rue-charlebois', 'Rue Charlebois', null, 'landmark', 45.4764192, -73.5870285, 60, null::extensions.geography, 'Rue Charlebois, Montréal', 'Le Sud-Ouest', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1003', false, null, true),
  ('parvis-de-biencourt', 'Parvis de Biencourt', 'Situé entre le boulevard Monk et la rue Briand, ce lieu de rencontre est le prolongement naturel du parvis de l’ancienne église Notre-Dame-du-Perpétuel-Secours devenue le Théâtre Paradoxe. La placette offre une vue imprenable sur ce bâtiment d’intérêt patrimonial. L’aménagement du tronçon contribue à rehausser l’animation et l’attractivité du boulevard Monk, artère commerciale en revitalisation à laquelle il aboutit.', 'landmark', 45.4588626, -73.5957067, 60, null::extensions.geography, 'Rue de Biencourt, Montréal', 'Le Sud-Ouest', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1004', false, null, true),
  ('place-du-marche', 'Place du Marché', 'Située à proximité du marché Atwater et du canal de Lachine, entre la rue Sainte-Émilie et l’avenue Greene, la rue Saint-Ambroise bénéficie d’une forte visibilité et d’un important achalandage de longue date. Elle accueille nombre de commerces et de services. Les abords du marché offrent un réel potentiel de création en raison de l’espace ludique et de détente déjà en place et de son animation habituelle.ObjectifsCréer un lieu de rassemblement pour les résidents et les visiteurs du marché Atwater, du canal de Lachine et des commerces adjacents.InstallationsBrumisateursPlacottoirs avec…', 'landmark', 45.4791848, -73.5756425, 60, null::extensions.geography, 'Rue Saint-Ambroise et Atwater, Montréal', 'Le Sud-Ouest', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1005', false, null, true),
  ('maison-de-la-culture-maisonneuve', 'Maison de la culture Maisonneuve', 'Maisonneuve est la première maison de la culture à avoir ouvert ses portes à Montréal, en 1981. Le bâtiment, construit en 1907, a aussi abrité une caserne de pompiers jusqu’au milieu des années 1990.', 'culture', 45.5511819, -73.5403033, 40, null::extensions.geography, '4200 Rue Ontario Est, Montréal H1V 1K1', 'Mercier–Hochelaga-Maisonneuve', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1021', false, null, true),
