  ('bibliotheque-dhochelaga', 'Bibliothèque d''Hochelaga', null, 'culture', 45.5423927, -73.5454254, 40, null::extensions.geography, '1870 Rue Davidson, Montréal H1W 2Y6', 'Mercier–Hochelaga-Maisonneuve', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1094', false, null, true),
  ('bibliotheque-langelier', 'Bibliothèque Langelier', 'Sur l’un des murs de la bibliothèque Langelier, une magnifique murale réalisée par les jeunes artistes de l''atelier le Fil d''Ariane illustre des contes traditionnels. La bibliothèque ouvre sa terrasse durant la saison estivale, permettant à sa clientèle de profiter de la lecture et du soleil en même temps.Pour connaître l’ensemble des services des bibliothèques de Montréal, c’est par ici.À découvrirProgrammation culturelleGrainothèqueProgramme d''éveil à la lecture Une naissance, un livrePlan directeur culturel de MHMBibliothèque numériqueLe réseau des bibliothèques de Montréal vous offre de…', 'culture', 45.581726, -73.544151, 40, null::extensions.geography, '6473 Rue Sherbrooke Est, Montréal H1N 1C5', 'Mercier–Hochelaga-Maisonneuve', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1099', false, null, true),
  ('bibliotheque-maisonneuve', 'Bibliothèque Maisonneuve', 'Lorsqu''on pénètre dans la bibliothèque Maisonneuve, on est frappé de voir des armoiries en céramique sur le plancher. C''est que l''édifice a servi d''hôtel de ville à l''ancienne municipalité de Maisonneuve de 1912 à 1918, année de son annexion à Montréal. En 1925, elle a aussi abrité l''Institut du radium de l''Université de Montréal qui formait à l’époque les radiologistes et où La Bolduc mourut en 1941.', 'culture', 45.5506362, -73.5406108, 40, null::extensions.geography, '4120 Rue Ontario Est, Montréal H1V 1J9', 'Mercier–Hochelaga-Maisonneuve', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1101', false, null, true),
  ('bibliotheque-mercier', 'Bibliothèque Mercier', 'La bibliothèque Mercier a des collections et des espaces pour les adultes, les adolescent(e)s de plus de 14 ans et les plus jeunes.Pour connaître l’ensemble des services des bibliothèques de Montréal, c’est par ici.À découvrirProgrammation culturelleGrainothèqueProgramme d''éveil à la lecture Une naissance, un livrePlan directeur culturel de MHMBibliothèque numériqueLe réseau des bibliothèques de Montréal vous offre de plus en plus de titres grâce à sa plateforme de prêt numérique : livres, journaux, cours de langue, musique, jeux… Une fois par mois, vos bibliothécaires vous révèlent leurs…', 'culture', 45.5955055, -73.5237638, 40, null::extensions.geography, '8105 Rue Hochelaga, Montréal H1L 2K9', 'Mercier–Hochelaga-Maisonneuve', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1102', false, null, true),
