  ('bibliohteque-henri-bourassa', 'Bibliohtèque Henri-Bourassa', null, 'culture', 45.6046442, -73.6251778, 40, null::extensions.geography, '5400 Boulevard Henri-Bourassa Est, Montréal H1G 2S9', 'Montréal-Nord', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1240', false, null, true),
  ('bibliotheque-belleville', 'Bibliothèque Belleville', 'En 2027, la bibliothèque et espace culturel du Cœur-Nomade ouvrira ses portes à l’angle du boulevard Henri-Bourassa Est et de l’avenue Oscar.Abonnement L’abonnement est gratuit pour les résidents de Montréal et donne accès aux services de l’ensemble des bibliothèques du Réseau des bibliothèques de Montréal.', 'culture', 45.5819587, -73.6422682, 40, null::extensions.geography, '10400 Avenue de Belleville, Montréal H1H 4Z7', 'Montréal-Nord', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1241', false, null, true),
  ('bibliotheque-yves-ryan', 'Bibliothèque Yves-Ryan', 'La bibliothèque Yves-Ryan, autrefois nommée Charleroi, est la première bibliothèque de Montréal-Nord.Elle a ouvert ses portes en février 1970. C’est aussi la première bibliothèque automatisée au Québec. En 2012, sa façade est refaite et en 2015, à l’occasion du centenaire de l’arrondissement, la bibliothèque est renommée en l’honneur de l’ancien maire Yves Ryan, qui a occupé ses fonctions pendant 38 ans.', 'culture', 45.5964737, -73.6314011, 40, null::extensions.geography, '4740 Rue de Charleroi, Montréal H1H 1V2', 'Montréal-Nord', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1242', false, null, true),
