  ('station-amos', 'Station Amos', null, 'landmark', 45.5947967, -73.6407137, 60, null::extensions.geography, 'Rue Amos, Montréal', 'Montréal-Nord', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1282', false, null, true),
  ('rue-de-dijon', 'Rue de Dijon', 'Située entre l’avenue P.-M.-Favier et le boulevard Rolland, la piétonnisation de la rue de Dijon constitue la première étape de réalisation du vaste projet de corridor vert dont la réalisation s’étendra sur cinq ans. Ce lieu de rencontre ludique et coloré est situé dans un quartier habité par un nombre élevé de familles. Il fait le pont entre l’école primaire Le Carignan, le parc Le Carignan et l’école secondaire Lester B. Pearson.', 'landmark', 45.6107239, -73.6163591, 60, null::extensions.geography, 'Rue de Dijon, Montréal', 'Montréal-Nord', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1283', false, null, true),
