  ('parc-des-anciens-combattants', 'Parc des Anciens-Combattants', 'Le parc des Anciens-Combattants est un lieu privilégié pour se détendre, profiter des attraits de la nature et pratiquer des loisirs en plein air : embarcation nautique non motorisée, volleyball de plage, pétanque (bocce), jeu de palet (shuffleboard), randonnée, module de jeu pour enfants et plus!Location de kayaksDurant la période estivale, notre organisme partenaire GUEPE assure la location de kayaks, de différentes activités de programmation, ainsi que de la gestion du pavillon. Le site nautique est actuellement fermé pour la saison froide.', 'park', 45.5094531, -73.7829333, 110, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.784322,45.508615],[-73.784122,45.508773],[-73.783997,45.50869],[-73.783559,45.509059],[-73.783345,45.508971],[-73.783365,45.508718],[-73.782985,45.508474],[-73.782719,45.508677],[-73.78213,45.508745],[-73.781505,45.508352],[-73.781425,45.508046],[-73.781525,45.507901],[-73.781393,45.507896],[-73.779936,45.508809],[-73.780686,45.508928],[-73.782092,45.509398],[-73.782922,45.509556],[-73.784333,45.509545],[-73.784443,45.509524],[-73.784452,45.509395],[-73.785408,45.509325],[-73.785417,45.509265],[-73.784322,45.508615]]]]}'),4326)),3))::extensions.geography, null, 'Pierrefonds-Roxboro', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1367', false, 'point is 25 m outside the land boundary (shoreline/quay); kept', true),
