  ('bibliotheque-de-pierrefonds', 'Bibliothèque de Pierrefonds', 'On peut y admirer quatre grandes œuvres autonomes et interreliées de l’artiste Sarah Bertrand-Hamel réalisées dans le cadre du projet d’intégration des arts à l’architecture et à l’environnement. Intitulée L’épaisseur du papier, ces œuvres nous donnent à contempler une interprétation sensible de l’histoire du papier et du livre.', 'culture', 45.4960899, -73.8474731, 40, null::extensions.geography, '13555 Boulevard de Pierrefonds, Montréal H9A 1A6', 'Pierrefonds-Roxboro', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1437', false, null, true),
  ('bibliotheque-de-roxboro-william-g-boll', 'Bibliothèque de Roxboro William G.Boll', null, 'culture', 45.5025749, -73.8145905, 40, null::extensions.geography, '110 Rue Cartier, Montréal H8Y 1G8', 'Pierrefonds-Roxboro', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1438', false, null, true),
  ('centre-culturel-de-pierrefonds', 'Centre culturel de Pierrefonds', 'Programmation culturelleDécouvrez les spectacles de musique, les pièces de théâtre et les autres activités présentées en consultant la Programmation culturelle ici.Réservez vos billets de spectaclesDes billets sont requis pour assister à la plupart des spectacles, qu’ils soient payants ou gratuits. Choisissez l’une des trois options suivantes :En ligne sur notre billetterie *Des frais de service s’appliquent.En personne, en prenant rendez-vous avec un membre de notre équipe au 514 702-1812En personne, à la salle de spectacle, à partir d’une heure avant l’événement.', 'culture', 45.4966164, -73.8493271, 40, null::extensions.geography, '13850 Boulevard Gouin Ouest, Montréal H8Z 1X7', 'Pierrefonds-Roxboro', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1458', false, null, true),
  ('cimetiere-sainte-genevieve', 'Cimetière Sainte-Geneviève', null, 'historic', 45.4804559, -73.8725038, 50, null::extensions.geography, '16037 Boulevard Gouin Ouest, Montréal H9H 1C7', 'L''Île-Bizard–Sainte-Geneviève', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1459', false, null, true),
  ('maison-antoine-beaudry', 'Maison Antoine-Beaudry', 'Située à Pointe-aux-Trembles et classée monument historique, la maison Antoine-Beaudry propose une programmation d''expositions, de spectacles, de conférences et d''activités en plein air.', 'culture', 45.6765862, -73.4912262, 40, null::extensions.geography, '14678 Rue Notre-Dame Est, Montréal H1A 1W1', 'Rivière-des-Prairies–Pointe-aux-Trembles', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1504', false, null, true),
