  ('parc-armand-bombardier', 'Parc Armand-Bombardier', 'Profitez des attraits de la nature ou pratiquez des loisirs en plein air.Une station Bixi électrifiée est installée aux abords du parc.-----Du 20 mai au 25 juin, un troupeau d’une douzaine de moutons de Biquette-Écopâturage passera ses journées au parc Armand-Bombardier dans le quartier de Rivière-des-Prairies dans le cadre du projet d’écopâturage urbain.', 'park', 45.640736, -73.5962605, 168, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.597723,45.643225],[-73.598847,45.642634],[-73.599126,45.642385],[-73.598216,45.64186],[-73.598026,45.641456],[-73.598078,45.640927],[-73.597552,45.640686],[-73.597335,45.640438],[-73.59793,45.639617],[-73.596919,45.638674],[-73.594878,45.639746],[-73.595887,45.640715],[-73.595849,45.640855],[-73.595456,45.641063],[-73.597723,45.643225]]]]}'),4326)),3))::extensions.geography, null, 'Rivière-des-Prairies–Pointe-aux-Trembles', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1513', false, null, true),
