  ('parc-clementine-de-la-rousseliere', 'Parc Clémentine-De La Rousselière', 'Profitez des attraits de la nature ou pratiquez des loisirs en plein air. Ce parc riverain comprend un bâtiment de services accessible construit en 2019.Zone d’entraide maritime (Z.E.M.) – Jeunes Marins UrbainsEnvie de pagayer en toute autonomie tout en suivant un parcours sécuritaire et bien balisé? Découvrez la Z.E.M., une boucle nautique d’environ 4 km conçue par Jeunes Marins Urbains.', 'park', 45.6684494, -73.4925842, 154, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.49197,45.669336],[-73.494113,45.669651],[-73.494224,45.669179],[-73.494258,45.667521],[-73.493744,45.66743],[-73.493778,45.667172],[-73.492677,45.667045],[-73.492835,45.666538],[-73.491686,45.66637],[-73.491409,45.666839],[-73.491434,45.66708],[-73.491587,45.667295],[-73.491451,45.667997],[-73.491481,45.669253],[-73.49197,45.669336]]]]}'),4326)),3))::extensions.geography, null, 'Rivière-des-Prairies–Pointe-aux-Trembles', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1517', false, null, true),
  ('parc-conrad-poirier', 'Parc Conrad-Poirier', 'Dans le cadre de la deuxième édition du budget participatif de la Ville de Montréal, l’arrondissement de Rivière-des-Prairies–Pointe-aux-Trembles a inauguré un gym à ciel ouvert au parc Conrad-Poirier. Ce projet, issu d’une mobilisation citoyenne, vise à favoriser l’activité physique pour tous les âges et à renforcer les liens communautaires.', 'park', 45.6369705, -73.5972443, 97, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.597705,45.635651],[-73.595951,45.636581],[-73.597507,45.638042],[-73.598446,45.637544],[-73.597533,45.636639],[-73.597609,45.636441],[-73.598207,45.636126],[-73.597705,45.635651]]]]}'),4326)),3))::extensions.geography, null, 'Rivière-des-Prairies–Pointe-aux-Trembles', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1518', false, null, true),
