  ('parc-des-cageux', 'Parc des Cageux', 'Après avoir inauguré une halte piétonne et cycliste dans le cadre de la première édition du budget participatif en 2023, l’arrondissement a poursuivi en 2024 les bonifications au parc des Cageux avec l’ajout d’un quai flottant (du printemps à l''automne) pour petites embarcations comme les planches à pagaie et les kayaks.', 'park', 45.6721472, -73.5426771, 157, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.535826,45.677166],[-73.535894,45.676997],[-73.536446,45.676436],[-73.538221,45.67537],[-73.538309,45.675245],[-73.538493,45.675202],[-73.540815,45.673868],[-73.542438,45.672822],[-73.545032,45.671353],[-73.545303,45.671162],[-73.545251,45.671081],[-73.544021,45.671368],[-73.541966,45.672006],[-73.541302,45.672346],[-73.538871,45.674156],[-73.537934,45.674719],[-73.536625,45.675733],[-73.535773,45.677089],[-73.535826,45.677166]]]]}'),4326)),3))::extensions.geography, null, 'Rivière-des-Prairies–Pointe-aux-Trembles', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1528', false, null, true),
