  ('eglise-saint-joseph', 'Église Saint-Joseph', 'Reconnaissable grâce à son clocher en flèche élancée, l''église Saint-Joseph est au cœur de l''activité du Vieux Village de Rivière-des-Prairies. Elle se fait également l''hôte de spectacles culturels très appréciés des habitants du quartier.', 'religious', 45.6628639, -73.561451, 60, null::extensions.geography, '10050 Boulevard Gouin Est, Montréal H1C 1A8', 'Rivière-des-Prairies–Pointe-aux-Trembles', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1625', false, null, true),
  ('ici-avant-ensuite-et-maintenant', 'Ici avant, ensuite et maintenant', 'Art public : Éric Cardinal, Ici avant, ensuite et maintenant, 2014.', 'public-art', 45.639844, -73.4899998, 25, null::extensions.geography, null, 'Rivière-des-Prairies–Pointe-aux-Trembles', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1626', false, null, true),
  ('maison-armand', 'Maison Armand', null, 'historic', 45.6961746, -73.5174551, 50, null::extensions.geography, '12930 Boulevard Gouin Est, Montréal H1C 1C1', 'Rivière-des-Prairies–Pointe-aux-Trembles', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1627', false, null, true),
  ('place-du-village-de-la-pointe-aux-trembles', 'Place du Village-de-la-Pointe-aux-Trembles', 'Cet espace urbain offre aux visiteurs une multitude d''événements dans une atmosphère conviviale.Une œuvre d’art public monumentale à l’entrée de la place confère une identité distinctive à ce lieu riche en patrimoine historique.Une station Bixi est installée sur le site.Tableau Cité Mémoire La Pointe de l''ÎleCette œuvre multimédia est projetée au sol de la place publique et se déploie de façon spectaculaire en images, en paroles et en musique pour une durée d’environ 30 minutes, dès le coucher du soleil.', 'landmark', 45.639844, -73.4899998, 60, null::extensions.geography, 'Boulevard Saint-Jean-Baptiste, Montréal', 'Rivière-des-Prairies–Pointe-aux-Trembles', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1630', false, null, true),
