  ('eglise-de-saint-leonard-de-port-maurice', 'Église de Saint-Léonard-de-Port-Maurice', null, 'religious', 45.5856312, -73.591085, 60, null::extensions.geography, '5525 Rue Jarry Est, Montréal H1P 1V9', 'Saint-Léonard', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1963', false, null, true),
  ('bibliotheque-de-saint-leonard', 'Bibliothèque de Saint-Léonard', 'La première bibliothèque de Saint-Léonard est inaugurée en 1966 sur la rue Jarry, dans une maison très modeste. En 1974, le nouvel hôtel de ville et la bibliothèque actuelle sont construits côte à côte, sur le boulevard Lacordaire. Agrandie en 1984, la bibliothèque se modernise au fil des années et abrite aujourd’hui la splendide Galerie Port-Maurice.Vous trouverez également de nombreux renseignements sur la bibliothèque et les services sur la page Facebook de la bibliothèque de Saint-Léonard.', 'culture', 45.5867341, -73.5975648, 40, null::extensions.geography, '8420 Boulevard Lacordaire, Montréal H1R 3G5', 'Saint-Léonard', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1969', false, null, true),
