  ('galerie-port-maurice', 'Galerie Port-Maurice', 'Des expositions d''artistes de différents courants contemporains y sont présentées.', 'culture', 45.5866063, -73.5974736, 40, null::extensions.geography, '8420 Boulevard Lacordaire, Montréal H1R 3G5', 'Saint-Léonard', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '1989', false, null, true),
