  ('parc-adrien-d-archambault', 'Parc Adrien-D.-Archambault', 'Fermeture temporaire des terrains de soccer pour travauxLes terrains de soccoer seront fermés temporairement, de octobre 2025 à mai 2026, pour effectuer des travaux d''entretien.Aménagement d’une piste à rouleaux dans le parc Adrien-D.-Archambault En 2025, l’arrondissement de Verdun prévoit aménager une piste à rouleaux (pumptrack) au parc Adrien-D.-Archambault, sur une partie de terrain en friche près du boulevard de la Forêt.', 'park', 45.4556424, -73.5577461, 213, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.556407,45.456721],[-73.556522,45.456559],[-73.556535,45.456951],[-73.557,45.457164],[-73.558419,45.457303],[-73.559576,45.455107],[-73.559402,45.455107],[-73.559395,45.454901],[-73.558973,45.454901],[-73.558973,45.454964],[-73.55592,45.454967],[-73.555821,45.453965],[-73.55565,45.45377],[-73.555008,45.453568],[-73.555152,45.453377],[-73.554785,45.452757],[-73.554673,45.452767],[-73.554281,45.453208],[-73.554347,45.453703],[-73.554253,45.454362],[-73.554338,45.454637],[-73.554233,45.454857],[-73.554189,45.455681],[-73.554337,45.456011],[-73.554151,45.456412],[-73.554133,45.457092],[-73.554951,45.457103],[-73.555275,45.457734],[-73.555357,45.457692],[-73.555399,45.457776],[-73.556176,45.457188],[-73.5564,45.456913],[-73.556407,45.456721]]]]}'),4326)),3))::extensions.geography, null, 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2017', false, null, true),
  ('parc-alfred-sauve', 'Parc Alfred-Sauvé', 'Piste cyclable longeant le parc. Nom donné à la mémoire d''Alfred Sauvé qui fut cordonnier pendant 40 ans à Verdun, à l''intersection des rues Ethel et Strathmore, soit à proximité de l''emplacement de ce parc. Père d''une famille nombreuse et très impliqué dans sa communauté, il fut l''un des fondateurs de la Caisse populaire Desjardins de Notre-Dame-de-la-Paix. Il oeuvra comme marguillier bénévole à la paroisse du même nom et s''impliqua également auprès des démunis au sein de la Société Saint-Vincent de Paul. Alfred Sauvé est décédé le 29 avril 1989, à l''âge de 94 ans.', 'park', 45.4716998, -73.5661937, 40, null::extensions.geography, null, 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2018', false, null, true),
  ('parc-archie-wilcox', 'Parc Archie-Wilcox', 'Piste cyclable longeant le parc, terrains de pétanque et circuit d''entraînement.Nommé en l''honneur de Thomas Archibald (Archie) Wilcox, joueur de hockey professionnel dans la Ligue nationale de hockey pour les Maroons de Montréal, les Bruins de Boston et les Eagles de Saint-Louis, de 1929 à 1935 et qui fut également conseiller municipal de Verdun, de 1945 à 1973.', 'park', 45.4528465, -73.5668793, 51, null::extensions.geography, null, 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2019', false, null, true),
  ('parc-arthur-therrien', 'Parc Arthur-Therrien', 'Butte pour la glissade et piste de ski de fondPrêt gratuit de tubes, skis de fond et raquettes au chalet du parc Arthur-TherrienTennis6 terrains de tennis. Réservations en ligne sur Loisirs Montréal avec la carte Biblio-Loisirs et la vignette appropriée.Site de planche à roulettesUn skatepark extérieur offre aux amateurs de planche à roulettes, de BMX, de trottinette et de patin acrobatique un environnement unique pour pratiquer leurs figures en toute sécurité.', 'park', 45.46599, -73.561189, 250, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.562049,45.463652],[-73.560796,45.463597],[-73.560935,45.462041],[-73.560072,45.462003],[-73.560056,45.463219],[-73.559788,45.464582],[-73.559568,45.468006],[-73.559269,45.4684],[-73.558917,45.46866],[-73.558271,45.468933],[-73.558694,45.469174],[-73.558886,45.469418],[-73.562387,45.469601],[-73.562487,45.469501],[-73.562715,45.468903],[-73.562761,45.468284],[-73.562286,45.466752],[-73.562235,45.466249],[-73.562745,45.464661],[-73.562294,45.464642],[-73.562049,45.463652]]]]}'),4326)),3))::extensions.geography, '3750 Boulevard Gaétan Laberge, Montréal', 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2020', false, null, true),
  ('parc-beatty', 'Parc Beatty', 'Situé en bordure du boulevard LaSalle et des terrains du Club de tennis Woodland, ce parc a été nommé en l''honneur de l''un des associés de l''étude légale Gooderham and Beatty de qui ce terrain fut acheté par la Osborne Park Land Co. Ltd pour des fins de subdivisions en lots de construction. Dans ce petit coin de verdure, on retrouve des aires de jeu pour enfants et tout-petits ainsi qu''une piste cyclable traversant le parc.', 'park', 45.450659, -73.5677413, 40, null::extensions.geography, null, 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2022', false, null, true),
  ('parc-beurling', 'Parc Beurling', 'Nommé en mémoire du pilote de l''air de la Royal Air Force, George Frederick Beurling, aussi surnommé le « Fou volant ». Ce dernier était natif de Verdun. On retrouve au parc Beurling plusieurs terrains de soccer en gazon naturel. Il s''agit du site d’entraînement pour les équipes de l’Association du Soccer Mineur de Verdun (ASMV). Durant l’été, l’ASMV y offre des camps de jour.', 'park', 45.4479713, -73.5848694, 89, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.584155,45.44714],[-73.583722,45.448503],[-73.585496,45.44868],[-73.585891,45.447443],[-73.584155,45.44714]]]]}'),4326)),3))::extensions.geography, null, 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2023', false, null, true),
