  ('parc-de-la-fontaine', 'Parc de la Fontaine', 'TennisSix (6) terrains. Réservations en ligne sur Loisirs Montréal avec la carte Biblio-Loisirs et la vignette appropriée.Piscine extérieureLes heures d''ouverture sont de 11 h 30 à 19 h 30 tous les jours.Boîtes de prêt-à-bougerUn nouveau point de service pour le prêt d’équipements est disponible dans le parc : la station connectée BoxUp. Cette boîte prêt-à-bouger est une solution de partage de matériel de loisir et de sport qui utilise la technologie d’une application mobile.', 'park', 45.4638375, -73.5441555, 134, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.541327,45.466089],[-73.541425,45.466309],[-73.542783,45.465875],[-73.54452,45.465679],[-73.544545,45.464964],[-73.544684,45.464491],[-73.545831,45.462829],[-73.545179,45.462719],[-73.545055,45.463112],[-73.544553,45.463031],[-73.544635,45.462782],[-73.544309,45.46273],[-73.544192,45.463381],[-73.54374,45.463307],[-73.543759,45.463248],[-73.542427,45.463032],[-73.542123,45.463489],[-73.542909,45.464012],[-73.542615,45.464218],[-73.542959,45.464015],[-73.543699,45.464538],[-73.543567,45.464631],[-73.543885,45.464855],[-73.543378,45.46521],[-73.543005,45.464985],[-73.54335,45.465229],[-73.542453,45.465857],[-73.542211,45.465957],[-73.542019,45.465822],[-73.541856,45.465936],[-73.541522,45.465968],[-73.541494,45.465921],[-73.541185,45.465999],[-73.541081,45.465957],[-73.541327,45.466089]]]]}'),4326)),3))::extensions.geography, null, 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2027', false, null, true),
