  ('parc-de-lhonorable-george-oreilly', 'Parc de l''Honorable-George-O''Reilly', 'Piste de danse Ouverte de la fin mai à la fin août, la piste de danse extérieure offre chaque jour durant la saison estivale une programmation diversifiée allant de la salsa à la danse sociale, sans oublier le tango et le Zumba. Natatorium de Verdun Consultez la page du Natatorium de Verdun. Volleyball de plage Réservation en ligne sur Loisirs Montréal.', 'park', 45.4376299, -73.5818009, 348, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.563988,45.453758],[-73.565633,45.45447],[-73.565779,45.454384],[-73.565436,45.454241],[-73.566101,45.453446],[-73.566184,45.453473],[-73.566282,45.453326],[-73.5662,45.453299],[-73.566811,45.452383],[-73.566682,45.452378],[-73.566155,45.45325],[-73.565488,45.453051],[-73.565679,45.452735],[-73.565213,45.452596],[-73.566695,45.45014],[-73.567521,45.450387],[-73.566791,45.452197],[-73.566946,45.452236],[-73.567561,45.450665],[-73.567753,45.450298],[-73.568042,45.45035],[-73.568621,45.448958],[-73.569313,45.448425],[-73.571217,45.447673],[-73.571976,45.447083],[-73.573156,45.445696],[-73.573615,45.445284],[-73.576354,45.443786],[-73.577211,45.44323],[-73.577865,45.4426],[-73.57949,45.440539],[-73.580554,45.439525],[-73.583161,45.437231],[-73.585787,45.435327],[-73.583803,45.435045],[-73.582155,45.436471],[-73.581876,45.436562],[-73.581604,45.436938],[-73.579951,45.43824],[-73.579746,45.438532],[-73.579377,45.438673],[-73.579112,45.439023],[-73.578624,45.439288],[-73.577965,45.439956],[-73.577974,45.440035],[-73.577811,45.440082],[-73.576723,45.441055],[-73.576317,45.441152],[-73.575793,45.441514],[-73.575165,45.442268],[-73.573681,45.443564],[-73.572591,45.444235],[-73.57185,45.444897],[-73.571769,45.445062],[-73.571073,45.445608],[-73.570712,45.446047],[-73.570257,45.446324],[-73.569443,45.44706],[-73.568982,45.447317],[-73.5690