  ('parc-de-loree-du-bois', 'Parc de l''Orée-du-Bois', 'À l’abri du soleil de par ces arbres majestueux, le parc de l’Orée-du-Bois est un site qui permet aux enfants de s’amuser.', 'park', 45.4511375, -73.5509949, 40, null::extensions.geography, null, 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2033', false, null, true),
