  ('parc-de-west-vancouver', 'Parc de West-Vancouver', 'Un accès à l''eau pour les planches à pagaies et kayaks est aménagé.Une piste de glissade est aménagée durant la saison hivernale.Une placette propose un mobilier urbain moderne et confortable, ainsi que des aires dédiées aux pique-niques et aux rencontres.Le parc peut aussi accueillir des spectacles en plein air en période estivale.', 'park', 45.4570399, -73.542129, 99, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.540966,45.458607],[-73.541151,45.458602],[-73.541421,45.457632],[-73.542642,45.457813],[-73.542593,45.457136],[-73.542859,45.456496],[-73.542357,45.456244],[-73.543972,45.453824],[-73.543445,45.45422],[-73.54307,45.454684],[-73.54046,45.45843],[-73.540966,45.458607]]]]}'),4326)),3))::extensions.geography, null, 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2035', false, null, true),
