  ('parc-des-sittelles', 'Parc des Sittelles', 'Le parc des Sittelles est un lieu privilégié où les tout-petits peuvent s’amuser en toute quiétude.', 'park', 45.4592938, -73.5527667, 40, null::extensions.geography, null, 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2038', false, null, true),
  ('parc-desmarchais', 'Parc Desmarchais', 'Piste cyclable traversant le parc. Aménagement d''un parc à chiens temporaire le 30 mai 2023. Tire probablement son origine en mémoire du riche fermier, Julien Desmarchais, qui avait une terre dans les années 1880 dans les environs de l''actuel parc Desmarchais.', 'park', 45.4538635, -73.5660698, 44, null::extensions.geography, '5200 Boulevard LaSalle, Montréal H4H 1N8', 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2039', false, null, true),
  ('parc-du-quai-de-la-tortue', 'Parc du Quai-de-La Tortue', null, 'park', 45.4468253, -73.5707673, 58, null::extensions.geography, null, 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2040', false, null, true),
  ('parc-du-souvenir', 'Parc du Souvenir', 'Le Mémorial de la Victoire, ou Monument aux braves de Verdun, date de 1924. D’abord installé au parc des Madelinots, il trouve sa place au parc du Souvenir, près de la mairie d’arrondissement, en 1959.Initialement, l’oeuvre d’art rend hommage aux héros de la Première guerre mondiale. Afin de refléter l’engagement des soldats à travers le temps, des inscriptions ont été ajoutées sur le monument pour rendre hommage aux Verdunois tombés au champ d’honneur lors de la deuxième guerre mondiale et de la guerre de Corée.En novembre 2022, l''arrondissement a inauguré un nouveau muret, qui vient…', 'park', 45.4590569, -73.572295, 43, null::extensions.geography, null, 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2041', false, null, true),
