  ('parc-elgar', 'Parc Elgar', null, 'park', 45.4576905, -73.5479379, 120, null::extensions.geography, '260 Rue Elgar, Montréal H3E 1C9', 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2043', false, null, true),
  ('parc-esplanade-de-la-pointe-nord', 'Parc Esplanade de la Pointe-Nord', null, 'park', 45.4733367, -73.5376384, 41, null::extensions.geography, null, 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2045', false, null, true),
  ('parc-gewurz-remer', 'Parc Gewurz-Remer', 'Aménagé en 2012, ce parc riverain offre un lien privilégié avec le centre-ville de Montréal et le fleuve Saint-Laurent. Le complexe de milieux humides et d''habitats fauniques élaboré est conçu pour s''intégrer dans un environnement urbain et offrir un design résolument contemporain.Des lignes fortes et graphiques organisent une série de bassins de rétention et de marais filtrants qui trouvent leur source dans les eaux de ruissellement des sites adjacents.Bénéfices de l''aménagement écologiqueRécupération, gestion et épuration de toutes les eaux pluviales du bassin du quartierCréation d''un…', 'park', 45.4738426, -73.540596, 40, null::extensions.geography, null, 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2046', false, null, true),
