  ('parc-sutherland-sackville-bain', 'Parc Sutherland-Sackville-Bain', 'Le parc Sutherland-Sackville-Bain est un lieu privilégié pour se détendre, profiter des attraits de la nature ou pratiquer des loisirs en plein air.', 'park', 45.4679589, -73.5642316, 52, null::extensions.geography, null, 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2063', false, null, true),
