  ('parc-wilson', 'Parc Wilson', 'On retrouve dans ce parc quatre terrains de tennis, un terrain de pickleball, des modules de jeu pour enfants et un sentier idéal pour apprendre aux enfants à faire du vélo.', 'park', 45.4487141, -73.5800988, 80, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.582341,45.448807],[-73.58226,45.448745],[-73.577126,45.448278],[-73.577142,45.448773],[-73.581017,45.448933],[-73.582341,45.448807]]]]}'),4326)),3))::extensions.geography, '1075 Avenue Brown, Montréal H4H 1H6', 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2065', false, null, true),
