  ('temple-sikh-gurdwara-nanak-darbar', 'Temple Sikh Gurdwara Nanak Darbar', null, 'religious', 45.4403467, -73.6324641, 60, null::extensions.geography, '7801 Rue Cordner, Montréal H8N 2X2', 'LaSalle', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2072', false, null, true),
  ('auditorium-de-verdun', 'Auditorium de Verdun', 'Activités offertes (avec ou sans inscription)L''horaire détaillé des activités et l''inscription en ligne sont et se font sur la plateforme Loisirs Montréal. Vous y trouverez aussi des règles à suivre ainsi que le tarif de l''activité si celle-ci n''est pas gratuite. L''inscription en ligne ouvre deux jours avant l''activité à partir de 8 h.Votre carte de loisirs est obligatoire.À noter que les entraînements avec un instructeur ou instructrice privé(e) ne seront pas autorisés.Découvrez le projet d''amélioration en cours Important : Dans le but de maintenir son actif patrimonial, l’arrondissement de…', 'culture', 45.4626846, -73.5618439, 40, null::extensions.geography, '4110 Boulevard LaSalle, Montréal H4G 2A5', 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2073', false, null, true),
  ('bibliotheque-de-lile-des-soeurs', 'Bibliothèque de L''île-des-Sœurs', null, 'culture', 45.4571266, -73.5473099, 40, null::extensions.geography, '260 Rue Elgar, Montréal H3E 1C9', 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2076', false, null, true),
  ('bibliotheque-jacqueline-de-repentigny', 'Bibliothèque Jacqueline-De Repentigny', 'Découvrez une bibliothèque accueillante, vivante et unique. Que vous soyez ici pour jouer, explorer ou travailler, en solo ou en groupe, la bibliothèque Jacqueline-De Repentigny offre des services et des espaces de travail de qualité. À Verdun, c''est l''endroit idéal pour rencontrer, échanger et s’ouvrir sur le monde.Psst : L''équipe se déplace l''été pour animer la bibliothèque de plage jusqu''au dimanche 23 août.Bon à savoirEn 2017, la bibliothèque de Verdun a été renommée bibliothèque Jacqueline-De Repentigny en l''honneur d''une grande Verdunoise.', 'culture', 45.4485474, -73.5778732, 40, null::extensions.geography, '5955 Rue Bannantyne, Montréal H4H 1H6', 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2077', false, null, true),
  ('boise-du-domaine-saint-paul', 'Boisé du Domaine Saint-Paul', null, 'park', 45.4544296, -73.5529556, 120, null::extensions.geography, null, 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2079', false, null, true),
  ('centre-communautaire-elgar', 'Centre communautaire Elgar', 'Le Centre communautaire Elgar offre aux citoyennes et citoyens une programmation d''activités de loisirs et culturelles.Location de salles et d''espaces diversIl est possible de louer un espace pour la tenue d’activités occasionnelles telles que des réceptions, des fêtes d''enfant ou des réunions. Pour ce faire :consultez la démarche à suivre;remplissez le formulaire en ligne.Veuillez prendre note que le comptoir d''accueil peut être temporairement fermé.', 'culture', 45.4571266, -73.5473099, 40, null::extensions.geography, '260 Rue Elgar, Montréal H3E 1C9', 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2089', false, null, true),
  ('centre-culturel-de-verdun', 'Centre culturel de Verdun', null, 'culture', 45.4485474, -73.5778732, 40, null::extensions.geography, '5955 Rue Bannantyne, Montréal H4H 1H6', 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2090', false, null, true),
  ('quai-5160-maison-de-la-culture-de-verdun', 'Quai 5160 - Maison de la culture de Verdun', 'Les programmations en salle du Quai 5160 sont en billetterie payante à petits prix ou gratuites. Vous pouvez vous procurer vos sièges réservés (sauf indication contraire) en achetant vos billets en ligne en tout temps ou au comptoir d''accueil selon les heures d''ouvertures.La mise en vente pour la saison d''automne se fait à la mi-août et celle de l''hiver-printemps à la mi-novembre.La billetterie en ligne est ici.Un lieu multifacettesAu-delà de sa programmation régulière, le mandat du Quai 5160 - Maison de la culture de Verdun comprend également l''organisation de résidences d''artistes, de…', 'culture', 45.4535461, -73.5650822, 40, null::extensions.geography, '5160 Boulevard LaSalle, Montréal H4H 1N8', 'Verdun', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2092', false, null, true),
