  ('parc-de-dieppe', 'Parc de Dieppe', 'Pendant la période estivale, des tables à pique-nique sont à votre disposition pour un moment convivial en famille ou entre amis. En vous y rendant en vélo, jetez un oeil à Habitat 67, ces constructions résidentielles originales qui font la renommée de Montréal encore aujourd’hui et qui ont été bâties pour l’Expo 67. Si vous avez le temps, non loin de là, faites une halte à la vague à Guy, une vague naturelle qui attire les surfeurs.', 'park', 45.5058327, -73.5432358, 128, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.543976,45.502317],[-73.543894,45.502312],[-73.543976,45.501601],[-73.543883,45.501646],[-73.5436,45.503909],[-73.543395,45.504179],[-73.543033,45.504369],[-73.543026,45.504821],[-73.542668,45.504953],[-73.54261,45.507842],[-73.542722,45.508023],[-73.542978,45.508114],[-73.543267,45.508061],[-73.543432,45.507886],[-73.544515,45.503093],[-73.544579,45.502501],[-73.544338,45.502338],[-73.544118,45.50406],[-73.543776,45.504468],[-73.543205,45.504748],[-73.543208,45.504459],[-73.543588,45.504229],[-73.543803,45.503903],[-73.543976,45.502317]]]]}'),4326)),3))::extensions.geography, 'Avenue Pierre-Dupuy et pont de la Concorde, Montréal', 'Ville-Marie', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2209', false, null, true),
