  ('parc-du-mont-royal', 'Parc du Mont-Royal', 'Profitez des sentiers et des espaces verts pour une marche dans la nature ou encore admirer le lac aux Castors et marcher jusqu’à la croix. Le parc est aussi une destination de choix pour se balader à pied, y pratiquer la course à pied ou sillonner les pistes cyclables En hiver, faites de la glissade sur chambre à air dans les corridors dédiés ou la piste de glissade libre. Venez profiter de la patinoire réfrigérée, des sentiers de raquette ainsi que des pistes de ski de fond. Afin de protéger les milieux naturels fragiles du site, il est important de demeurer dans les sentiers.', 'park', 45.5029564, -73.58918, 900, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.584891,45.514504],[-73.588088,45.515994],[-73.588347,45.516043],[-73.590561,45.515391],[-73.5912,45.514719],[-73.591606,45.514521],[-73.592031,45.514478],[-73.59686,45.514571],[-73.597368,45.514462],[-73.597863,45.514172],[-73.598898,45.513121],[-73.597512,45.513208],[-73.597177,45.513164],[-73.596942,45.51305],[-73.59678,45.512739],[-73.596883,45.512505],[-73.596902,45.51182],[-73.596715,45.511588],[-73.595687,45.511149],[-73.593938,45.510784],[-73.591509,45.509561],[-73.591304,45.509335],[-73.591352,45.508304],[-73.592846,45.506954],[-73.593479,45.50607],[-73.593849,45.50543],[-73.593983,45.50497],[-73.593961,45.504355],[-73.594124,45.50403],[-73.594839,45.503384],[-73.594533,45.503229],[-73.594767,45.503045],[-73.595682,45.502705],[-73.596981,45.502826],[-73.5985,45.501359],[-73.602077,45.498276],[-73.605474,45.494909],[-73.60481,45.494762],[-73.604149,45.494729],[-73.603523,45.494802],[-73.60277,45.495004],[-73.602782,45.495364],[-73.603532,45.495641],[-73.6037,45.496047],[-73.602955,45.496774],[-73.601735,45.496064],[-73.60124,45.496991],[-73.599543,45.497753],[-73.59867,45.497366],[-73.598437,45.497585],[-73.598079,45.497398],[-73