  ('college-dawson', 'Collège Dawson', null, 'campus', 45.4899219, -73.5882008, 100, null::extensions.geography, '3040 Rue Sherbrooke Ouest, Montréal H3Z 1A4', 'Ville-Marie', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2455', false, null, true),
  ('bibliotheque-pere-ambroise', 'Bibliothèque Père-Ambroise', 'La bibliothèque offre des collections et des services destinés aux jeunes, aux familles et aux adultes. Elle donne tous les jours accès à 8 postes informatiques, plusieurs tables de travail et 60 places assises.FabricathèqueÀ travers différentes activités, la fabricathèque de la bibliothèque vous permet d''explorer plusieurs technologies dont l''impression 3D, la modélisation et la robotique.', 'culture', 45.5228882, -73.5628815, 40, null::extensions.geography, '2093 Rue de la Visitation, Montréal H2L 3C9', 'Ville-Marie', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2469', false, null, true),
