  ('ecuries-dyouville', 'Écuries D’Youville', null, 'historic', 45.5013097, -73.5550104, 50, null::extensions.geography, '290 Place D''Youville, Montréal H2Y 2B6', 'Ville-Marie', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2608', false, null, true),
  ('edifice-aldred', 'Édifice Aldred', 'Oeuvre de l''agence d’architectes Barott and Blackader réalisé entre 1929 et 1931, l’édifice Aldred est commandé par la société financière Aldred and Co. Limited qui est liée à l’importante compagnie d’électricité Shawinigan Water and Power Company. John Edward Aldred est alors président de ces deux compagnies. Pour ériger ce gratte-ciel de 23 étages, il choisit un site prestigieux : la place d’Armes.', 'architecture', 45.5052681, -73.5567245, 60, null::extensions.geography, '501 Place d'' Armes, Montréal', 'Ville-Marie', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2609', false, null, true),
