  ('edifice-de-la-banque-royale', 'Édifice de la Banque Royale', null, 'historic', 45.5022627, -73.5591362, 50, null::extensions.geography, '360 Rue Saint-Jacques, Montréal H2Y 1P5', 'Ville-Marie', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2613', false, null, true),
  ('edifice-dominion-square', 'Édifice Dominion Square', null, 'historic', 45.5001817, -73.5721094, 50, null::extensions.geography, '1255 Rue Peel, Montréal H3B 4V4', 'Ville-Marie', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2614', false, null, true),
  ('edifice-dominique-ducharme', 'Édifice Dominique-Ducharme', null, 'historic', 45.4997279, -73.555126, 50, null::extensions.geography, '105 Rue McGill, Montréal H2Y 2E7', 'Ville-Marie', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2615', false, null, true),
  ('edifice-ernest-cormier', 'Édifice Ernest-Cormier', 'Cet édifice est construit entre 1922 et 1926 selon les plans des architectes Louis-Auguste Amos, Charles J. Saxe et Ernest Cormier. Il s’agit du premier contrat d’importance de ce dernier depuis son retour d’études à Paris. Peu après son décès, en 1980, son nom sera donné à l’édifice afin de marquer l’importance de cet architecte dans la société québécoise. Le projet est lancé en février 1920 lorsque le gouvernement du Québec sanctionne une loi sur la construction d’une deuxième « annexe » au palais de justice de Montréal.', 'historic', 45.5071144, -73.5543381, 50, null::extensions.geography, '100 Rue Notre-Dame Est, Montréal H2Y 4B6', 'Ville-Marie', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2616', false, null, true),
  ('place-bonaventure', 'Place Bonaventure', null, 'architecture', 45.4997215, -73.5654068, 100, null::extensions.geography, '800 Rue De La Gauchetière Ouest, Montréal H5A 1K6', 'Ville-Marie', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2618', false, null, true),
  ('edifice-gerald-godin', 'Édifice Gérald-Godin', null, 'historic', 45.4998499, -73.556845, 50, null::extensions.geography, '360 Rue McGill, Montréal', 'Ville-Marie', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2619', false, null, true),
  ('edifice-grand-tronc', 'Édifice Grand Tronc', 'L’édifice du Grand Tronc est construit entre 1899 et 1902. La Ville de Montréal cède des terrains à la compagnie de transport du Grand Tronc en 1899 en vertu d’une entente par laquelle la compagnie s’engage, entre autres, à maintenir son siège social canadien dans l’édifice pendant au moins vingt ans. Geste rare pour une entreprise anglo-canadienne, la compagnie du Grand Tronc confie la conception à un architecte américain, Richard A. Waite, plutôt qu’à un Britannique. Les travaux débutent au printemps 1899 après la destruction des bâtiments qui s’y trouvaient.', 'historic', 45.4998499, -73.556845, 50, null::extensions.geography, '360 Rue McGill, Montréal H2Y 2E9', 'Ville-Marie', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2620', false, null, true),
