  ('buste-de-jose-de-san-martin', 'Buste de José de San Martin', 'Art public : Toto, Carlos Maria, Buste de José de San Martin, 2000.', 'public-art', 45.4893646, -73.5808945, 25, null::extensions.geography, null, 'Ville-Marie', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2963', false, null, true),
  ('tour-de-lhorloge', 'Tour de l’Horloge', 'La Tour de l’horloge est construite en 1921-1922. Dans le cadre de travaux d’agrandissement des installations portuaires, la Commission du havre de Montréal décide de construire le long de la jetée Victoria un convoyeur à grains et des hangars. On décide également d’ériger une tour afin de commémorer les marins de la marine marchande morts durant la Première Guerre mondiale. La tour, coiffée d’une spectaculaire horloge et d’une lampe guidant les navires, permet en outre de masquer les volumineuses installations le long de la jetée Victoria.', 'historic', 45.5122423, -73.545692, 50, null::extensions.geography, 'Vieux-Port de Montréal, Montréal', 'Ville-Marie', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2964', false, null, true),
