  ('sans-titre-vermette-claude', 'Sans titre (Vermette, Claude)', 'Art public : Vermette, Claude, Sans titre, 2006.', 'public-art', 45.4984842, -73.5990951, 25, null::extensions.geography, null, 'Ville-Marie', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2974', false, null, true),
  ('vieux-seminaire-de-saint-sulpice', 'Vieux Séminaire de Saint-Sulpice', 'Résidence, manoir seigneurial, presbytère .... Le plus vieil immeuble du Vieux-Montréal, l''ancien séminaire a répondu à divers besoins durant sa longue histoire selon le rôle que son propriétaire unique, la Compagnie des Prêtres de Saint-Sulpice, jouait dans la société montréalaise. Le bâtiment actuel est le second que les Sulpiciens ont fait construire. Le premier avait été érigé en 1657 sur la rue Saint-Paul sur le site de l''actuel entrepôt de la compagnie Frothingham & Workman.', 'historic', 45.5041389, -73.5569077, 50, null::extensions.geography, '130 Rue Notre-Dame Ouest, Montréal H2Y 1T1', 'Ville-Marie', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2975', false, null, true),
