  ('monument-a-la-reine-victoria', 'Monument à la reine Victoria', 'Art public : Wood, Marshall, Monument à la reine Victoria, 1869.', 'public-art', 45.5014229, -73.5615845, 25, null::extensions.geography, null, 'Ville-Marie', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2982', false, null, true),
  ('hotel-de-ville-de-montreal', 'Hôtel de ville de Montréal', 'La construction de l''hôtel de ville de Montréal s''est déroulée sur plusieurs années. Les premiers travaux d''excavation ont lieu en 1872 et la construction de l''édifice proprement dit débute en 1874 d''après les plans des architectes Hutchison et Perrault. Finalement l''Hôtel de ville est inauguré le 11 mars 1878. L''inspiration stylistique vient de la France du Second Empire. Ce style architectural est utilisé à cette époque pour de nombreux édifices publics, notamment pour les hôtels de ville de New York et Philadelphie.', 'historic', 45.508838, -73.5541565, 70, null::extensions.geography, '275 Rue Notre-Dame Est, Montréal H2Y 1C6', 'Ville-Marie', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '2986', false, null, true),
