  ('auditorium-le-prevost', 'Auditorium Le Prévost', null, 'culture', 45.5440755, -73.6146545, 40, null::extensions.geography, '7355 Avenue Christophe-Colomb, Montréal H2R 2S5', 'Villeray–Saint-Michel–Parc-Extension', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3067', false, null, true),
  ('bibliotheque-de-parc-extension', 'Bibliothèque de Parc-Extension', 'Les gens y viennent pour lire, s’informer, emprunter un guide d’apprentissage du français, naviguer sur Internet ou assister aux activités organisées pour eux. Les jeunes sont invités à des heures du conte, des ateliers, des spectacles et des rencontres de toutes sortes. Certains adultes profitent même de leur visite pour pratiquer leur français en assistant à un atelier de conversation animé par un membre du personnel.Collection de livres multilinguesSaviez-vous que la bibliothèque possède environ 7600 livres dans d''autres langues que le français ou l''anglais?', 'culture', 45.5318697, -73.6301983, 40, null::extensions.geography, '421 Rue Saint-Roch, Montréal H3N 1K2', 'Villeray–Saint-Michel–Parc-Extension', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3068', false, null, true),
  ('bibliotheque-de-saint-michel', 'Bibliothèque de Saint-Michel', 'La bibliothèque de Saint-Michel a développé au fil des ans des collections et des services à l’écoute des jeunes lecteurs. Elle leur propose notamment des milliers de bandes dessinées, des centaines de mangas et des activités sur mesure pour eux. Elle offre en outre du soutien aux garderies et aux centres de la petite enfance en leur offrant des heures du conte.Pour nous contacterAdultes : 514 872-3899Jeunes : 514 872-4250', 'culture', 45.5623034, -73.6019599, 40, null::extensions.geography, '7601 Rue François-Perreault, Montréal H2A 3L6', 'Villeray–Saint-Michel–Parc-Extension', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3069', false, null, true),
