  ('parc-george-vernot', 'Parc George-Vernot', 'Situé au cœur de Saint-Michel dans VSP, le parc George-Vernot est en pleine transformation afin de moderniser les installations sportives et d''ajouter de nouveaux espaces de détente et de culture. Consultez la page consacrée à son réaménagement pour découvrir le projet et suivre l''avancée des travaux.', 'park', 45.5683577, -73.6151601, 115, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.61339,45.568427],[-73.615982,45.569569],[-73.616921,45.568527],[-73.614338,45.567382],[-73.61339,45.568427]]],[[[-73.617124,45.569847],[-73.616294,45.569481],[-73.61617,45.569609],[-73.617009,45.569974],[-73.617124,45.569847]]]]}'),4326)),3))::extensions.geography, null, 'Villeray–Saint-Michel–Parc-Extension', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3156', false, null, true),
