  ('parc-howard', 'Parc Howard', 'Le parc Howard est un lieu privilégié pour se détendre, profiter des attraits de la nature ou pratiquer des loisirs en plein air.Horaire du RoulivreLe Roulivre est en service tous les mardis de 15 h à 18 h.', 'park', 45.5340212, -73.6432852, 94, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.645112,45.534096],[-73.641929,45.533229],[-73.641658,45.533661],[-73.641684,45.533837],[-73.64197,45.534216],[-73.64479,45.534683],[-73.645112,45.534096]]]]}'),4326)),3))::extensions.geography, null, 'Villeray–Saint-Michel–Parc-Extension', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3158', false, null, true),
  ('parc-jarry', 'Parc Jarry', 'Découvrez un paysage nature en plein cœur de la ville et profitez des installations adaptées aux différentes saisons : piscine, pataugeoire, terrains de sport et aires de pique-nique. En hiver, un comptoir de location d’équipement est aussi ouvert les fins de semaine.', 'park', 45.5353889, -73.6282272, 367, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.623248,45.534877],[-73.62247,45.536201],[-73.631264,45.538762],[-73.634381,45.533361],[-73.625044,45.531821],[-73.624938,45.532001],[-73.627772,45.532472],[-73.628422,45.532554],[-73.628789,45.532485],[-73.628917,45.532823],[-73.62967,45.532681],[-73.629836,45.533117],[-73.629346,45.533209],[-73.629507,45.533632],[-73.629339,45.533663],[-73.629404,45.533834],[-73.629181,45.533876],[-73.629312,45.534221],[-73.627067,45.534586],[-73.626898,45.534139],[-73.625964,45.533864],[-73.623581,45.53431],[-73.623248,45.534877]]]]}'),4326)),3))::extensions.geography, '285 Rue Gary-Carter, Montréal H2R 2W1', 'Villeray–Saint-Michel–Parc-Extension', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3159', false, null, true),
