  ('parc-julie-hamelin', 'Parc Julie-Hamelin', 'Ce parc, judicieusement conçu afin de faciliter l’accès au jeu et au plein air pour tous, comprend : Une aire de jeu de 16 000 pi2 pour les 2-12 ans, inclusive pour tous les niveaux de motricité et de limitations (don de la Fondation Bon départ de Canadian Tire);Un terrain de basket-ball en béton adapté aux différents niveaux de joueurs et aux fauteuils roulants;Des jeux d’eau offrant un point de rafraîchissement;Une structure d’entraînement extérieur;Un sentier permettant le « BenchFit » pour la population vieillissante;Des anneaux d’entraînement pour les artistes du cirque;Une diversité de…', 'park', 45.5634308, -73.6170578, 68, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.616099,45.56336],[-73.617594,45.564014],[-73.6182,45.563338],[-73.616729,45.562696],[-73.616099,45.56336]]]]}'),4326)),3))::extensions.geography, null, 'Villeray–Saint-Michel–Parc-Extension', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3161', false, null, true),
