  ('parc-villeray', 'Parc Villeray', 'Venez profiter des nombreux équipements sportifs permettant notamment la pratique du basketball, du soccer, du football, du baseball, du tennis de table, de la course à pied et de la pétanque. Vous y trouverez également une aire d’exercice extérieure, ainsi que des tables à pique-nique et des bancs pour passer de beaux moments en plein air.', 'park', 45.5475426, -73.6212006, 165, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.624335,45.548123],[-73.61956,45.54598],[-73.61844,45.547239],[-73.622765,45.549169],[-73.624335,45.548123]]]]}'),4326)),3))::extensions.geography, null, 'Villeray–Saint-Michel–Parc-Extension', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3176', false, null, true),
