  ('parc-yvonne-maisonneuve', 'Parc Yvonne-Maisonneuve', 'Anciennement connu par l''appellation usuelle « parc Hutchison/des-Pins », le parc Hutchison-Avenue-des-Pins a changé de nom en mars 2017 pour honorer madame Yvonne Maisonneuve, fondatrice du Chaînon.', 'park', 45.5108651, -73.5780327, 40, null::extensions.geography, null, 'Le Plateau-Mont-Royal', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3323', false, null, true),
