  ('place-valentin-jautard', 'Place Valentin-Jautard', null, 'park', 45.539317, -73.5688872, 40, null::extensions.geography, null, 'Le Plateau-Mont-Royal', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3326', false, null, true),
  ('place-des-fleurs-de-macadam', 'Place des Fleurs-de-Macadam', 'Le site abritait anciennement une station-service opérée par Armand Ferland, le père du célèbre auteur-compositeur-interprète Jean-Pierre Ferland. La place porte le nom de la chanson Les Fleurs de Macadam pour cette raison.En plus des mécanismes de récupération des eaux de pluie, l''aménagement unique est constitué de jets de bruine à même les pierres de rivières, de végétaux variés, de mobilier et d''une oeuvre d''art suspendue de l''atelier En temps et lieu.', 'park', 45.5270736, -73.5797173, 120, null::extensions.geography, null, 'Le Plateau-Mont-Royal', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3327', false, null, true),
