  ('parc-daisy-peterson-sweeney', 'Parc Daisy-Peterson-Sweeney', 'Les citoyens sont invités à profiter pleinement de cet espace verdoyant juste à côté du marché, de la piste cyclable du canal de Lachine, pour faire le plein de nature, mais également, pour s’initier aux échecs.Découvrez les règles des échecs', 'park', 45.4803661, -73.5739135, 48, null::extensions.geography, null, 'Le Sud-Ouest', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3343', false, null, true),
  ('parc-david-lefebvre', 'Parc David-Lefebvre', 'Des zones permettant une variété d’activités et d’expériencesVenez vous entraîner dans le circuit d’exercice quatre saisons compte cinq appareils vous permettant d’exécuter une variété de mouvements complémentaires pour travailler votre cardio, votre flexibilité et vos muscles. Il est possible de programmer différents niveaux de défis grâce à des écrans tactiles alimentés en électricité par vos coups de pédales!Une zone de détente comprenant des chaises longues et des tables à pique-nique ainsi que des maisonnettes balancelles vous permet de vous détendre après votre entraînement.', 'park', 45.4862401, -73.5774956, 40, null::extensions.geography, null, 'Le Sud-Ouest', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3344', false, null, true),
  ('parc-des-ecluses-de-la-cote-saint-paul', 'Parc des Écluses-de-la-Côte-Saint-Paul', null, 'park', 45.465977, -73.5920053, 120, null::extensions.geography, null, 'Le Sud-Ouest', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3345', false, null, true),
  ('parc-gedeon-de-catalogne', 'Parc Gédéon-De Catalogne', 'Ce parc de détente est aussi un site de compostage collectif.On joue dans les parcsVenez bouger et vous amusez gratuitement dans les parc du Sud-Ouest. Consultez toutes les activités en cliquant ici.', 'park', 45.4719688, -73.5832682, 120, null::extensions.geography, null, 'Le Sud-Ouest', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3346', false, null, true),
  ('parc-philippe-lalonde', 'Parc Philippe-Lalonde', 'Éclairé à l’énergie solaire et muni d’un escalier et d’une rampe d’accès universel, cet espace vert répond aux impératifs environnementaux et aux enjeux d’accessibilité universelle. Les citoyens peuvent s’exercer sur un module d’escalade pour enfants et adultes constitué de 26 poteaux avec quatre parcours permettant de tester force motrice, coordination et équilibre. Ils peuvent aussi profiter des chaises longues pour une pause bien méritée ou des tables de pique-nique pour casser la croûte dans ce lieu enchanteur.Philippe-LalondeLe parc est nommé en l’honneur de M.', 'park', 45.4673772, -73.5917961, 40, null::extensions.geography, null, 'Le Sud-Ouest', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3347', false, null, true),
  ('parc-saint-henri', 'Parc Saint-Henri', 'Le parc Saint-Henri est un lieu privilégié pour se détendre, profiter des attraits de la nature ou pratiquer des loisirs en plein air.', 'park', 45.4800727, -73.5862956, 120, null::extensions.geography, null, 'Le Sud-Ouest', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3348', false, null, true),
  ('salle-desilets-du-cegep-marie-victorin', 'Salle Désilets du Cégep Marie-Victorin', 'Espace de vie culturelle bouillonnant, la salle Désilets propose tout au long de l''année une programmation artistique variée de grande qualité. Visitez son site web pour en apprendre davantage.', 'culture', 45.6178735, -73.60603, 40, null::extensions.geography, '7000 Rue Marie-Victorin, Montréal H1G 2J6', 'Rivière-des-Prairies–Pointe-aux-Trembles', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3355', false, null, true),
  ('place-publique-du-parc-saint-joseph', 'Place publique du parc Saint-Joseph', null, 'landmark', 45.6627762, -73.5626238, 60, null::extensions.geography, 'Boulevard Gouin Est et 68e Avenue, Montréal', 'Rivière-des-Prairies–Pointe-aux-Trembles', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3356', false, null, true),
  ('place-paul-dejean', 'Place Paul-Déjean', 'Cette place porte le nom de Paul Déjean (1931-2005) : Fondateur du Bureau de la communauté chrétienne des Haïtiens de Montréal (BCCHM), une oeuvre majeure à Montréal et au Québec.', 'landmark', 45.6390471, -73.5965619, 60, null::extensions.geography, null, 'Rivière-des-Prairies–Pointe-aux-Trembles', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3357', false, null, true),
  ('plage-de-lest', 'Plage de l''Est', 'Le site comprend un pavillon de service avec toilettes et douches, deux terrains de volleyball de plage, une promenade de béton éclairée à laquelle se greffent quelques escaliers et murets, une jetée, composée d''acier et de bois, qui s’amorce à proximité du pavillon et qui se prolonge vers le fleuve, un jeu d’eau intégré à la promenade de béton et un abri ouvert intégré à la jetée.La baignade n''est pas autorisée sur le site, mais on y retrouve des jeux d''eau.', 'park', 45.6984722, -73.4809858, 79, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.481359,45.698617],[-73.481443,45.698417],[-73.481155,45.69838],[-73.481262,45.698065],[-73.481161,45.698052],[-73.481221,45.697809],[-73.481309,45.697821],[-73.481353,45.697657],[-73.479818,45.69745],[-73.479247,45.698602],[-73.481359,45.698617]]]]}'),4326)),3))::extensions.geography, null, 'Rivière-des-Prairies–Pointe-aux-Trembles', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3358', false, null, true),
