  ('parc-ernest-rouleau', 'Parc Ernest-Rouleau', 'Profitez du belvédère couvert, du mobilier urbain tel des chaises longues, des bancs fixes, des bancs balançants et des tables dans ce parc des plus propices à la détente. Vous y trouverez aussi une aire d’exerciseurs urbains, des panneaux d’interprétation, une borne de réparation de vélo ainsi que des arbres matures. Une station Bixi électrifiée est installée aux abords du parc.Rappelons que l''aménagement du parc Ernest-Rouleau, appelé projet Fenêtre sur la rivière, est l''un des deux projets choisis par les citoyens à la suite de la démarche participative Transformons nos parcs!', 'park', 45.631928, -73.6154526, 70, extensions.st_multi(extensions.st_collectionextract(extensions.st_makevalid(extensions.st_setsrid(extensions.st_geomfromgeojson('{"type":"MultiPolygon","coordinates":[[[[-73.614598,45.632607],[-73.614605,45.632489],[-73.614859,45.632359],[-73.614927,45.632404],[-73.615026,45.632296],[-73.615204,45.632421],[-73.615395,45.632363],[-73.616265,45.631814],[-73.616646,45.631691],[-73.616417,45.631241],[-73.615864,45.631521],[-73.616206,45.631855],[-73.616104,45.631908],[-73.615987,45.631949],[-73.615635,45.631618],[-73.614035,45.632394],[-73.61449,45.632827],[-73.614598,45.632607]]],[[[-73.609573,45.635194],[-73.60913,45.635446],[-73.609458,45.635774],[-73.609869,45.635541],[-73.609573,45.635194]]],[[[-73.608497,45.636461],[-73.60865,45.636332],[-73.608233,45.635957],[-73.608051,45.636061],[-73.608497,45.636461]]]]}'),4326)),3))::extensions.geography, null, 'Rivière-des-Prairies–Pointe-aux-Trembles', 'montreal-lieux-interet', 'https://donnees.montreal.ca/dataset/lieux-d-interet', 'CC-BY-4.0', '3366', false, null, true),
